        except Exception:
            items = []

    # If no keys are supplied, return all values
    if not keys:
        return [v for _, v in items]

    # Otherwise filter according to the provided keys (ints or actual keys)
    result = []
    for key in keys:
        if isinstance(key, int):
            # index‑based lookup
            if 0 <= key < len(items):
                result.append(items[key][1])
