    return result

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Try to obtain the field names and values from the record.
    try:
        fields = getattr(self, "_fields")
    except AttributeError:
        # Fallback: if object behaves like a mapping, use its keys
        try:
            fields = list(self.keys())
        except Exception:
            fields = []

    try:
        values = getattr(self, "_values")
    except AttributeError:
        # Fallback: if object behaves like a sequence of values
        try:
            values = list(self.values())
        except Exception:
            values = []

    # Build a base dictionary mapping field name to value.
    base = dict(zip(fields, values))

    # If no specific keys requested, return the entire mapping.
    if not keys:
        return dict(base)

    result = {}
    for key in keys:
        # Determine whether key is an integer index.
        is_index = False
        try:
            idx = int(key)
            is_index = True
        except Exception:
            is_index = False

        if is_index:
            if idx < 0 or idx >= len(values):
                raise IndexError(f"Index {idx} out of range for record with {len(values)} values")
            # Get the corresponding field name, if available.
            if idx < len(fields):
                field_name = fields[idx]
                result[field_name] = values[idx]
            else:
                # No field name for this index; skip or use numeric key.
                result[f"field_{idx}"] = values[idx]
        else:
            # Treat key as field name.
            if key in base:
                result[key] = base[key]
            else:
                # Field name not present: insert None per specification.
                result[key] = None

    return result

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Helper to retrieve items in order
    try:
        # Common pattern: a list of (key, value) tuples
        items = list(self._items)
    except AttributeError:
        try:
            items = list(self.items())
        except AttributeError:
            try:
                items = list(self)
            except TypeError:
                # If we cannot iterate, return empty dict
                return {}

    key_list = [k for k, _ in items]
    val_list = [v for _, v in items]

    def _get_by_index(i):
        if i < 0 or i >= len(key_list):
            raise IndexError(f"Index {i} out of bounds for record with {len(key_list)} items")
        return key_list[i], val_list[i]

    # No filtering requested: return full dictionary
    if not keys:
        return dict(items)

    result = {}
    for key in keys:
        if isinstance(key, int):
            k, v = _get_by_index(key)
            result[k] = v
        else:
            if key in key_list:
                idx = key_list.index(key)
                result[key] = val_list[idx]
            else:
                result[key] = None
    return result

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Retrieve field names (keys) and corresponding values from the record.
    # Different implementations may expose these under different attribute names,
    # so we try a few common ones.
    if hasattr(self, 'keys'):
        field_names = getattr(self, 'keys')
    elif hasattr(self, 'columns'):
        field_names = getattr(self, 'columns')
    elif hasattr(self, 'fields'):
        field_names = getattr(self, 'fields')
    else:
        raise AttributeError(
            "Record object must expose field names via 'keys', 'columns', or 'fields'"
        )

    if hasattr(self, 'values'):
        values = getattr(self, 'values')
    elif hasattr(self, 'data'):
        values = getattr(self, 'data')
    elif hasattr(self, 'items'):
        values = getattr(self, 'items')
    else:
        raise AttributeError(
            "Record object must expose values via 'values', 'data', or 'items'"
        )

    if len(field_names) != len(values):
        raise ValueError("Number of field names does not match number of values")

    # If no specific keys were requested, return all.
    if not keys:
        return dict(zip(field_names, values))

    result = {}
    for key in keys:
        # Index-based request
        if isinstance(key, int):
            if key < 0 or key >= len(values):
                raise IndexError(
                    f"Index {key} out of bounds for record with {len(values)} items"
                )
            result[field_names[key]] = values[key]
        # Name-based request
        else:
            if key in field_names:
                idx = field_names.index(key)
                result[key] = values[idx]
            else:
                # Key not found -> None
                result[key] = None
    return result

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
