    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Attempt to obtain a mapping of the record's data
    try:
        # If the object itself is dict-like
        data_map = dict(self)
    except Exception:
        # Fallback: use the object's __dict__ if available
        if hasattr(self, "__dict__"):
            data_map = dict(self.__dict__)
        else:
            raise TypeError("Object does not provide a mapping of its data.")

    # Preserve order of items for index lookup
    items = list(data_map.items())
    key_list = [k for k, v in items]

    if not keys:
        # No filtering requested; return a shallow copy of the data
        return {k: v for k, v in items}

    result = {}
    lookup = dict(items)

    for key in keys:
        if isinstance(key, int):
            # Handle negative indices as in list semantics
            if key < 0:
                key = len(items) + key
            if key < 0 or key >= len(items):
                raise IndexError(f"Index {key} out of bounds for record with {len(items)} items.")
            col_key = key_list[key]
            result[col_key] = items[key][1]
        else:
            # Lookup by key, insert None if missing
            result[key] = lookup.get(key, None)

    return result

def data(self, *keys):
        """ Return the keys and values of this record as a dictionary,
        optionally including only certain values by index or key. Keys
        provided in the items that are not in the record will be
        inserted with a value of :const:`None`; indexes provided
        that are out of bounds will trigger an :exc:`IndexError`.

        :param keys: indexes or keys of the items to include; if none
                      are provided, all values will be included
        :return: dictionary of values, keyed by field name
        :raises: :exc:`IndexError` if an out-of-bounds index is specified
        """
        # First gather all items from the record in a list of (key, value) tuples.
        # Try to use dict-like interface first, otherwise fall back to iterating
        # over the object itself.
        if hasattr(self, "items") and callable(self.items):
            try:
                items = list(self.items())
            except Exception:
                # In case items() does not return key/value tuples
                items = []
                for k in self:
                    try:
                        v = self[k]
                        items.append((k, v))
                    except Exception:
                        pass
        else:
            items = []
            try:
                # Assume self is iterable over (key, value) pairs
                for kv in self:
                    if isinstance(kv, tuple) and len(kv) == 2:
                        items.append(kv)
                    else:
                        # Could be object with attributes key and value
                        if hasattr(kv, "key") and hasattr(kv, "value"):
                            items.append((kv.key, kv.value))
            except Exception:
                # maybe mapping-like
                if hasattr(self, "__getitem__"):
                    try:
                        for k in self:
                            items.append((k, self[k]))
                    except Exception:
                        pass

        # Build a lookup for keys to values for quick access when keys are provided
        key_lookup = {k: v for k, v in items}

        # If no specific keys are requested, return all items
        if not keys:
            return dict(items)

        # Build result dictionary according to requested keys / indices
        result = {}
        for key in keys:
            # If key is an integer, treat as index
            if isinstance(key, int):
                if key < 0 or key >= len(items):
                    raise IndexError(f"Index {key} out of bounds (0-{len(items)-1})")
                k, v = items[key]
                result[k] = v
            else:
                # Treat as a key lookup
                if key in key_lookup:
                    result[key] = key_lookup[key]
                else:
                    result[key] = None

        return result

def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                hydration_hooks=None, **handlers):
    """Appends a DISCARD message to the output queue.

    :param n: number of records to discard, default = -1 (ALL)
    :param qid: query ID to discard for, default = -1 (last query)
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    """
    # Normalize hooks to dictionaries
    dehydration_hooks = dehydration_hooks or {}
    hydration_hooks = hydration_hooks or {}

    # Basic type checking to avoid runtime errors
    if not isinstance(dehydration_hooks, dict):
        raise TypeError("dehydration_hooks must be a dict")
    if not isinstance(hydration_hooks, dict):
        raise TypeError("hydration_hooks must be a dict")
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if not isinstance(qid, int):
        raise TypeError("qid must be an integer")

    # Build the DISCARD message dictionary
    msg = {
        "type": "DISCARD",
        "qid": qid,
        "n": n,
        "dehydration_hooks": dehydration_hooks,
        "hydration_hooks": hydration_hooks,
    }

    # Append the message to the output queue safely
    try:
        if hasattr(self, "output_queue"):
            queue = self.output_queue
        elif hasattr(self, "queue"):
            queue = self.queue
        else:
            # Fall back to a newly created list if none exists
            queue = []
            self.output_queue = queue
        queue.append(msg)
    except Exception as exc:
        # Log or propagate error as needed; here we raise a RuntimeError
        raise RuntimeError(f"Failed to append DISCARDis message to queue: {exc}") from exc

    # Return a Response object initialized with any handlers if Response is defined
    try:
        return Response(**handlers)
    except NameError:
        # If Response class is not defined, return the message queue reference
        # so callers can inspect it; or simply return None
        return None

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
          db=None, imp_user=None, dehydration_hooks=None,
          hydration_hooks=None, **handlers):
    """Appends a BEGIN message to the output queue.

    Parameters:
        mode (str): access mode for routing - "READ" or "WRITE" (default)
        bookmarks (iterable): bookmark values after which this transaction should begin
        metadata (dict): custom metadata dictionary to attach to the transaction
        timeout (float): timeout for transaction execution (seconds)
        db (str): name of the database against which to begin the transaction
            Requires Bolt 4.0+.
        imp_user (str): the user to impersonate
            Requires Bolt 4.4+
        dehydration_hooks (dict): Hooks to dehydrate types (dict from type
            (class) to dehydration function). Dehydration functions receive
            the value and return an object of type understood by packstream.
        hydration_hooks (dict): Hooks to hydrate types (mapping from type
            (class) to dehydration function). Dehydration functions receive
            the value of type understood by packstream and are free to return any
            object.
        handlers: handler functions passed into the returned Response object
    Returns:
        Response object
    """
    # Validate mode
    if mode is not None:
        mode_val = mode.upper()
        if mode_val not in ("READ", "WRITE"):
            raise ValueError("mode must be 'READ' or 'WRITE'")
    else:
        mode_val = None

    # Validate bookmarks
    if bookmarks is not None:
        try:
            bookmarks_val = list(bookmarks)
        except Exception as exc:
            raise TypeError("bookmarks must be an iterable") from exc
    else:
        bookmarks_val = None

    # Validate timeout
    if timeout is not None and not isinstance(timeout, (int, float)):
        raise TypeError("timeout must be a number")

    # Merge hooks into the connection's settings
    if dehydration_hooks is not None:
        if not isinstance(dehydration_hooks, dict):
            raise TypeError("dehydration_hooks must be a dict")
        self.dehydration_hooks.update(dehydration_hooks)
    if hydration_hooks is not None:
        if not isinstance(hydration_hooks, dict):
            raise TypeError("hydration_hooks must be a dict")
        self.hydration_hooks.update(hydration_hooks)

    # Build the payload for the BEGIN packet
    payload = {}
    if mode_val:
        payload["mode"] = mode_val
    if bookmarks_val:
        payload["bookmarks"] = bookmarks_val
    if metadata:
        payload["metadata"] = metadata
    if timeout:
        payload["timeout"] = timeout
    if db:
        payload["database"] = db
    if imp_user:
        payload["impersonated_user"] = imp_user

    # Send the BEGIN packet
    try:
        self._enqueue_packet(self.BEGIN, payload)
    except AttributeError as exc:
        raise RuntimeError("Unable to enqueue BEGIN packet") from exc

    # Return the response object
    return Response(self, **handlers)

