        # Validate dehydration / hydration hooks
        if dehydration_hooks is not None and not isinstance(dehydration_hooks, dict):
            raise TypeError('dehydration_hooks must be a dictionary')
        if hydration_hooks is not None and not isinstance(hydration_hooks, dict):
            raise TypeError('hydration_hooks must be a dictionary')
        # Validate handlers mapping
        if not isinstance(handlers, dict):
            raise TypeError('handlers must be a mapping of handler names to callables')

        # Build BEGIN message
        message = {'type': 'BEGIN', 'mode': mode}
        if bookmarks:
            message['bookmarks'] = bookmarks
        if metadata:
            message['metadata'] = metadata
        if timeout is not None:
            message['timeout'] = float(timeout)
        if db is not None:
            message['db'] = db
        if imp_user is not None:
            message['imp_user'] = imp_user
        if dehydration_hooks:
            message['dehydration_hooks'] = dehydration_hooks
        if hydration_hooks:
            message['hydration_hooks'] = hydration_hooks

        # Append to the output queue
        try:
            self._out.append(message)
        except AttributeError as exc:
            raise RuntimeError('Output queue (_out) not initialized') from exc

        # Return a Response object
