def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
          db=None, imp_user=None, dehydration_hooks=None,
          hydration_hooks=None, **handlers):
    """
    Appends a BEGIN message to the output queue.

    :param mode: access mode for routing - "READ" or "WRITE" (default)
    :param bookmarks: iterable of bookmark values after which this transaction should begin
    :param metadata: custom metadata dictionary to attach to the transaction
    :param timeout: timeout for transaction execution (seconds)
    :param db: name of the database against which to begin the transaction
        Requires Bolt 4.0+.
    :param imp_user: the user to impersonate
        Requires Bolt 4.4+
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    :return: Response object
    """
    # Default mode to WRITE if not specified
    mode = mode or "WRITE"

    # Assemble payload for the BEGIN message
    payload = {"mode": mode}
    if bookmarks:
        try:
            payload["bookmarks"] = list(bookmarks)
        except TypeError:
            raise ValueError("bookmarks must be an iterable of bookmark values")
    if metadata is not None:
        if not isinstance(metadata, dict):
            raise TypeError("metadata must be a dictionary")
        payload["metadata"] = metadata
    if timeout is not None:
        if not isinstance(timeout, (int, float)):
            raise TypeError("timeout must be a number (seconds)")
        payload["timeout"] = float(timeout)
    if db:
        payload["database"] = db
    if imp_user:
        payload["impersonated_user"] = imp_user
    if dehydration_hooks:
        if not isinstance(dehydration_hooks, dict):
            raise TypeError("dehydration_hooks must be a dictionary")
        payload["dehydrate"] = dehydration_hooks
    if hydration_hooks:
        if not isinstance(hydration_hooks, dict):
            raise TypeError("hydration_hooks must be a dictionary")
        payload["hydrate"] = hydration_hooks

    # Merge any additional handler arguments
    payload.update(handlers)

    # Append the BEGIN command to the internal output queue
    try:
        # The queue may be called _output, _out_queue, or something similar.
        # We hope that one of these exists; otherwise we raise an error.
        if hasattr(self, "_output"):
            self._output.append(("BEGIN", payload))
        elif hasattr(self, "_out_queue"):
            self._out_queue.append(("BEGIN", payload))
        else:
            raise AttributeError("Unable to locate transaction output queue.")
    except Exception as exc:
        # Wrap any exception that occurs during queue append.
        raise RuntimeError(f"Failed to append BEGIN message: {exc}") from exc

    # Return a lightweight Response placeholder. In a full implementation,
    # this would likely be an instance of a Response class provided by the
    # surrounding framework.
    class _DummyResponse:
        def __init__(self, payload):
            self.payload = payload

        def __repr__(self):
            return f"<BeginResponse payload={self.payload!r}>"

    return _DummyResponse(payload)

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Validate arguments
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    if not isinstance(fields, (list, tuple)):
        raise TypeError("fields must be a list or tuple")
    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dict")

    # Ensure field definitions are (name, type) tuples
    field_names = []
    for entry in fields:
        if not (isinstance(entry, tuple) and len(entry) == 2):
            raise ValueError("Each field must be a (name, type) tuple")
        fname, _ = entry
