def point_type(name, fields, srid_map):
    """Dynamically create a Point subclass.

    Parameters
    ----------
    name : str
        Name of the subclass to create.
    fields : dict
        Mapping of field names (str) to their expected types.
    srid_map : dict
        Mapping of subclass names to SRID values.

    Returns
    -------
    type
        A new subclass of :class:`Point` with the given fields and SRID.
    """
    # Validate signature
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    if not isinstance(fields, dict):
        raise TypeError("fields must be a dict")
    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dict")

    # The base class must exist in the current namespace.
    try:
        base_cls = Point
    except NameError as exc:
        raise NameError("Base class 'Point' is not defined in the current context.") from exc

    # Prepare annotations and default values
    annotations = {}
    defaults = {}
    for key, typ in fields.items():
        if not isinstance(key, str):
            raise TypeError(f"Field name {key!r} is not a string")
        annotations[key] = typ
        defaults[key] = None

    # Resolve SRID for this subclass
    srid_value = srid_map.get(name)

    def __init__(self, *args, **kwargs):
        """Initialize a point instance with the defined fields."""
        # Accept positional arguments in the order of the fields dictionary.
        if args:
            if len(args) > len(fields):
                raise TypeError(f"{name} expected at most {len(fields)} positional arguments, got {len(args)}")
            for field_name, value in zip(fields, args):
                setattr(self, field_name, value)

        # Merge keyword arguments with defaults
        for field_name in fields:
            if field_name in kwargs:
                setattr(self, field_name, kwargs.pop(field_name))
            else:
                setattr(self, field_name, defaults[field_name])

        # If any unexpected keyword arguments remain, raise an error.
        if kwargs:
            unexpected = ", ".join(kwargs.keys())
            raise TypeError(f"Unexpected keyword arguments: {unexpected}")

        # Store the SRID on the instance
        self.srid = srid_value

    # Assemble the class dictionary
    class_dict = {
        "__init__": __init__,
        "__annotations__": annotations,
        "srid": srid_value,
        "__module__": __name__,
    }
    class_dict.update(defaults)  # set default attributes on the class

    # Dynamically create and return the subclass
    return type(name, (base_cls,), class_dict)

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        def wrapped(*args, **kwargs):
            # Emit a deprecation warning on each call
            warnings.warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        # Preserve function metadata
        wrapped.__name__ = func.__name__
        wrapped.__doc__ = func.__doc__
        wrapped.__module__ = func.__module__
        wrapped.__annotations__ = getattr(func, "__annotations__", {})
        wrapped.__dict__.update(func.__dict__)
        return wrapped
    return decorator

