def _inline_r_setup(code: str) -> str:
    """
    Some behaviour of R cannot be configured via env variables, but can
    only be configured via R options once R has started. These are set here.
    """
    if not isinstance(code, str):
        raise TypeError(f"code must be a str, got {type(code).__name__}")

    # R options to control numeric representation, output format, etc.
    options = [
        "options(scipen=999)",           # Avoid scientific notation
        "options(digits=15)",            # Increase numeric precision
        "options(stringsAsFactors=FALSE)"  # Consistent string behavior
    ]

    # Strip any leading/trailing whitespace from the input code
    cleaned_code = code.strip()

    # If code is empty, just return the options
    if not cleaned_code:
        return "\n".join(options)

    # Prepend the options to the user's code
    return "\n".join(options + ["", cleaned_code])

def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""

    # Ensure the object is a sequence of strings
    try:
        items = list(seq)
    except Exception as exc:
        raise TypeError("Input must be a sequence of strings") from exc

    # Validate that all elements are strings
    for idx, item in enumerate(items):
        if not isinstance(item, str):
            raise TypeError(f"Element at position {idx} is not a string")

    n = len(items)
    if n <= 1:
        return items

    # Create a deterministic seed from the content of the items
    seed = 0
    for s in items:
        for ch in s:
            seed = (seed * 31 + ord(ch)) & 0xffffffff

    # Linear Congruential Generator parameters (common values)
    a = 1664525
    c = 1013904223
    m = 2**32

    def _rand() -> int:
        nonlocal seed
        seed = (a * seed + c) % m
        return seed

    # Fisher–Yates shuffle using our deterministic RNG
    for i in range(n - 1, 0, -1):
        j = _rand() % (i + 1)
        items[i], items[j] = items[j], items[i]

    return items

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError("Expected a string, got %r" % type(s).__name__)
    if not s:
        return ()
    # Replace common separators with a period to simplify splitting
    s_clean = s.replace('-', '.').replace('_', '.')
    parts: list[int] = []
    for part in s_clean.split('.'):
        if part.isdigit():
            parts.append(int(part))
        else:
            # extract leading numeric portion
            num_str = ''
            for ch in part:
                if ch.isdigit():
                    num_str += ch
                else:
                    break
            if num_str:
                parts.append(int(num_str))
            else:
                # non‑numeric segment, treat as zero
                parts.append(0)
    return tuple(parts)

