    # Try regex extraction of all digit sequences
    try:
        re_mod = __import__('re')
        nums = re_mod.findall(r'\d+', s)
        if not nums:
            return ()
        return tuple(int(n) for n in nums)
    except Exception:
        # Fallback to simple splitting on common separators
        parts = s.replace('-', '.').replace('_', '.').split('.')
        nums = []
        for part in parts:
            if part.isdigit():
