def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    import os, sys

    # Return original if empty
    if not cmd:
        return cmd

    # Convert to list for manipulation
    new_cmd = list(cmd)

    if os.name == 'nt':
        # Handle shebang: if the first argument is a script with a shebang,
        # insert the interpreter at the beginning.
        script = new_cmd[0]
        if isinstance(script, str) and os.path.isfile(script):
            try:
                with open(script, 'rb') as f:
                    first_line = f.readline().decode(errors='ignore')
                if first_line.startswith('#!'):
                    # Extract interpreter and any arguments
                    parts = first_line[2:].strip().split()
                    if parts:
                        interpreter = parts[0]
                        shebang_args = parts[1:]
                    else:
                        interpreter = ''
                        shebang_args = []

                    # If interpreter is a simple name (e.g., python), use the
                    # current interpreter if the name matches
                    if interpreter and interpreter.lower() in ('python', 'python3', 'python2'):
                        interpreter = sys.executable
                    # Quote paths that contain spaces
                    if interpreter and ' ' in interpreter and not (interpreter.startswith('"') and interpreter.endswith('"')):
                        interpreter = f'"{interpreter}"'
                    # Build new command
                    new_cmd = [interpreter] + shebang_args + [script] + new_cmd[1:]
            except Exception:
                # If anything goes wrong (not a file, read error, etc.), ignore
                pass

        # Wrap any argument that contains spaces and is not already quoted
        def quote_if_needed(arg: str) -> str:
            if not isinstance(arg, str):
                return arg
            if ' ' in arg and not (arg.startswith('"') and arg.endswith('"')):
                return f'"{arg}"'
            return arg

        new_cmd = [quote_if_needed(arg) for arg in new_cmd]

    return tuple(new_cmd)

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    import os
    import sys

    if not isinstance(cmd, (tuple, list)):
        raise TypeError(f"cmd must be a tuple (or list) of strings, got {type(cmd).__name__}")
    for a in cmd:
        if not isinstance(a, str):
            raise TypeError(f"command elements must be strings, got {type(a).__name__}")

    # Nothing to normalise on non‑Windows platforms
    if os.name != 'nt':
        return tuple(cmd)

    # Quote arguments that need quoting on Windows
    def _quote(arg: str) -> str:
        if not arg or any(ch in arg for ch in ' \t"\\'):
            # escape backslashes before a quote
            escaped = arg.replace('\\', '\\\\')
            escaped = escaped.replace('"', r'\"')
            return f'"{escaped}"'
        return arg

    new_cmd = tuple(_quote(a) for a in cmd)

    # Handle shebang scripts (deep‑path shebangs)
    script = cmd[0]
    if (
        os.path.isfile(script)
        and script.lower().endswith('.py')
    ):
        try:
            with open(script, 'rb') as f:
                first_line = f.readline().decode(errors='ignore')
            if first_line.startswith('#!') and 'python' in first_line.lower():
                # Replace script with interpreter
                return (sys.executable, script) + tuple(cmd[1:])
        except Exception:
            # ignore any IO errors
            pass

    return new_cmd

