def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorator(func):
        if maxsize <= 0:
            return func  # do nothing

        cache = {}
        recency = []

        def _make_key(args, kwd):
            key = args
            if kwd:
                items = tuple(sorted(kwd.items()))
            else:
                items = ()
            if typed:
                key = args + tuple(type(v) for v in args)
                items = items + tuple((k, type(v)) for k, v in sorted(kwd.items()))
            return (key, items)

        def wrapper(*args, **kwd):
            key = _make_key(args, kwd)
            entry = cache.get(key)
            now = timer()
            if entry is not None:
                value, expire = entry
                if expire > now:
                    # Move key to end to denote recent use
                    try:
                        recency.remove(key)
                    except ValueError:
                        pass
                    recency.append(key)
                    return value
                else:
                    # Expired
                    del cache[key]
                    try:
                        recency.remove(key)
                    except ValueError:
                        pass
            # compute new value
            result = func(*args, **kwd)
            cache[key] = (result, now + ttl)
            recency.append(key)
            # Evict oldest if necessary
            if len(cache) > maxsize:
                oldest = recency.pop(0)
                cache.pop(oldest, None)
            return result

        return wrapper
    return decorator

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    if not isinstance(maxsize, int):
        raise TypeError("maxsize must be an int or 0")
    if maxsize < 0:
        raise ValueError("maxsize must be >= 0")
    if not isinstance(typed, bool):
        raise TypeError("typed must be a bool")

    def decorator(func):
        import collections
        import functools
        cache = collections.OrderedDict()
        hits = misses = 0
        lock = None
        # helper to create cache key
        def _make_key(args, kwds, typed):
            key = args
            if kwds:
                # use ordered tuple of sorted items
                key += tuple(sorted(kwds.items()))
            if typed:
                key += tuple(type(v) for v in args)
                if kwds:
                    key += tuple(type(v) for k, v in sorted(kwds.items()))
            return key

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            if maxsize == 0:
                return func(*args, **kwargs)
            try:
                key = _make_key(args, kwargs, typed)
            except Exception:
                # If key creation fails due to unhashable, skip cache
                return func(*args, **kwargs)
            # thread safety if needed
            if lock is not None:
                with lock:
                    result = cache.get(key, None)
                    if key in cache:
                        hits += 1
                        # move to end to mark as most recent
                        cache.move_to_end(key)
                        return result
                    # cache miss
                    misses += 1
                    result = func(*args, **kwargs)
                    cache[key] = result
                    # evict most recently used if cache exceeded
                    if len(cache) > maxsize:
                        # pop MRU: last item
                        cache.popitem(last=True)
                    return result
            else:
                result = cache.get(key, None)
                if key in cache:
                    hits += 1
                    cache.move_to_end(key)
                    return result
                misses += 1
                result = func(*args, **kwargs)
                cache[key] = result
                if len(cache) > maxsize:
                    cache.popitem(last=True)
                return result

        def cache_clear():
            nonlocal hits, misses
            cache.clear()
            hits = misses = 0

        def cache_info():
            """Return cache statistics"""
            return dict(hits=hits, misses=misses,
                         maxsize=maxsize, currsize=len(cache))

        wrapper.cache_clear = cache_clear
        wrapper.cache_info = cache_info
        return wrapper

    return decorator

