            if callable(key):
                try:
                    k = key(*args, **kwargs)
                except Exception:
                    k = (args, tuple(sorted(kwargs.items())))
            else:
                k = (args, tuple(sorted(kwargs.items())))
            # Acquire lock if provided
            if lock:
                # Try to use context manager style
                acquire = getattr(lock, "acquire", None)
                release = getattr(lock, "release", None)
                if acquire and release:
                    acquire()
                else:
                    # Assume lock is a context manager
                    try:
                        lock.__enter__()
                    except AttributeError:
                        pass
            try:
                if k in cache:
                    return cache[k]
                result = func(*args, **kwargs)
                cache[k] = result
                return result
            finally:
                if lock:
                    if acquire and release:
                        release()
                    else:
                        try:
                            lock.__exit__(None, None, None)
                        except AttributeError:
                            pass
