            try:
                k = key(*args, **kwargs)
            except Exception:
                # Fall back to default hashkey if the key function fails
                k = hashkey(*args, **kwargs)

            # Retrieve from cache if available
            if lock:
                with lock:
                    cached = cache.get(k)
            else:
                cached = cache.get(k)

            if cached is not None:
                return cached

            # Call the underlying function
            result = func(*args, **kwargs)

            # Store the result in cache
            if lock:
                with lock:
                    cache[k] = result
            else:
                cache[k] = result

            return result
        return wrapper
    return decorator

def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception.
    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """
    import traceback
    import os
    import re

    if not isinstance(e, BaseException):
        raise TypeError("e must be an exception instance.")

    try:
        limit = int(max_level)
    except Exception:
        limit = 30
    if limit < 1:
        limit = 30

    try:
        max_path = int(max_path_level)
    except Exception:
        max_path = 5
    if max_path < 1:
        max_path = 5

    def truncate_path(path, max_parts):
        parts = path.split(os.sep)
        if len(parts) > max_parts:
            return os.sep.join(['...'] + parts[-max_parts:])
        return path

    tb_lines = traceback.format_exception(type(e), e, e.__traceback__, limit=limit)

    def process_line(line):
        return re.sub(
            r'File "([^"]+)"',
            lambda m: f'File "{truncate_path(m.group(1), max_path)}"',
            line,
        )

    processed = [process_line(l) for l in tb_lines]
    return ''.join(processed)

