        raise TypeError("minimalBases expects a list (or tuple) of classes")
    for c in classes:
        if not isinstance(c, type):
            raise TypeError(f"Element {c!r} is not a class")
    # Determine which classes are superclasses of any other in the list
    to_drop = set()
    for base in classes:
        for other in classes:
            if base is other:
                continue
            try:
                if issubclass(other, base):
                    to_drop.add(base)
                    break
            except Exception:
                # If the relationship cannot be determined, ignore
                pass
    # Preserve original order
    return [c for c in classes if c not in to_drop]

