    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Validate that `classes` is iterable
    try:
        iter(classes)
    except TypeError:
        raise TypeError("The `classes` argument must be an iterable of types.")
    # Remove duplicates while preserving order
    seen = set()
    unique = []
    for c in classes:
        if not isinstance(c, type):
            raise TypeError(f"Element {c!r} is not a class type.")
        if c not in seen:
            seen.add(c)
            unique.append(c)
    # Build minimal set: keep only classes that are not superclasses of any others
    minimal = []
    for c in unique:
        if any(issubclass(d, c) and d is not c for d in unique):
            # `c` is a superclass of another class in the list, so skip it
            continue
        minimal.append(c)
    return minimal

