def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    # Most classes that provide an interface expose a class‑level dictionary
    # called ATTRIBUTES (or INTERFACE) mapping attribute name → description.
    # This helper collects those mappings from the hierarchy (so inherited
    # attributes are included) and returns them as a list of tuples.
    # The ``all`` parameter is kept for compatibility with older code that
    # expected to filter optional attributes; it is not used here because
    # the interface dictionary already contains the complete specification.
    interface = getattr(self.__class__, "ATTRIBUTES", None)
    if interface is None:
        interface = getattr(self.__class__, "INTERFACE", None)
    if interface is None:
        # No interface defined – return an empty list
        return []

    # Merge dictionaries from base classes, giving precedence to subclasses
    attrs = {}
    for cls in reversed(self.__class__.__mro__):
        if hasattr(cls, "ATTRIBUTES"):
            attrs.update(getattr(cls, "ATTRIBUTES"))
        elif hasattr(cls, "INTERFACE"):
            attrs.update(getattr(cls, "INTERFACE"))

    # The mapping may be a simple dict or a collection of objects that
    # expose ``name`` and ``description`` attributes.
    if isinstance(attrs, dict):
        return list(attrs.items())
    else:
        # Fallback: try to extract name/description from each element
        out = []
        for item in attrs:
            name = getattr(item, "name", None) or getattr(item, "id", None)
            desc = getattr(item, "description", None) or getattr(item, "desc", None)
            if name is not None and desc is not None:
                out.append((name, desc))
        return out

