            for cls in self.__class__.mro():
                if hasattr(cls, "ATTRIBS"):
                    collect_from.append(cls.ATTRIBS)
        else:
            if hasattr(self.__class__, "ATTRIBS"):
                collect_from.append(self.__class__.ATTRIBS)

        # NOTE: ATTRIBS may be a list, tuple, set or dict --
        # we support key- or value- based extraction.
        names = set()
        for attr in collect_from:
            if isinstance(attr, dict):
                names.update(attr.keys())
            else:
                try:
