        # This will at least return the attributes present on the
        # instance itself, i.e. those that have been realized.
        pass

    # Fallback: return all public instance attributes that do not look
    # like methods or private/internal state.
    attrs = [
        key for key, value in vars(self).items()
        if not key.startswith("_") and not callable(value)
