    The function accepts an optional ``output`` argument which, if provided,
    must be a list that will be appended to; otherwise a new list is created.
    """
    if output is None:
        output = []

    if sequence is None:
        return output

    try:
        iterator = iter(sequence)
    except TypeError:
        # ``sequence`` is not iterable – treat it as a single item
        output.append(sequence)
        return output

    for item in iterator:
        if isinstance(item, (tuple, list)):
            output.extend(item)
        else:
            output.append(item)

    return output

