    interfaces.

    Anything but indiviual interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    # Helper to determine if an item should be expanded.
    def should_expand(item):
        # Expand lists/tuples, but not strings or bytes.
        return isinstance(item, (list, tuple)) and not isinstance(item, (str, bytes))

    # If sequence is a single element that's not a list or tuple, treat it as a singleton.
    if not isinstance(sequence, (list, tuple)):
        sequence = [sequence]

    for item in sequence:
        if item is None:
            continue
        if should_expand(item):
            _normalizeargs(item, output)
        else:
            output.append(item)

    return output

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individual interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    # Guard against None or non-iterable sequence
    if sequence is None:
        return output
    try:
        iterator = iter(sequence)
    except TypeError:
        # Treat as single element
        iterator = (sequence,)
    for item in iterator:
        # Expand tuples of interfaces
        if isinstance(item, tuple):
            output.extend(item)
            continue
        # Expand Declarions or objects with 'implements' or 'interfaces' attributes
        if hasattr(item, "implements"):
            impl = getattr(item, "implements")
            if isinstance(impl, (list, tuple)):
                output.extend(impl)
                continue
        if hasattr(item, "interfaces"):
            inters = getattr(item, "interfaces")
            if isinstance(inters, (list, tuple)):
                output.extend(inters)
                continue
        # Otherwise keep the item as is
        output.append(item)
    return output

