def to_csv(self, separator=",", header=None):
        """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
              Iterables are converted to tables.

        Convert graph's points to CSV.

        *separator* delimits values, the default is comma.

        *header*, if not ``None``, is the first string of the output
        (new line is added automatically).

        Since a graph can be multidimensional,
        for each point first its coordinate is converted to string
        (separated by *separator*), then each part of its value.

        To convert :class:`Graph` to CSV inside a Lena sequence,
        use :class:`lena.output.ToCSV`."""
        # Basic safety checks
        if not hasattr(self, "points"):
            raise AttributeError("The object does not provide a 'points' attribute.")

        if header is not None and not isinstance(header, str):
            raise TypeError("header must be a string or None")

        lines = []
        if header is not None:
            lines.append(header)

        try:
            for point in self.points:
                # Expect point as (coord, value)
                if not isinstance(point, (list, tuple)) or len(point) != 2:
                    raise ValueError("Each point must be a tuple/list of (coord, value)")

                coord, value = point

                # Convert coordinate
                if isinstance(coord, (list, tuple)):
                    coord_items = [str(c) for c in coord]
                else:
                    coord_items = [str(coord)]

                coord_str = separator.join(coord_items)

                # Convert value
                # Value can be iterable or single
                if isinstance(value, (list, tuple, set)) and not isinstance(value, str):
                    value_items = [str(v) for v in value]
                else:
                    value_items = [str(value)] if value is not None else []

                value_str = separator.join(value_items)

                if value_str:
                    line = coord_str + separator + value_str
                else:
                    line = coord_str

                lines.append(line)

        except Exception as exc:
            # Return a readable error message in the CSV output
            # rather than throwing an exception that would break
            # the calling code that might rely on to_csv for diagnostics.
            error_line = f"Error converting point to CSV: {exc}"
            if lines:
                lines.append(error_line)
            else:
                lines = [error_line]

        return "\n".join(lines)

def to_csv(self, separator=",", header=None):
    """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
          Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    # Validate parameters
    if not isinstance(separator, str):
        raise TypeError("separator must be a string")
    if header is not None and not isinstance(header, str):
        raise TypeError("header must be a string or None")

    lines = []

    # Header handling
    if header is not None:
        lines.append(header.rstrip("\n") + "\n")

    # Helper to determine if object is iterable but not string/bytes
    def is_iterable_not_str(obj):
        return (
            hasattr(obj, "__iter__") and
            not isinstance(obj, (str, bytes)) and
            not isinstance(obj, (int, float, complex))
        )

    # Get points from the graph
    points_iter = None
    if hasattr(self, "points"):
        points_iter = self.points
    if points_iter is None:
        # Assume the graph itself is iterable of points
        points_iter = self

    for point in points_iter:
        # Default formatting
        coord_str = ""
        val_str = ""

        # Determine coordinate and value based on structure
        if isinstance(point, tuple]:
            if len(point) == 2:
                coord, val = point
            else:
                coord = point[:-1]
                val = point[-1]
        else:
            # Fallback: no explicit value
            coord = point
            val = None

        # Process coordinate
        if is_iterable_not_str(coord):
            try:
                coord_str = separator.join(map(str, coord))
            except Exception:
                coord_str = str(coord)
        else:
            coord_str = str(coord)

        # Process value
        if val is not None:
            if is_iterable_not_str(val):
                try:
                    val_str = separator.join(map(str, val))
                except Exception:
                    val_str = str(val)
            else:
                val_str = str(val)

        # Assemble line
        if val_str:
            line = f"{coord_str}{separator}{val_str}\n"
        else:
            line = f"{coord_str}\n"

        lines.append(line)

    # Join all parts into final string
    return "".join(lines)

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Ensure the instance has an attribute to store error indices
    if not hasattr(self, "_err_indices"):
        # No error indices have been recorded; return an empty list
        return []

    err_dict = getattr(self, "_err_indices")
    if not isinstance(err_dict, dict):
        # Unexpected structure; assume no indices for the requested coordinate
        return []

    # Return the indices for the specified coordinate, defaulting to an empty list
    return err_dict.get(coord_name, [])

