            # Assumes the instance has an `err_indices` dict mapping coordinate names
            # to a list or set of index values where errors were detected.
            return list(getattr(self, "err_indices", {}).get(coord_name, []))
        except Exception:
            # In case the attribute does not exist or any other issue occurs,
            # return an empty list to indicate no errors were found for this coordinate.
            return []

