    if not isinstance(coord_name, str):
        raise TypeError("coord_name must be a string")

    # Retrieve the internal mapping of error indices
    try:
        err_map = self._error_indices
    except AttributeError:
        # No error mapping defined; return empty list
        return []

    if not isinstance(err_map, dict):
        raise TypeError("self._error_indices must be a mapping of coordinate names to indices")

    # Get the indices for the requested coordinate
    indices = err_map.get(coord_name, [])
    if not isinstance(indices, (list, tuple)):
        raise TypeError(f"Error indices for coordinate {coord_name!r} must be a list or tuple")

    # Return a copy to prevent accidental modification of the internal list
    return list(indices)

def _update_context(self, context):
    """Update *context* with the properties of this graph.

    *context.error* is appended with indices of errors.
    Example subcontext for a graph with fields "E,t,error_E_low":
    {"error": {"x_low": {"index": 2}}}.
    Note that error names are called "x", "y" and "z"
    (this corresponds to first three coordinates,
    if they are present), which allows to simplify plotting.
    Existing values are not removed
    from *context.value* and its subcontexts.

    Called on "destruction" of the graph (for example,
    in :class:`.ToCSV`). By destruction we mean conversion
    to another structure (like text) in the flow.
    The graph object is not really destroyed in this process.
    """
    # Ensure the context has an `error` dictionary
    if not hasattr(context, "error") or context.error is None:
        context.error = {}
    if not isinstance(context.error, dict):
        # Gracefully handle non-dict errors
        context.error = {}

    # Map the graph's own attributes that represent errors
    # conventionally named like "error_<field>".
    for attr_name in dir(self):
        if not attr_name.startswith("error_"):
            continue
        error_value = getattr(self, attr_name, None)
        if error_value is None:
            continue

        # Construct the key used in the context.
        # The original description suggests using "x", "y", "z" for
        # the first three coordinates.  If we cannot infer such a
        # mapping, we simply use the suffix after "error_".
        error_key_suffix = attr_name[len("error_") :]  # e.g., "E_low"

        # Attempt a coarse mapping: replace any leading alphabetic
        # character with "x", "y", or "z" if it is the first field.
        # Fall back to the original suffix if not ambiguous.
        # Avoid altering a suffix that already starts with "x",
        # "y", or "z" to preserve names like "x_low".
        if error_key_suffix and error_key_suffix[0].isalpha():
            first_field = error_key_suffix[0].lower()
            if first_field in ("x", "y", "z"):
                # keep as is
                context_key = error_key_suffix
            else:
                # Map only if we have enough context of coordinate order:
                # we resort to a simple mapping sequentially if the graph
                # has a 'coordinates' or 'fields' attribute
                try:
                    order = getattr(self, "coordinates", None)
                except Exception:
                    order = None
                if (order is not None and isinstance(order, (list, tuple)) and
                        len(order) >= 3):
                    # find position of the first field component
                    pos = None
                    for i, field in enumerate(order):
                        if field.lower().startswith(first_field):
                            pos = i
                            break
                    if pos is not None and pos < 3:
                        context_key = ("x", "y", "z")[pos] + error_key_suffix[1:]
                    else:
                        context_key = error_key_suffix
                else:
                    context_key = error_key_suffix
        else:
            context_key = error_key_suffix

        # Determine the index of the error.
        # We assume that the error value is an integer or a container
        # (list/tuple/set) of indices, and we use the first one.
        if isinstance(error_value, (list, tuple, set)):
            if not error_value:
                continue
            idx = next(iter(error_value))
        else:
            idx = error_value

        # Insert into the context without removing existing entries.
        if context_key in context.error:
            # Preserve any other metadata already present.
            context.error[context_key].update({"index": idx})
        else:
            context.error[context_key] = {"index": idx}

def _update_context(self, context):
    """Update *context* with the properties of this graph.

    *context.error* is appended with indices of errors.
    Example subcontext for a graph with fields "E,t,error_E_low":
    {"error": {"x_low": {"index": 2}}}.
    Note that error names are called "x", "y" and "z"
    (this corresponds to first three coordinates,
    if they are present), which allows to simplify plotting.
    Existing values are not removed
    from *context.value* and its subcontexts.

    Called on "destruction" of the graph (for example,
    in :class:`.ToCSV`). By destruction we mean conversion
    to another structure (like text) in the flow.
    The graph object is not really destroyed in this process.
    """
    # Ensure context has an 'error' attribute that is a dict
    try:
        err_dict = context.error  # may raise AttributeError
    except AttributeError:
        # If context.error is not set, create it
        context.error = {}

    errors = context.error

    # Map coordinate indices to names for the first three coordinates
    coord_names = {0: "x", 1: "y", 2: "z"}
    # Assume the graph stores the column headers in self.fields (a list or tuple)
    if not hasattr(self, "fields"):
        # If the graph doesn't expose fields, nothing to do
        return
    try:
        fields = self.fields
    except Exception:
        return

    # Build a quick lookup for base columns (non-error) to their index
    base_index = {name: idx for idx, name in enumerate(fields)}

    for idx, col_name in enumerate(fields):
        if not isinstance(col_name, str):
            continue
        if not col_name.lower().startswith("error_"):
            continue

        # Extract the part after the first underscore following "error_"
        # e.g., for "error_E_low" we get "E_low", then split on '_' to get base field name
        rest = col_name[len("error_") :]
        # Determine the base field (e.g., "E" from "E_low")
        if "_" in rest:
            base_field = rest.split("_", 1)[0]
            suffix = rest.split("_", 1)[1]
        else:
            base_field = rest
            suffix = ""

        # Determine the coordinate index (0->x, 1->y, 2->z)
        base_idx = base_index.get(base_field)
        if base_idx is None or base_idx not in coord_names:
            # Unsupported coordinate (e.g., >3) – skip
            continue

        coord = coord_names[base_idx]
        key = f"{coord}_{suffix}" if suffix else coord

        # Add the error index; if key already exists, keep existing (do not overwrite)
        if key not in errors:
            errors[key] = {"index": idx}
        else:
            # Append / keep existing indices if multiple
            if isinstance(errors[key], dict) and "index" in errors[key]:
                # Wrap existing index into a list
                errors[key] = {"indexes": [errors[key]["index"], idx]}
            elif isinstance(errors[key], dict) and "indexes" in errors[key]:
                errors[key]["indexes"].append(idx)
            else:
                # Unexpected structure – replace safely
                errors[key] = {"indexes": [idx]}

    # Existing values in context.value and subcontexts are left untouched.

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Basic validation of inputs
    try:
        bins_list = list(bins)
        edges_list = list(edges)
    except TypeError as exc:
        raise ValueError("Both bins and edges must be array-like") from exc

    if len(edges_list) != len(bins_list) + 1:
        raise ValueError("Number of edges must be one more than number of bins")

    total = 0.0
    for value, left, right in zip(bins_list, edges_list, edges_list[1:]):
        try:
            width = right - left
            total += value * width
        except Exception as exc:
            raise ValueError(f"Non-numeric bin value or edge encountered: {exc}") from exc

    return total

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Basic input validation
    if bins is None or edges is None:
        raise TypeError("both bins and edges must be provided and not None")

    try:
        bins = list(bins)
    except TypeError as exc:
        raise TypeError("bins must be an iterable") from exc

    try:
        edges = list(edges)
    except TypeError as exc:
        raise TypeError("edges must be an iterable") from exc

    if len(edges) != len(bins) + 1:
        raise ValueError("len(edges) must be exactly one more than len(bins)")

    # Compute bin widths and validate edges are strictly increasing
    widths = []
    prev_edge = edges[0]
    for idx, edge in enumerate(edges[1:], start=1):
        width = edge - prev_edge
        if width <= 0:
            raise ValueError(f"edges must be strictly increasing; "
                             f"edge difference at position {idx} is {width}")
        widths.append(float(width))
        prev_edge = edge

    # Calculate the integral
    total = 0.0
    for bin_val, width in zip(bins, widths):
        try:
            bin_val = float(bin_val)
        except Exception as exc:
            raise TypeError(f"bin values must be numeric; got {bin_val}") from exc
        total += bin_val * width

    return total

