        raise ValueError("len(edges) must be len(bins)+1")

    try:
        widths = [edges[i + 1] - edges[i] for i in range(len(bins))]
    except Exception as exc:
        raise ValueError("edges must be numeric and increasing") from exc

    try:
        total = sum(b * w for b, w in zip(bins, widths))
    except Exception as exc:
        raise ValueError("bins must be numeric") from exc

    return total

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Validate inputs
    try:
        bin_list = list(bins)
        edge_list = list(edges)
    except TypeError as exc:
        raise ValueError("bins and edges must be iterable") from exc

    if len(bin_list) != len(edge_list) - 1:
        raise ValueError(
            f"Number of bins ({len(bin_list)}) must be one less than number of edges ({len(edge_list)})"
        )

    # Ensure edges are strictly increasing
    if any(edge_list[i] >= edge_list[i + 1] for i in range(len(edge_list) - 1)):
        raise ValueError("edges must be strictly increasing")

    # Compute bin widths and integral
    integral_value = 0.0
    try:
        for b, e1, e2 in zip(bin_list, edge_list, edge_list[1:]):
            width = float(e2 - e1)
            integral_value += float(b) * width
    except Exception as exc:
        raise ValueError("Error computing integral: incompatible bin values") from exc

    return integral_value

