def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("Both arguments must be dictionaries")

    result = {}
    for key, val in d1.items():
        if key not in d2:
            # Include the value directly (no potential recursion)
            result[key] = val
        else:
            other_val = d2[key]
            # If both values are dicts and we still have depth left,
            # compute the nested difference.
            if isinstance(val, dict) and isinstance(other_val, dict):
                # Determine new recursion depth
                if level == 0:
                    # No recursion allowed – treat the nested dicts as
                    # different values if they are not identical.
                    if val != other_val:
                        result[key] = val
                else:
                    new_level = level - 1 if level > 0 else -1
                    subdiff = difference(val, other_val, new_level)
                    if subdiff:
                        result[key] = subdiff
            else:
                # Non-dict values – include if they differ
                if val != other_val:
                    result[key] = val
    return result

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("Both arguments must be dictionaries")
    result = {}
    for key, val1 in d1.items():
        if key not in d2:
            # include value directly (may be a dict reference)
            result[key] = val1
            continue
        val2 = d2[key]
        if isinstance(val1, dict) and isinstance(val2, dict):
            # Recurse when allowed by level
            if level == -1 or level > 0:
                # Determine recursion depth for the next level
                new_level = -1 if level == -1 else level - 1
                sub = difference(val1, val2, new_level)
                if sub:
                    result[key] = sub
            else:
                # At depth limit, if dictionaries differ, include the dict from d1
                if val1 != val2:
                    result[key] = val1
        else:
            # Include the value from d1 if it differs from d2
            if val1 != val2:
                result[key] = val1
    return result

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if not isinstance(d1, dict):
        raise TypeError("d1 must be a dictionary")
    if not isinstance(d2, dict):
        # nothing to subtract from, return a shallow copy of d1
        return {k: v if not isinstance(v, dict) else v.copy()
                for k, v in d1.items()}

    def _diff(sub1, sub2, curr_depth):
        if level != -1 and curr_depth >= level:
            # depth limit reached, treat as non-dict values
            if sub1 != sub2:
                return sub1
            return None

        result = {}
        for key, val1 in sub1.items():
            if key not in sub2:
                # key missing in sub2: include it
                result[key] = val1.copy() if isinstance(val1, dict) else val1
            else:
                val2 = sub2[key]
                # both present
                if isinstance(val1, dict) and isinstance(val2, dict):
                    sub_diff = _diff(val1, val2, curr_depth + 1)
                    if sub_diff:
                        result[key] = sub_diff
                else:
                    if val1 != val2:
                        result[key] = val1
        return result if result else None

    diff_result = _diff(d1, d2, 0)
    return diff_result if diff_result is not None else {}

