    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("both d1 and d2 must be dictionaries")

    result = {}
    for k, v in d1.items():
        # Key not in d2: include entire subtree or value
        if k not in d2:
            if isinstance(v, dict):
                # copy recursively if we still allow recursion
                if level != 0:
                    result[k] = difference(v, {}, level-1 if level > 0 else -1)
                else:
                    # no recursion: just reference original dict
                    result[k] = v
            else:
                result[k] = v
            continue

        # Key present in both, compare values
        v2 = d2[k]
        if v == v2:
            continue
        if isinstance(v, dict) and isinstance(v2, dict):
            if level == 0:
                # no recursion: treat as different value
                result[k] = v
            else:
                nested = difference(v, v2, level-1 if level > 0 else -1)
                if nested:
                    result[k] = nested
        else:
            result[k] = v

    return result

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Sanity checks
    if not hasattr(self, "edges"):
        raise AttributeError("Histogram object lacks 'edges' attribute")
    if not hasattr(self, "data") and not hasattr(self, "buckets"):
        raise AttributeError("Histogram object lacks storage attribute ('data' or 'buckets')")
    if not isinstance(coord, (list, tuple)):
        raise TypeError("coord must be a sequence of coordinates")

    # Dimension check
    if len(coord) != len(self.edges):
        raise ValueError(f"Coordinate dimensionality ({len(coord)}) does not match histogram ({len(self.edges)})")

    # Find bin indices for each dimension
    bin_indices = []
    for val, edge in zip(coord, self.edges):
        # If coordinate is outside the defined edges, ignore it
        if val < edge[0] or val > edge[-1]:
            return
        # Find the bin index
        # Note: assumes edges are sorted in ascending order
        idx = None
        for i in range(len(edge) - 1):
            if edge[i] <= val < edge[i + 1]:
                idx = i
                break
        # If value equals the last edge value, it falls into the last bin
        if idx is None and val == edge[-1] and len(edge) > 1:
            idx = len(edge) - 2
        if idx is None:
            return  # Outside or malformed edges
        bin_indices.append(idx)

    bin_tuple = tuple(bin_indices)

    # Update histogram storage
    if hasattr(self, "data"):
        try:
            self.data[bin_tuple] += weight
        except Exception as exc:
            raise RuntimeError(f"Failed to update histogram data: {exc}") from exc
    else:
        # Use sparse dictionary representation
        self.buckets[bin_tuple] = self.buckets.get(bin_tuple, 0) + weight

def fill(self, coord, weight=1):
        """Fill histogram at *coord* with the given *weight*.

        Coordinates outside the histogram edges are ignored.
        """
        # Basic validation
        if weight is None:
            return
        try:
            # Import numpy lazily to avoid mandatory dependency
            import numpy as np
        except Exception:
            # If numpy is not available we cannot compute bin indices
            return

        # Ensure coord is numeric and shape aligns with histogram dimensions
        try:
            coord_arr = np.asarray(coord, dtype=float)
        except Exception:
            # Invalid coordinate type: ignore
            return

        # If histogram is 1‑D
        if hasattr(self, "edges") and hasattr(self, "bins"):
            edges = np.asarray(self.edges, dtype=float)
            if coord_arr.ndim == 0:  # scalar
                # Find bin index
                idx = np.searchsorted(edges, coord_arr, side='right') - 1
                if 0 <= idx < len(self.bins):
                    self.bins[idx] += weight
            elif coord_arr.ndim == 1 and len(coord_arr) == len(edges) - 1:
                # Multi‑dimensional histogram, basic handling: ignore for simplicity
                pass  # Experimental; real implementation would need multidimensional logic
        # If histogram uses explicit bounds
        elif hasattr(self, "min") and hasattr(self, "max"):
            if coord_arr < self.min or coord_arr > self.max:
                return
            # Simple counting if bin width is known
            if hasattr(self, "width") and self.width > 0:
                idx = int((coord_arr - self.min) / self.width)
                if self.bins is not None and 0 <= idx < len(self.bins):
                    self.bins[idx] += weight
        # Unsupported histogram structure: silently ignore
        return  # End of method

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Ensure coord is an iterable of numeric values
    try:
        coord_list = list(coord)
    except TypeError:
        raise TypeError("coord must be an iterable of numerical values")

    # histogram should have 'edges' and 'bins' attributes
    if not hasattr(self, 'edges') or not hasattr(self, 'bins'):
        raise AttributeError("Histogram object missing 'edges' or 'bins' attributes")

    if len(coord_list) != len(self.edges):
        raise ValueError(f"{len(self.edges)} coordinate values required, got {len(coord_list)}")

    indices = []
    for dim, value in enumerate(coord_list):
        edges = self.edges[dim]
        # Value must be within the range [edges[0], edges[-1])
        if value < edges[0] or value >= edges[-1]:
            # Coordinates outside the histogram bounds are ignored
            return

        # Find bin index via binary search
        lo, hi = 0, len(edges) - 1
        while lo < hi - 1:
            mid = (lo + hi) // 2
            if value < edges[mid]:
                hi = mid
            else:
                lo = mid
        indices.append(lo)

    # Increment the histogram bin
    try:
        self.bins[tuple(indices)] += weight
    except Exception as exc:
        raise RuntimeError(f"Failed to update histogram bin {indices}: {exc}") from exc

def fill(self, coord, weight=1):
        """Fill histogram at *coord* with the given *weight*.

        Coordinates outside the histogram edges are ignored.
        """
        # Import bisect for efficient bin search
        try:
            from bisect import bisect_left
        except Exception:
            # If bisect not available, fallback to linear search
            def bisect_left(a, x):
                for i, val in enumerate(a):
                    if val > x:
                        return i
                return len(a)

        # Ensure coord is a sequence of the correct dimensionality
        if not isinstance(coord, (list, tuple)):
            raise TypeError("coord must be a list or tuple of coordinates")
        if len(coord) != len(self.edges):
            raise ValueError(f"coord must have {len(self.edges)} dimensions")

        # Determine bin indices for each dimension
        indices = []
        for dim, (x, edges) in enumerate(zip(coord, self.edges)):
            # Find the insertion point
            idx = bisect_left(edges, x)
            # Convert to bin index
            bin_index = idx - 1
            # Check bounds
            if bin_index < 0 or bin_index >= len(edges) - 1:
                # Coordinate outside histogram edges; ignore histogram
                return
            indices.append(bin_index)

        # Increment the appropriate bin by weight
        try:
            self.counts[tuple(indices)] += weight
        except Exception as e:
            raise RuntimeError(f"Failed to increment histogram bin at {indices}: {e}")

def _validate_labels(labels):
    """
    Check that keys and values in the given labels match against their corresponding
    regular expressions.
    """
    errors = []

    # Regular expressions for keys and values
    key_re = re.compile(r"^[A-Za-z][A-Za-z0-9_]*$")
    val_re = re.compile(r"^[A-Za-z][A-Za-z0-9_]*$")

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            errors.append({repr(key): "expected string or bytes-like object"})
        else:
            if not key_re.match(key):
                errors.append({key: f"Label key '{key}' does not match the regex [{key_re.pattern}]"})

        # Validate value type
        if not isinstance(value, (str, bytes)):
            errors.append({repr(value): "expected string or bytes-like object"})
        else:
            if not val_re.match(value):
                errors.append({value: f"Label value '{value}' does not match the regex [{val_re.pattern}]"})

    if errors:
        raise ValidationError(errors)

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    # Regular expressions to validate label keys and values.
    # They should be defined elsewhere in the application.
    # For the purpose of this implementation we assume they are available
    # as LABEL_KEY_REGEX and LABEL_VALUE_REGEX.
    try:
        import re

        key_regex = LABEL_KEY_REGEX  # should be a compiled regex
        value_regex = LABEL_VALUE_REGEX  # should be a compiled regex
    except NameError:
        # If regexes are not defined, raise an informative error.
        raise ValidationError(
            [
                {
                    "regex": "Regular expression patterns for labels not available. "
                    "Ensure `LABEL_KEY_REGEX` and `LABEL_VALUE_REGEX` are defined."
                }
            ]
        )

    errors = []

    for k, v in labels.items():
        # Check key
        if not isinstance(k, (str, bytes)):
            errors.append({str(k): "expected string or bytes-like object"})
        else:
            if isinstance(k, bytes):
                # Try to decode to string for regex test
                try:
                    k_str = k.decode("utf-8")
                except Exception:
                    errors.append({str(k): "bytes key could not be decoded as UTF-8"})
                    k_str = None
            else:
                k_str = k
            if k_str is not None and not key_regex.search(k_str):
                errors.append(
                    {str(k): f"Label key '{k_str}' does not match the regex {key_regex.pattern}"}
                )

        # Check value(s)
        # Accept a single string/bytes or a list/tuple of them
        vs = [v] if not isinstance(v, (list, tuple)) else v
        if not isinstance(vs, (list, tuple)):
            errors.append({str(v): "expected string or bytes-like object"})
            continue

        for item in vs:
            if not isinstance(item, (str, bytes)):
                errors.append({str(item): "expected string or bytes-like object"})
            else:
                if isinstance(item, bytes):
                    try:
                        item_str = item.decode("utf-8")
                    except Exception:
                        errors.append({str(item): "bytes value could not be decoded as UTF-8"})
                        item_str = None
                else:
                    item_str = item
                if item_str is not None and not value_regex.search(item_str):
                    errors.append(
                        {
                            str(item): f"Label value '{item_str}' does not match the regex {value_regex.pattern}"
                        }
                    )

    if errors:
        # Raise ValidationError with the collected message list
        raise ValidationError(errors)

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    import re

    errors = []

    # Regular expressions for keys and values (example patterns, replace with actual ones if needed)
    key_regex = re.compile(r'^[A-Za-z0-9_]+$')
    val_regex = re.compile(r'^[A-Za-z0-9_]+$')

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): 'expected string or bytes-like object'})
        else:
            if not key_regex.match(key):
                errors.append(
                    {key: f"Label key {key!r} does not match the regex [{key_regex.pattern}]"}
                )

        # Validate value type
        if not isinstance(value, (str, bytes)):
            errors.append({str(value): 'expected string or bytes-like object'})
        else:
            if not val_regex.match(value):
                errors.append(
                    {value: f"Label value {value!r} does not match the regex [{val_regex.pattern}]"}
                )

    if errors:
        raise ValidationError(errors)

def validate_value(value):
    """Validate the given value against the corresponding regular expression.

    Args:
        value: the string to validate

    Raises:
        ValidationError: if the given value is not conform to the regular expression.
    """
    import re
    # Convert non-string values to string for validation
    if not isinstance(value, str):
        value = str(value)

    # Retrieve the regular expression from the surrounding scope
    try:
        pattern = regex
    except NameError:
        raise ValidationError("No regular expression defined for validation.")

    # Compile string patterns if necessary
    if isinstance(pattern, str):
        try:
            pattern = re.compile(pattern)
        except re.error as exc:
            raise ValidationError(f"Invalid regular expression '{pattern}': {exc}")

    # Ensure the pattern supports fullmatch (Python ≥3.4)
    matched = pattern.fullmatch(value) if hasattr(pattern, "fullmatch") else pattern.match(value)
    if not matched:
        raise ValidationError(
            f"Value '{value}' does not match the required pattern {pattern.pattern if hasattr(pattern, 'pattern') else pattern}"
        )
    return True

def validate_value(value):
    """Validate the given value against the corresponding regular expression.

    Args:
        value: the string to validate

    Raises:
        ValidationError: if the given value is not conform to the regular expression.
    """
    # Ensure value is a string
    if not isinstance(value, str):
        raise ValidationError("Provided value must be a string")

    # Retrieve the regular expression pattern that should be used for validation
    # It may be defined globally as REGEX, or as an attribute of this module/class.
    try:
        pattern = REGEX
    except NameError:
        # If no pattern is defined, consider any string as valid
        return

    # Import the regex module lazily
    try:
        import re
    except ImportError as e:
        raise RuntimeError("Regex module not available") from e

    # Compile the pattern if it hasn't been compiled already
    if not hasattr(pattern, "fullmatch"):
        try:
            compiled_pattern = re.compile(pattern)
        except re.error as e:
            raise RuntimeError(f"Invalid regular expression '{pattern}': {e}") from e
    else:
        compiled_pattern = pattern

    # Perform the full match
    if not compiled_pattern.fullmatch(value):
        raise ValidationError(
            f"Value '{value}' does not conform to the expected regular expression."
        )

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Together with :func:`generate_default_observer_schema_list`, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.

    """
    if not isinstance(manifest_dict, dict):
        raise ValueError(f"Expected manifest_dict to be a dict, got {type(manifest_dict).__name__}")

    def recurse(item, is_top=False):
        if isinstance(item, dict):
            result = {}
            for k, v in item.items():
                if isinstance(v, dict) or isinstance(v, list):
                    result[k] = recurse(v, False)
                else:
                    # Scalar value
                    if is_top:
                        # Keep original value on top level
                        result[k] = v
                    else:
                        result[k] = None
            return result
        elif isinstance(item, list):
            result_list = []
            for elem in item:
                if isinstance(elem, dict) or isinstance(elem, list):
                    result_list.append(recurse(elem, False))
                else:
                    result_list.append(None)
            return result_list
        else:
            # Scalar at top level: keep if first_level else None
            return item if is_top else None

    return recurse(manifest_dict, first_level)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
