    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.

    """
    if not isinstance(manifest_dict, dict):
        raise TypeError("manifest_dict must be a dictionary")

    def _recurse(struct, is_first):
        if isinstance(struct, dict):
            result = {}
            for k, v in struct.items():
                if isinstance(v, dict):
                    result[k] = _recurse(v, False)
                elif isinstance(v, list):
                    # Process list entries recursively, assuming each entry is a dict.
                    result[k] = [_recurse(item, False) if isinstance(item, dict) else None for item in v]
                else:
                    # Non-dict/list values
                    result[k] = v if is_first else None
            return result
        elif isinstance(struct, list):
            # Should not normally occur in this helper, but handle just in case.
            return [_recurse(item, False) if isinstance(item, (dict, list)) else None for item in struct]
        else:
            # Primitive value
            return struct if is_first else None

    return _recurse(manifest_dict, first_level)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.

    """
    if not isinstance(manifest_dict, dict):
        raise TypeError(f"Expected dict, got {type(manifest_dict).__name__}")

    result = {}

    # Copy identifying fields when this is the first level
    if first_level:
        ident_keys = ['apiVersion', 'kind']
        for key in ident_keys:
            if key in manifest_dict:
                result[key] = manifest_dict[key]
        # Handle simple metadata subfields
        if 'metadata' in manifest_dict and isinstance(manifest_dict['metadata'], dict):
            meta_in = manifest_dict['metadata']
            meta_out = {}
            for meta_k in ['name', 'namespace', 'labels', 'annotations']:
                if meta_k in meta_in:
                    meta_out[meta_k] = meta_in[meta_k]
            if meta_out:
                result['metadata'] = meta_out

    for key, value in manifest_dict.items():
        # Skip already handled identifiers
        if key in result:
            continue

        if isinstance(value, dict):
            # Recurse into nested dicts
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            processed_list = []
            for item in value:
                if isinstance(item, dict):
                    processed_list.append(generate_default_observer_schema_dict(item, first_level=False))
                elif isinstance(item, list):
                    # Nested lists are flattened by treating each element similarly
                    sublist = []
                    for subitem in item:
                        if isinstance(subitem, dict):
                            sublist.append(generate_default_observer_schema_dict(subitem, first_level=False))
                        elif isinstance(subitem, list):
                            sublist.append([])  # All plain lists become empty
                        else:
                            sublist.append(None)
                    processed_list.append(sublist)
                else:
                    processed_list.append(None)
            result[key] = processed_list
        else:
            result[key] = None

    return result

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.

    """
    if not isinstance(manifest_dict, dict):
        raise ValueError("manifest_dict must be a dictionary")

    def _process_node(node, is_root):
        if isinstance(node, dict):
            new_obj = {}
            for k, v in node.items():
                if isinstance(v, (dict, list)):
                    new_obj[k] = _process_node(v, False)
                else:
                    # Keep original value only if we're at the root and first_level is True
                    new_obj[k] = v if is_root and first_level else None
            return new_obj
        if isinstance(node, list):
            return [_process_node(elem, False) if isinstance(elem, (dict, list)) else (elem if False else None) for elem in node]
        # Primitive value; replace with None unless at root and first_level
        return node if is_root and first_level else None

    return _process_node(manifest_dict, True)

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    # Basic sanity checks
    if not isinstance(observer_schema, list):
        raise TypeError("observer_schema must be a list")
    if response is None or not isinstance(response, dict):
        # Nothing to do if there's no response data
        return last_applied_manifest

    # Ensure we are working with a list for the manifest
    if last_applied_manifest is None:
        last_applied_manifest = []

    for field_def in observer_schema:
        # Extract the key name in a flexible way
        key = field_def.get("name") or field_def.get("field") or field_def.get("key")
        if not key:
            continue  # skip malformed entries

        # Skip if the key is not present in the response
        if key not in response:
            continue

        value = response[key]

        # Find the existing entry in the manifest or create a new one
        target_entry = None
        if isinstance(last_applied_manifest, list):
            for item in last_applied_manifest:
                if isinstance(item, dict):
                    if item.get("name") == key or item.get("field") == key or item.get("key") == key:
                        target_entry = item
                        break
            if target_entry is None:
                # create a new entry with a *value* key for scalar/nested data
                target_entry = {"name": key, "value": None}
                last_applied_manifest.append(target_entry)
        else:
            # If the manifest is a dict, use it directly
            if key not in last_applied_manifest:
                last_applied_manifest[key] = None
            target_entry = last_applied_manifest

        # Handle nested structures recursively
        subschema = field_def.get("subschema")
        if subschema and isinstance(subschema, list):
            # Ensure the target entry holds a container for nested data
            if isinstance(target_entry, dict):
                nested_container = target_entry.get("value")
            else:
                nested_container = target_entry.get(key)

            if nested_container is None:
                if isinstance(value, dict):
                    nested_container = {}
                elif isinstance(value, list):
                    nested_container = []
                else:
                    nested_container = {}

                if isinstance(target_entry, dict):
                    target_entry["value"] = nested_container
                else:
                    target_entry[key] = nested_container

            if isinstance(value, dict):
                update_last_applied_manifest_list_from_resp(
                    nested_container, subschema, value
                )
            elif isinstance(value, list):
                # For lists, ensure each element has a container and recurse
                for i, item in enumerate(value):
                    if not isinstance(item, dict):
                        continue  # non‑dict items are copied directly
                    if i >= len(nested_container):
                        nested_container.append({})
                    update_last_applied_manifest_list_from_resp(
                        nested_container[i], subschema, item
                    )
            else:
                # For scalar values, just copy them if they weren't set
                if isinstance(target_entry, dict) and target_entry.get("value") is None:
                    target_entry["value"] = value
                elif not isinstance(target_entry, dict) and target_entry is None:
                    target_entry[key] = value
        else:
            # No nested schema, just set the value if absent
            if isinstance(target_entry, dict):
                if target_entry.get("value") is None:
                    target_entry["value"] = value
            else:
                if target_entry[key] is None:
                    target_entry[key] = value

    return last_applied_manifest

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:`update_last_applied_manifest_dict_from_resp`, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response.

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated.  It is typically a dictionary, but may also be a list of
            dictionaries when multiple resources are returned.
        observer_schema (dict | list): partial ``observer_schema`` describing
            which fields should be observed.  The schema can be nested to match
            the structure of the Kubernetes object.
        response (dict | list): partial response from the Kubernetes API.

    This function goes through all observed fields, and initializes their value in
    ``last_applied_manifest`` if they are not yet present.
    """

    # Helper to update a single dictionary against the schema
    def _update_dict(ld, schema, resp):
        if not isinstance(schema, dict):
            # If schema is a list of field names, treat each as a key
            if isinstance(schema, list):
                for key in schema:
                    if key not in ld:
                        if isinstance(resp, dict) and key in resp:
                            ld[key] = resp[key]
                        else:
                            # If the value is a nested dict or list, initialize structure
                            ld[key] = {} if isinstance(resp, dict) else []
                return

        # Schema is a dict mapping keys to nested schema or None
        for key, sub_schema in schema.items():
            if key not in ld:
                if isinstance(resp, dict) and key in resp:
                    ld[key] = resp[key]
                else:
                    # Initialize based on expected type in response
                    ld[key] = {} if isinstance(sub_schema, dict) else [] if isinstance(sub_schema, list) else None
            # If both are dicts/lists, recurse
            if isinstance(ld[key], dict) and isinstance(resp.get(key, {}), dict):
                _update_dict(ld[key], sub_schema or {}, resp[key])
            elif isinstance(ld[key], list) and isinstance(resp.get(key, []), list) and isinstance(sub_schema, list):
                # Recursively process each item in the list
                for idx, item in enumerate(resp[key]):
                    if idx >= len(ld[key]):
                        # Ensure list has an element to update
                        ld[key].append({} if isinstance(sub_schema[0], dict) else [])
                    _update_dict(ld[key][idx], sub_schema[0] if sub_schema else {}, item)

    # If everything is a list of items, iterate through them
    if isinstance(last_applied_manifest, list) and isinstance(response, list) and isinstance(observer_schema, list):
        # Schema list should contain dicts corresponding to each item
        for idx, item in enumerate(response):
            if idx < len(last_applied_manifest):
                _update_dict(last_applied_manifest[idx], observer_schema[0] if observer_schema else {}, item)
            else:
                # Append new item from response
                new_item = {}
                _update_dict(new_item, observer_schema[0] if observer_schema else {}, item)
                last_applied_manifest.append(new_item)
    else:
        # Treat as single object
        _update_dict(last_applied_manifest, observer_schema, response)

