    Returns:
        The updated ``last_applied_manifest``.
    """

    # Helper to safely get nested value
    def get_nested(d, keys, default=None):
        for k in keys:
            if not isinstance(d, dict):
                return default
            d = d.get(k, default)
        return d

    # If either the manifest or the response is not a list, nothing to do
    if not isinstance(last_applied_manifest, list) or not isinstance(response, list):
        return last_applied_manifest

    # ``observer_schema`` is expected to be a list of dictionaries,
    # each describing an element in the list (e.g., a Kubernetes resource).
    # We iterate over these schemas and ensure each corresponding entry in
    # ``last_applied_manifest`` has the values present in ``response``.
    for i, elem_schema in enumerate(observer_schema):
        # Skip if schema does not contain a name key
        name = elem_schema.get("name")
        if name is None:
            continue

        # Ensure both lists have an element at this index
        try:
            src_elem = response[i]
            tgt_elem = last_applied_manifest[i]
        except IndexError:
            # If the manifest is shorter, we create a new element
            if i < len(response):
                tgt_elem = {}
                last_applied_manifest.append(tgt_elem)
            else:
                continue

        if not isinstance(src_elem, dict) or not isinstance(tgt_elem, dict):
            continue

        # Update scalar fields
        for field, field_def in elem_schema.get("properties", {}).items():
            if field not in tgt_elem and field in src_elem:
                tgt_elem[field] = src_elem[field]

            # Recursively handle nested lists
            if (
                field_def.get("type") == "array"
                and isinstance(field_def.get("items"), dict)
                and isinstance(src_elem.get(field), list)
                and isinstance(tgt_elem.get(field), list)
            ):
                for j, item_schema in enumerate(field_def["items"].get("properties", {})):
                    try:
                        src_item = src_elem[field][j]
                        tgt_item = tgt_elem[field][j]
                        # Recurse for dictionary items
                        if isinstance(src_item, dict) and isinstance(tgt_item, dict):
                            update_last_applied_manifest_dict_from_resp(
                                tgt_item, field_def["items"]["properties"], src_item
                            )
                    except Exception:
                        continue

            # Recursively handle nested objects
            if (
                field_def.get("type") == "object"
                and isinstance(field_def.get("properties"), dict)
                and isinstance(src_elem.get(field), dict)
                and isinstance(tgt_elem.get(field), dict)
            ):
                update_last_applied_manifest_dict_from_resp(
                    tgt_elem[field], field_def["properties"], src_elem[field]
                )

    return last_applied_manifest

