def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Basic guard against a missing application object
    if not hasattr(app, "spec"):
        # nothing to do if no spec attribute
        return

    manifest = getattr(app.spec, "manifest", None)
    if manifest is None:
        # nothing to do if no manifest defined
        return

    # Try to obtain the resources dictionary or iterable
    resources = getattr(manifest, "resources", None)
    if resources is None:
        # Support a case where the manifest itself is a mapping of resources
        resources = manifest

    # Iterate over resources and set a default observer schema when missing
    for key, resource in list(resources.items() if isinstance(resources, dict) else enumerate(resources)):
        try:
            # Resource may be a dict or an object instance
            if isinstance(resource, dict):
                if not resource.get("observer_schema"):
                    resource["observer_schema"] = {"fields": []}
            else:
                if not getattr(resource, "observer_schema", None):
                    setattr(resource, "observer_schema", {"fields": []})
        except Exception:
            # Skip problematic entries but continue processing
            continue

    # No explicit return value is required; the function mutates the app object in place.

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Basic validation of the input
    if app is None:
        raise ValueError("The application instance is None.")
    if not hasattr(app, "spec"):
        raise TypeError("The provided object does not appear to be a valid Application (missing 'spec' attribute).")
    if not hasattr(app.spec, "manifest"):
        raise AttributeError("The application spec does not contain a 'manifest' attribute.")

    manifest = app.spec.manifest

    # Try to get an iterable container of resources.  The exact attribute name depends on
    # the underlying implementation – common choices are 'resources', 'items', or a bare
    # list/tuple.  We fall back to the manifest itself if it appears to be iterable.
    resources = None
    if hasattr(manifest, "resources"):
        resources = manifest.resources
    elif hasattr(manifest, "items"):
        resources = manifest.items
    elif isinstance(manifest, (list, tuple)):
        resources = manifest
    else:
        # Not a recognized container – raise a clear error
        raise TypeError(
            "Could not find a container of Kubernetes resources within spec.manifest. "
            f"Found type {type(manifest).__name__} with attributes {dir(manifest)}."
        )

    # Ensure we have something to iterate over
    try:
        iter(resources)
    except TypeError as exc:
        raise TypeError(
            "The resources container is not iterable. "
            f"Resource type: {type(resources).__name__}"
        ) from exc

    # Prepare a dictionary to hold generated schemas if we want to expose them
    generated_schemas = {}

    for idx, res in enumerate(resources):
        # Normalise the resource into a dictionary; if it is not a dict assume
        # it has dict-like attribute access (e.g. a dataclass or namedtuple).
        try:
            res_dict = dict(res)
        except Exception:
            # Attempt attribute extraction
            try:
                res_dict = {
                    k: getattr(res, k) for k in dir(res)
                    if not k.startswith("_") and not callable(getattr(res, k))
                }
            except Exception:
                # Skip items that cannot be represented as a dict
                continue

        # Skip if the resource already has a custom observer schema
        # The attribute name may vary; we check several plausible keys.
        custom_schema = None
        for key in ("observer_schema", "custom_observer_schema", "observer"):
            if key in res_dict:
                custom_schema = res_dict[key]
                break
        if custom_schema is not None:
            # Resource already has a custom schema – skip
            continue

        # Build a minimal default schema.  We use the most common fields; any missing
        # fields are set to None so that later code can handle them gracefully.
        kind = res_dict.get("kind")
        api_version = res_dict.get("api_version") or res_dict.get("apiVersion") or "v1"
        metadata = res_dict.get("metadata", {})
        name = metadata.get("name") if isinstance(metadata, dict) else None

        # The ID is usually a combination of kind and name, but we keep it simple.
        resource_id = f"{kind}/{name}" if kind and name else f"id-{idx}"

        default_schema = {
            "id": resource_id,
            "kind": kind,
            "apiVersion": api_version,
            "metadata": {"name": name} if name else {},
            # Additional fields can be added here as needed.
        }

        # Store the generated schema back into the resource.  If the resource is a
        # dictionary we simply assign a new key.  For attribute‑based objects we attempt
        # to set an attribute; if that fails we skip assigning it.
        if isinstance(res, dict):
            res["default_observer_schema"] = default_schema
        else:
            try:
                setattr(res, "default_observer_schema", default_schema)
            except Exception:
                # If we cannot set an attribute, we record it in the generated_schemas map
                pass

        generated_schemas[resource_id] = default_schema

    # Attach the mapping to the application for future reference.  This is optional and
    # may not be needed by the caller, but provides a convenient cache.
    setattr(app, "_generated_default_observer_schemas", generated_schemas)
    return generated_schemas

