        raise TypeError("manifest_files must be iterable")
    if not isinstance(digests_used, (set, list)):
        raise TypeError("digests_used must be a set or list")

    missing = []
    for mf in manifest_files:
        # Each manifest file is expected to have a 'digest' attribute or key and a 'required' flag
        try:
            digest = mf.digest if hasattr(mf, "digest") else mf.get("digest")
        except Exception:
            raise ValueError(f"Manifest file {mf!r} does not contain a 'digest' value")
        if not digest:
            continue  # skip entries without a digest value
        required = getattr(mf, "required", mf.get("required", False))
        if required and digest not in digests_used:
            missing.append(digest)

    if missing:
        missing_str = ", ".join(str(d) for d in missing)
        raise ValueError(f"Required digests missing or unused: {missing_str}")

    # Optionally, ensure that all used digests have corresponding entries in the manifest
    # (i.e. no digest is used that is not listed at all)
    all_manifest_digests = set()
    for mf in manifest_files:
        try:
            d = mf.digest if hasattr(mf, "digest") else mf.get("digest")
        except Exception:
            continue
        if d:
            all_manifest_digests.add(d)
    unused_digests = set(digests_used) - all_manifest_digests
    if unused_digests:
        unused_str = ", ".join(str(d) for d in unused_digests)
