            if logical_path not in later_map:
                later_map[logical_path] = set()
            later_map[logical_path].update(files_set)

    # Merge later duplicates into current map where applicable
    for log_path, files in curr_map.items():
        if log_path in later_map:
            files.update(later_map[log_path])

    return curr_map

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Basic validation of arguments
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary mapping version identifiers to entries")
    # Convert the requested version to a comparable form
    try:
        target_version = int(version)
    except Exception as exc:
        raise ValueError(f"Provided version '{version}' cannot be interpreted as an integer: {exc}") from exc

    # Prepare result dictionary
    path_map = {}
    # Iterate over all inventory entries whose version is >= target_version
    for v_key, entries in inventory.items():
        try:
            v_num = int(v_key)
        except Exception:
            # Skip non-numeric version keys
            continue
        if v_num < target_version:
            continue
        # Each entry is expected to be a mapping with logical path and a file reference
        if not isinstance(entries, (list, tuple)):
            continue
        for entry in entries:
            if not isinstance(entry, dict):
                continue
            # Guess logical path key
            logical_path = entry.get("logical_path") or entry.get("state_path")
            if logical_path is None:
                # Skip entries without logical path
                continue
            # Guess content file key
            content_file = entry.get("content_file") or entry.get("file") or entry.get("path")
            if content_file is None:
                continue
            # Normalize into set
            if logical_path not in path_map:
                path_map[logical_path] = set()
            path_map[logical_path].add(content_file)

    return path_map

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    path_map = {}
    try:
        # Use inventory as a mapping: version -> list of items
        if isinstance(inventory, dict):
            items = inventory.get(version, [])
            if items is None:
                items = []
            for entry in items:
                try:
                    lp = entry.get("logical_path")
                    cf = entry.get("content_file")
                except AttributeError:
                    continue
                if lp and cf:
                    path_map.setdefault(lp, set()).add(cf)

            # Add duplicates from later versions
            for ver in inventory:
                try:
                    if ver <= version:
                        continue
                except TypeError:
                    continue
                for entry in inventory[ver]:
                    try:
                        lp = entry.get("logical_path")
                        cf = entry.get("content_file")
                    except AttributeError:
                        continue
                    if lp and cf:
                        path_map.setdefault(lp, set()).add(cf)
            return path_map

        # Use inventory as a list (or any iterable) of items
        items = [e for e in inventory if getattr(e, "version", None) == version or getattr(e, "version", None) == self.get("version", None) and e.get("version") == version]
        for entry in items:
            try:
                lp = getattr(entry, "logical_path", None) or entry.get("logical_path")
                cf = getattr(entry, "content_file", None) or entry.get("content_file")
            except Exception:
                continue
            if lp and cf:
                path_map.setdefault(lp, set()).add(cf)

        # Add duplicates from later versions
        for entry in inventory:
            try:
                ver = getattr(entry, "version", None) or entry.get("version")
                if ver is None or ver <= version:
                    continue
                lp = getattr(entry, "logical_path", None) or entry.get("logical_path")
                cf = getattr(entry, "content_file", None) or entry.get("content_file")
                if lp and cf:
                    path_map.setdefault(lp, set()).add(cf)
            except Exception:
                continue
        return path_map

    except Exception:
        # A last-ditch attempt for unknown structures
        for entry in inventory:
            try:
                ver = getattr(entry, "version", None) or entry.get("version")
                if ver is None:
                    continue
                if ver == version or ver > version:
                    lp = getattr(entry, "logical_path", None) or entry.get("logical_path")
                    cf = getattr(entry, "content_file", None) or entry.get("content_file")
                    if lp and cf:
                        path_map.setdefault(lp, set()).add(cf)
            except Exception:
                continue
        return path_map

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Normalise: inventory can be a dict-like or a sequence of items.
    path_map = {}
    if inventory is None:
        return path_map

    # Helper to safely compare versions
    def _ge(v1, v2):
        try:
            return v1 >= v2
        except Exception:
            # If comparison fails, we can't determine suitability
            return False

    # Case 1: inventory behaves like a dict (items() exists)
    items = None
    try:
        items = inventory.items()
    except Exception:
        pass

    if items is not None:
        iterable = items
    else:
        # Assume inventory is an iterable of tuples (key, value)
        try:
            iterable = inventory
        except Exception:
            # Unrecognised structure, abort gracefully
            return path_map

    for key, value in iterable:
        # Determine logical path and version from the key if applicable
        logical_path = None
        key_version = None
        if isinstance(key, tuple):
            # Expect (logical_path, version)
            if len(key) >= 2:
                logical_path, key_version = key[0], key[1]
        else:
            logical_path = key

        if logical_path is None:
            continue  # skip malformed entries

        # Determine the content files to add
        files = set()
        # If the value itself is a dict mapping versions to files
        if isinstance(value, dict) and key_version is None:
            # value: {version: file_path}
            for ver, file_path in value.items():
                if _ge(ver, version):
                    files.add(file_path)
        # If the key already had a version
        elif key_version is not None:
            if _ge(key_version, version):
                # The value might be a file path or a list of paths
                if isinstance(value, (list, set, tuple)):
                    for fp in value:
                        files.add(fp)
                else:
                    files.add(value)
        else:
            # No version info; treat as a file path to include if unspecified
            if isinstance(value, (list, set, tuple)):
                for fp in value:
                    files.add(fp)
            else:
                files.add(value)

        if files:
            path_map.setdefault(logical_path, set()).update(files)

    return path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise TypeError("fixity must be a dict mapping file names to checksum info")
    try:
        file_set = set(manifest_files)
    except TypeError as exc:
        raise TypeError("manifest_files must be an iterable of filenames") from exc

    import re
    hex_re = re.compile(r'^[0-9a-fA-F]+$')
    for fname, checks in fixity.items():
        if fname not in file_set:
            raise ValueError(f"Fixity references unknown file '{fname}' not listed in the manifest.")
        if not isinstance(checks, dict):
            raise TypeError(f"Checksums for file '{fname}' should be a dict")
        for alg, val in checks.items():
            if not isinstance(alg, str):
                raise TypeError(f"Checksum algorithm name must be a string, got {alg!r}")
            if not isinstance(val, str):
                raise TypeError(f"Checksum value for file '{fname}', algorithm '{alg}' must be a string")
            if not hex_re.match(val):
                raise ValueError(f"Checksum value for file '{fname}', algorithm '{alg}' is not valid hex.")
            # Basic length checks for common algorithms
            if alg.lower() == 'sha256' and len(val) != 64:
                raise ValueError(f"Checksum for file '{fname}' using SHA256 should be 64 hex digits.")
            if alg.lower() == 'md5' and len(val) != 32:
                raise ValueError(f"Checksum for file '{fname}' using MD5 should be 32 hex digits.")
    return True

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        if not isinstance(fixity, dict):
            raise ValueError(f"Expected fixity to be a dict, got {type(fixity).__name__}")

        # Ensure all referenced files exist in the manifest
        for fname in fixity:
            if fname not in manifest_files:
                raise ValueError(f"Fixity references unknown file '{fname}' not present in the manifest")

        # Basic validation for checksum values
        allowed_lengths = {32, 40, 64}  # typical MD5, SHA-1, SHA-256 hex lengths
        for fname, checksum in fixity.items():
            if not isinstance(checksum, str):
                raise ValueError(f"Checksum for file '{fname}' must be a string, got {type(checksum).__name__}")
            if len(checksum) not in allowed_lengths:
                raise ValueError(f"Checksum for file '{fname}' has invalid length {len(checksum)}; "
                                 f"expected one of {sorted(allowed_lengths)} hex digits")
        return True

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Allow an empty or missing fixity block
    if fixity is None:
        return True

    # Ensure the fixity block is a list or tuple of entries
    if not isinstance(fixity, (list, tuple)):
        raise ValueError("Fixity block must be a list or tuple")

    # Normalise manifest files to a set for fast membership checks
    if isinstance(manifest_files, (set, list, tuple)):
        manifest_set = set(manifest_files)
    else:
        raise TypeError("manifest_files must be an iterable of file names")

    referenced_files = set()
    for idx, entry in enumerate(fixity):
        # Each entry must be a mapping
        if not isinstance(entry, dict):
            raise ValueError(f"Fixity entry {idx} must be a dict, got {type(entry).__name__}")

        # Require a 'file' key in each entry
        if 'file' not in entry:
            raise ValueError(f"Fixity entry {idx} missing required 'file' key")

        file_name = entry['file']

        # Ensure the referred file is present in the manifest
        if file_name not in manifest_set:
            raise ValueError(
                f"Fixity entry {idx} references unknown file '{file_name}' not found in manifest"
            )

        # Detect duplicate file references within the fixity block
        if file_name in referenced_files:
            raise ValueError(
                f"Duplicate file reference in fixity block: '{file_name}' (found in entry {idx})"
            )
        referenced_files.add(file_name)

    # Optional: check that every manifest file is referenced at least once
    missing = manifest_set - referenced_files
    if missing:
        raise ValueError(
            f"Manifest file(s) missing from fixity block: {', '.join(sorted(missing))}"
        )

    return True

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        # Accept an empty or None block as valid
        if not fixity:
            return True

        # Accept a single dictionary or a list/tuple of dictionaries
        if isinstance(fixity, dict):
            entries = [fixity]
        elif isinstance(fixity, (list, tuple)):
            entries = list(fixity)
        else:
            raise ValueError(f"fixity must be a dict or a list/tuple of dicts, got {type(fixity).__name__}")

        # Each entry must be a dict containing at least a 'file' and a 'checksum' key
        for i, entry in enumerate(entries, start=1):
            if not isinstance(entry, dict):
                raise ValueError(f"Entry {i} in fixity block is not a dict (got {type(entry).__name__})")
            if "file" not in entry:
                raise ValueError(f"Entry {i} missing required 'file' key")
            if "checksum" not in entry:
                raise ValueError(f"Entry {i} missing required 'checksum' key")

            file_path = entry["file"]
            checksum = entry["checksum"]

            if not isinstance(file_path, str) or not file_path:
                raise ValueError(f"Entry {i} has invalid 'file' value: {file_path!r}")
            if not isinstance(checksum, str) or not checksum:
                raise ValueError(f"Entry {i} has invalid 'checksum' value: {checksum!r}")

            # Ensure the referenced file actually exists in the manifest
            if file_path not in manifest_files:
                raise ValueError(
                    f"File '{file_path}' listed in fixity block is not present in the manifest files"
                )

        # If we reach here all checks passed
        return True

