def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package

    Returns
    -------
    dict
    """
    import os

    if not isinstance(folder, str):
        raise TypeError(f"folder must be a str, got {type(folder).__name__}")

    if not os.path.isdir(folder):
        raise FileNotFoundError(f"The specified folder does not exist: {folder}")

    package_data = {}
    try:
        for root, dirs, files in os.walk(folder):
            for fname in files:
                # Skip hidden files
                if fname.startswith('.'):
                    continue
                file_path = os.path.join(root, fname)
                try:
                    rel_path = os.path.relpath(file_path, folder)
                except Exception:
                    # Fallback to absolute path if rel error
                    rel_path = file_path
                stem, ext = os.path.splitext(fname)
                ext = ext.lower()

                if stem not in package_data:
                    package_data[stem] = {}
                # Read content if possible; if binary or unreadable, store None
                content = None
                try:
                    with open(file_path, 'r', encoding='utf-8') as fh:
                        content = fh.read()
                except Exception:
                    # Might be a binary or unsupported encoding
                    pass
                package_data[stem][ext] = {
                    'path': rel_path,
                    'content': content
                }
    except Exception as e:
        raise RuntimeError(f"Error while exploring folder '{folder}': {e}") from e

    return package_data

def _eval_file(prefix, file_path):
    """
    Identifica o tipo de arquivo do pacote: `asset` ou `rendition`.

    Identifica o tipo de arquivo do pacote e atualiza `packages` com o tipo e
    o endereço do arquivo em análise.

    Parameters
    ----------
    prefix : str
        nome do arquivo XML sem extensão
    file_path : str
        full path to the file

    Returns
    -------
    dict
        Dictionary with keys 'type' and 'path' (or 'error' if an exception occurred).
    """
    import os
    packages = {}
    try:
        # Check file existence
        if not os.path.isfile(file_path):
            raise FileNotFoundError(f"File not found: {file_path}")

        # Simple heuristic: file name contains 'asset' or 'rendition'
        lower_name = os.path.basename(file_path).lower()
        if "asset" in lower_name:
            ftype = "asset"
        elif "rendition" in lower_name:
            ftype = "rendition"
        else:
            # Try to parse XML and infer type from root tag or attribute
            try:
                import xml.etree.ElementTree as ET
                tree = ET.parse(file_path)
                root = tree.getroot()
                # check root tag name or an attribute that might indicate type
                tag_lower = root.tag.lower()
                if "asset" in tag_lower:
                    ftype = "asset"
                elif "rendition" in tag_lower:
                    ftype = "rendition"
                else:
                    # look for 'type' attribute
                    type_attr = root.attrib.get("type", "").lower()
                    if type_attr in {"asset", "rendition"}:
                        ftype = type_attr
                    else:
                        ftype = "unknown"
            except Exception:
                ftype = "unknown"

        packages = {"type": ftype, "path": file_path}
    except Exception as exc:
        packages = {"error": str(exc)}
    return packages

