def match_pubdate(node, pubdate_xpaths):
    """Retorna o primeiro match da lista de pubdate_xpaths"""

    # Validate arguments
    if node is None:
        return None
    if not hasattr(node, "find"):
        raise TypeError("`node` must be an Element-like object supporting .find()")
    if not isinstance(pubdate_xpaths, (list, tuple)):
        raise TypeError("`pubdate_xpaths` must be a list or tuple of XPath strings")

    # Iterate through the provided XPath expressions and return the first match
    for xpath in pubdate_xpaths:
        if not isinstance(xpath, str):
            continue  # Skip non-string entries
        try:
            match = node.find(xpath)
            if match is not None:
                return match
        except Exception:
            # Ignore malformed XPath expressions and continue with the next
            continue

    # If none of the XPath expressions matched, return None
    return None

