def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.

    Valores válidos incluem:
        5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
        25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
        s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1,
        suppl, suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    # Get text from the element
    if issue is None:
        return (None, None)
    if hasattr(issue, "text"):
        text = issue.text or ""
    elif hasattr(issue, "get_text"):
        try:
            text = issue.get_text() or ""
        except Exception:
            text = str(issue) or ""
    else:
        text = str(issue) or ""

    text = text.strip()
    if not text:
        return (None, None)

    import re
    # Extract number part (supports optional range like "2-5")
    number_match = re.search(r'(?i)\b(\d+(?:-\d+)?)\b', text)
    number = number_match.group(1) if number_match else None

    # Remove the extracted number from the text
    suppl_part = text
    if number_match:
        suppl_part = text[:number_match.start()] + text[number_match.end():]
    suppl_part = suppl_part.strip()

    # Clean up surrounding punctuation and parentheses
    suppl_part = suppl_part.strip("().,[]{}<>")
    suppl_part = suppl_part.strip()

    if not suppl_part:
        suppl_part = None

    return (number, suppl_part)

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    indent_str = ' ' * indent
    parts = [f"{indent_str}<{self.__class__.__name__}"]
    try:
        # Get attributes either from __dict__ or __slots__
        if hasattr(self, "__dict__"):
            attrs = dict(self.__dict__)
        elif hasattr(self, "__slots__"):
            attrs = {slot: getattr(self, slot) for slot in self.__slots__}
        else:
            attrs = {}
    except Exception:
        attrs = {}

    for name, value in attrs.items():
        try:
            if hasattr(value, "pretty") and callable(value.pretty):
                parts.append("\n" + value.pretty(indent + 2, debug))
            elif isinstance(value, (list, tuple)):
                parts.append(f"\n{indent_str}  {name}: [")
                for item in value:
                    if hasattr(item, "pretty"):
                        parts.append("\n" + item.pretty(indent + 4, debug))
                    else:
                        parts.append("\n" + (' ' * (indent + 4)) + repr(item))
                parts.append(f"\n{indent_str}  ]")
            elif isinstance(value, dict):
                parts.append(f"\n{indent_str}  {name}: {{")
                for dk, dv in value.items():
                    if hasattr(dv, "pretty"):
                        parts.append("\n" + dv.pretty(indent + 4, debug))
                    else:
                        parts.append("\n" + (' ' * (indent + 4)) + f"{dk}: {repr(dv)}")
                parts.append(f"\n{indent_str}  }}")
            else:
                if debug:
                    parts.append(f"\n{indent_str}  {name} ({type(value).__name__}): {repr(value)}")
                else:
                    parts.append(f"\n{indent_str}  {name}: {repr(value)}")
        except Exception:
            parts.append(f"\n{indent_str}  {name}: <error>")

    parts.append(f"\n{indent_str}</{self.__class__.__name__}>")
    return ''.join(parts)

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    if not isinstance(indent, int) or indent < 0:
        raise ValueError("indent must be a non‑negative integer")
    spacer = " " * indent
    lines = [f"{spacer}{self.__class__.__name__}("]
    # simple attributes
    for key, value in vars(self).items():
        if key.startswith("_"):
            continue
        # Represent collections succinctly
        if isinstance(value, (list, tuple, set)):
            val_repr = f"[{len(value)} items]"
        else:
            val_repr = repr(value)
        lines.append(f"{spacer}  {key}={val_repr}")
    # debug information
    if debug:
        for key, value in vars(self).items():
            if not key.startswith("_"):
                continue
            lines.append(f"{spacer}  {key}={value!r}")
    lines.append(f"{spacer})")
    return "\n".join(lines)

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    # Helper to format attributes
    def _attrs(obj):
        attrs = []
        if hasattr(obj, "attrib"):
            for k, v in getattr(obj, "attrib", {}).items():
                attrs.append(f'{k}="{v}"')
        elif hasattr(obj, "attributes"):
            for k, v in getattr(obj, "attributes", {}).items():
                attrs.append(f'{k}="{v}"')
        else:
            # Fallback: use all (non-callable) attributes except common ones
            for k, v in vars(obj).items():
                if k.startswith("_") or k in ("children", "text", "tag"):
                    continue
                if callable(v):
                    continue
                attrs.append(f'{k}="{v}"')
        return attrs

    ind = " " * indent
    # Determine tag name
    tag = getattr(self, "tag", getattr(self, "type", "unknown"))
    attr_str = ""
    attrs = _attrs(self)
    if attrs:
        attr_str = " " + " ".join(attrs)

    # Determine children and text
    children = getattr(self, "children", [])
    text = getattr(self, "text", None)

    # Debug information
    if debug:
        debug_info = f"#{self.__class__.__name__}"
        if getattr(self, "id", None):
            debug_info += f" id={self.id}"
        attr_str = (attr_str + " " + debug_info).strip()

    # Build start tag
    start_tag = f"{ind}<{tag}{attr_str}"
    if not children and (text is None or text == ""):
        return start_tag + "/>"
    else:
        start_tag += ">"

    parts = [start_tag]
    # Add text if present
    if text:
        parts.append(text)

    # Add children recursively
    if children:
        parts.append("\n")
        for child in children:
            if hasattr(child, "pretty") and callable(child.pretty):
                parts.append(child.pretty(indent + 2, debug))
            else:
                # If child is a string or has __str__
                parts.append(" " * (indent + 2) + str(child))
        parts.append("\n" + ind)

    # End tag
    parts.append(f"</{tag}>")
    return "".join(parts)

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    indent_str = "  " * indent
    parts = []

    # Use the class name as the main heading
    head = f"{indent_str}{self.__class__.__name__}"
    # Include an id attribute if present
    if hasattr(self, "id") and self.id is not None:
        head = f"{head} id={self.id}"
    parts.append(head)

    # Pretty‑print simple attributes
    if hasattr(self, "__dict__"):
        for key, value in sorted(self.__dict__.items()):
            # Skip callables and children containers
            if callable(value):
                continue
            if isinstance(value, (list, tuple, set)):
                # Likely a collection of children – skip here
                continue
            if key.startswith("_"):
                continue
            parts.append(f"{indent_str}  {key}={value!r}")

    # Recursively pretty‑print children if the object is iterable or has a
    # 'children' attribute.  We guard against string types and other
    # non‑sequence iterables that are not meant to be treated as children.
    children_iter = None
    if hasattr(self, "__iter__") and not isinstance(self, (str, bytes)):
        try:
            # Attempt to iterate; if it yields elements, use it
            children_iter = iter(self)
            # Allow empty iteration – no error
            next(children_iter, None)
            # Reset iterator for later use
            children_iter = iter(self)
        except Exception:
            children_iter = None

    # Fallback to 'children' attribute if present
    if children_iter is None and hasattr(self, "children"):
        children_iter = iter(self.children)

    if children_iter is not None:
        for child in children_iter:
            try:
                parts.append(child.pretty(indent + 1, debug))
            except Exception:
                # In case the child does not support pretty, fall back to repr
                parts.append(f"{indent_str}  {repr(child)}")

    # Debug information (optional)
    if debug:
        try:
            debug_repr = repr(self)
        except Exception:
            debug_repr = "<repr unavailable>"
        parts.append(f"{indent_str}<Debug: {debug_repr}>")

    return "\n".join(parts)

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    lines = []
    prefix = ' ' * indent
    # Basic representation of the object
    if debug:
        lines.append(f"{prefix}{self.__class__.__name__} (id={id(self)})")
    else:
        lines.append(f"{prefix}{self.__class__.__name__}")
    # Add non-private, non-callable attributes
    attrs = []
    for key, value in vars(self).items():
        if not key.startswith('_') and not callable(value):
            attrs.append(f"{key}={value!r}")
    if attrs:
        lines[-1] += ' [' + ', '.join(attrs) + ']'
    # Determine children to recurse on
    children = None
    if hasattr(self, 'children'):
        children = self.children
    elif isinstance(self, (list, tuple)):
        children = self
    else:
        try:
            children = list(self)
        except Exception:
            children = None
    # Pretty-print each child
    if children:
        for child in children:
            if hasattr(child, 'pretty') and callable(child.pretty):
                lines.append(child.pretty(indent + 4, debug))
            else:
                lines.append(' ' * (indent + 4) + repr(child))
    return '\n'.join(lines)

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def are_same(e1, e2):
        if e1 is e2:
            return True
        if isinstance(e1, tuple) and isinstance(e2, tuple):
            if len(e1) != len(e2):
                return False
            return all(are_same(a, b) for a, b in zip(e1, e2))
        return e1 == e2

    def simplify(expr):
        # Base case: non-tuple (literal or variable)
        if not isinstance(expr, tuple):
            return expr
        op = expr[0]
        # Recursively simplify children
        if op in ('&', '|'):
            left = simplify(expr[1])
            right = simplify(expr[2])

            # Absorption handling
            if op == '&':
                if isinstance(right, tuple) and right[0] == '|':
                    # A & (A | B) -> A
                    if are_same(left, right[1]) or are_same(left, right[2]):
                        return left
                    # Negative absorption A & (~A | B) -> A & B
                    neg_left = (isinstance(right[1], tuple) and right[1][0] == '~' and are_same(left, right[1][1]))
                    neg_right = (isinstance(right[2], tuple) and right[2][0] == '~' and are_same(left, right[2][1]))
                    if neg_left or neg_right:
                        # pick the non-negated part
                        other = right[2] if neg_left else right[1]
                        return ('&', left, other)
            else:  # op == '|'
                if isinstance(right, tuple) and right[0] == '&':
                    # A | (A & B) -> A
                    if are_same(left, right[1]) or are_same(left, right[2]):
                        return left
                    # Negative absorption A | (~A & B) -> A | B
                    neg_left = (isinstance(right[1], tuple) and right[1][0] == '~' and are_same(left, right[1][1]))
                    neg_right = (isinstance(right[2], tuple) and right[2][0] == '~' and are_same(left, right[2][1]))
                    if neg_left or neg_right:
                        other = right[2] if neg_left else right[1]
                        return ('|', left, other)

            return (op, left, right)
        else:
            # Unknown operator: just return as is
            return expr

    if args is None:
        return []
    try:
        iterator = iter(args)
    except TypeError:
        raise TypeError("absorb expects an iterable of expressions") from None

    result = []
    for expr in iterator:
        result.append(simplify(expr))
    return result

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.
    """
    if not isinstance(hook, HookType):
        raise TypeError("hook must be a HookType instance, got %r" % hook)

    # Ensure the registry exists
    if not hasattr(self, "_registry"):
        self._registry = {}

    def decorator(func):
        if not callable(func):
            raise TypeError("listener must be callable, got %r" % func)
        # Store the handler in the registry
        self._registry.setdefault(hook, []).append(func)
        return func

    return decorator

def on(self, hook):
        """Decorator function to add a new handler to the registry.

        Args:
            hook (HookType): Hook attribute for which to register the handler.

        Returns:
            callable: Decorator for registering listeners for the specified
            hook.
        """
        # Ensure the internal handler registry exists
        if not hasattr(self, "_handlers"):
            self._handlers = {}

        # Validate hook type if a HookType is defined; otherwise accept any hashable
        try:
            from typing import TYPE_CHECKING
            if not isinstance(hook, type(hook)):
                # If HookType is an enum or custom class, this check will succeed
                pass
        except Exception:
            # If HookType is not defined or cannot be imported, proceed without checks
            pass

        # If this hook was never seen before create a list for it
        if hook not in self._handlers:
            self._handlers[hook] = []

        def decorator(func):
            """Register a listener function for the specified hook."""
            if not callable(func):
                raise TypeError("Registered handler must be callable")
            # Avoid duplicate registrations
            if func not in self._handlers[hook]:
                self._handlers[hook].append(func)
            return func

        return decorator

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.
    """
    # Basic validation for the hook type
    try:
        isinstance_hook = isinstance
        HookType  # noqa: F821 - assumed imported elsewhere
    except NameError:
        # If HookType is not defined, skip the check
        isinstance_hook = lambda obj, cls: True
    else:
        isinstance_hook = isinstance

    if not isinstance_hook(hook, HookType):
        raise TypeError(f"hook must be a HookType instance, got {type(hook).__name__}")

    def decorator(func):
        if not callable(func):
            raise TypeError(f"listener {func!r} is not callable")
        # Ensure the registry dict exists
        if not hasattr(self, "_listener_registry"):
            self._listener_registry = {}
        registry = self._listener_registry
        # Avoid duplicate registration of the same function
        hooks_list = registry.setdefault(hook, [])
        if func in hooks_list:
            raise ValueError(f"listener {func.__name__} already registered for hook {hook}")
        hooks_list.append(func)
        return func

    return decorator

def base_config(user, etcd_host="localhost", etcd_port=2379):
    """Creates a configuration with some simple parameters, which have a default value
    that can be set.

    Args:
        user (str): the name of the user for the static authentication
        etcd_host (str): the host for the database.
        etcd_port (int): the port for the database.

    Returns:
        dict: the created configuration.

    """
    # Basic validation of inputs
    try:
        if not isinstance(user, str) or not user:
            raise TypeError("`user` must be a non-empty string")
        if not isinstance(etcd_host, str) or not etcd_host:
            raise TypeError("`etcd_host` must be a non-empty string")
        if not isinstance(etcd_port, int):
            raise TypeError("`etcd_port` must be an integer")
        if not (0 < etcd_port < 65536):
            raise ValueError("`etcd_port` must be in the range 1-65535")
    except Exception as e:
        # Re-raise with a clear message
        raise ValueError(f"Invalid configuration parameters: {e}") from None

    config = {
        "user": user,
        "etcd_host": etcd_host,
        "etcd_port": etcd_port,
    }
    return config

def _fromutc(self, dt):
    """Given a timezone-aware datetime in a given timezone, calculates a
    timezone-aware datetime in a new timezone.

    Since this is the one time that we *know* we have an unambiguous
    datetime object, we take this opportunity to determine whether the
    datetime is ambiguous and in a "fold" state (e.g. if it's the first
    occurrence, chronologically, of the ambiguous datetime).

    :param dt:
        A timezone-aware :class:`datetime.datetime` object.
    """
    # Ensure the input is timezone-aware
    if dt.tzinfo is None:
        raise ValueError("dt must be a timezone‑aware datetime")
    # Determine if the datetime is ambiguous and adjust fold if needed
    try:
        # Create two versions of the datetime with different fold values.
        fold0 = dt.replace(fold=0)
        fold1 = dt.replace(fold=1)
        offset0 = fold0.utcoffset()
        offset1 = fold1.utcoffset()
        if offset0 is not None and offset1 is not None and offset0 != offset1:
            # dt is ambiguous; choose the correct fold based on the current utcoffset
            current_offset = dt.utcoffset()
            if current_offset == offset1:
                dt = fold1
            else:
                dt = fold0
    except Exception:
        # If the timezone doesn't support fold, ignore the adjustment
        pass
    # Convert to the target timezone (self)
    try:
        return dt.astimezone(self)
    except Exception:
        # Fallback: force replace tzinfo if a direct conversion fails
        return dt.replace(tzinfo=self)

def tzname_in_python2(namefunc):
    import sys
    def wrapper(*args, **kwargs):
        result = namefunc(*args, **kwargs)
        if sys.version_info[0] < 3:
            try:
                # In Python 2, unicode type is available
                if isinstance(result, unicode):
                    return result.encode('utf-8')
            except NameError:
                # pragma: no cover, in unexpected Python versions
                pass
        return result
    return wrapper

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes,
    but was changed to unicode strings
    """
    import sys
    if sys.version_info[0] >= 3:
        # In Python 3 tzname already returns a str (unicode), so just return the original
        return namefunc

    # In Python 2 the tzname may return a unicode string; convert it to a byte string
    def wrapper(*args, **kwargs):
        result = namefunc(*args, **kwargs)
        try:
            # In Python 2, unicode type exists
            if isinstance(result, unicode):
                return result.encode('utf-8')
        except NameError:
            # Fallback if unicode is not defined (shouldn't happen in py2)
            if isinstance(result, str):
                return result
        return result

    return wrapper

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    import sys
    import functools
    try:
        _unicode = unicode  # Python 2
    except NameError:
        _unicode = str      # Python 3

    @functools.wraps(namefunc)
    def wrapper(*args, **kwargs):
        value = namefunc(*args, **kwargs)
        if sys.version_info[0] < 3 and isinstance(value, _unicode) and not isinstance(value, bytes):
            # Convert unicode to bytes using UTF-8 (common choice)
            return value.encode('utf-8')
        return value

    return wrapper

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    if sys.version_info[0] < 3:
        def wrapper(*args, **kwargs):
            value = namefunc(*args, **kwargs)
            if isinstance(value, unicode):
                return value.encode('utf-8')
            return value
        return wrapper
    else:
        return namefunc

def get_versions():
    """Get version information or return default if unable to do so."""
    import subprocess, sys
    versions = {}
    # Determine package name from module namespace or environment
    try:
        pkg_name = __package__ or __name__.split('.')[0]
    except Exception:
        pkg_name = None
    # Attempt to get distribution version via importlib.metadata
    try:
        from importlib import metadata
    except ImportError:
        try:
            import pkg_resources
            metadata = pkg_resources
        except ImportError:
            metadata = None
    if metadata and pkg_name:
        try:
            if hasattr(metadata, 'version'):
                versions['version'] = metadata.version(pkg_name)
            elif hasattr(metadata, 'get_distribution'):
                versions['version'] = metadata.get_distribution(pkg_name).version
        except Exception:
            pass
    # Attempt to get git commit hash
    try:
        commit = subprocess.check_output(
            ['git', 'rev-parse', 'HEAD'],
            stderr=subprocess.DEVNULL,
            cwd=sys.path[0]
        )
        versions['commit'] = commit.decode('utf-8').strip()
    except Exception:
        pass
    if not versions:
        versions = {'version': 'unknown'}
    return versions

def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        from importlib.metadata import version, PackageNotFoundError
        pkg = __package__ or __name__
        if pkg in ["__main__", None]:
