    default = {'version': '0.0.0', 'build': None}
    # First try setuptools/pkg_resources
    try:
        import pkg_resources
        distribution = pkg_resources.get_distribution(__name__ or '')
        return {'version': distribution.version, 'build': distribution.parsed_version}
