    # Then try importlib.metadata (Python 3.8+)
    try:
        from importlib import metadata
        return {'version': metadata.version(__name__ or ''), 'build': None}
    except Exception:
        pass
    # As a last resort, try pkg_resources with the package's top-level name
    try:
