    import subprocess
    import sys
    import os

    # Prepare command list
    if isinstance(commands, str):
        cmd = [commands]
    else:
        try:
            cmd = list(commands)
        except TypeError:
            raise TypeError("commands must be a string or an iterable of strings")

    if args:
        if isinstance(args, str):
            args = [args]
        try:
            cmd.extend(args)
        except TypeError:
            raise TypeError("args must be a string or an iterable of strings")

    # Merge environment if provided
    if env is not None:
        environment = os.environ.copy()
        environment.update(env)
    else:
        environment = None

    try:
        if verbose:
            result = subprocess.run(
                cmd,
                cwd=cwd,
                env=environment,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
