    """Create decorator to mark a method as the handler of a VCS."""
    if not isinstance(vcs, str):
        raise TypeError("vcs must be a string identifier")
    # Initialize registry on the function if not already present
    if not hasattr(register_vcs_handler, "registry"):
        register_vcs_handler.registry = {}
    if method is None:
        # Decorator called with arguments: return the real decorator
        def decorator(func):
            if not callable(func):
                raise TypeError("decorated object must be callable")
            register_vcs_handler.registry[vcs] = func
            return func
        return decorator
    # Decorator called directly with the function
    if not callable(method):
        raise TypeError("method must be callable")
    register_vcs_handler.registry[vcs] = method
    return method

def register_vcs_handler(vcs, method):
