def initialize(self):
    """Create and initialize a new OCFL storage root."""
    import os
    import json

    # Validate that the root path has been set
    if not hasattr(self, "root") or not self.root:
        raise ValueError("Instance attribute 'root' must be set before initialization")

    # Create the root directory
    try:
        os.makedirs(self.root, exist_ok=True)
    except OSError as exc:
        raise RuntimeError(
            f"Failed to create OCFL storage root at {self.root!r}"
        ) from exc

    # Create required subdirectories
    required_subdirs = ["objects", "layouts", "archives"]
    for sub in required_subdirs:
        sub_path = os.path.join(self.root, sub)
        try:
            os.makedirs(sub_path, exist_ok=True)
        except OSError as exc:
            raise RuntimeError(
                f"Failed to create subdirectory {sub_path!r}"
            ) from exc

    # Create an empty manifest file if it does not exist
    manifest_path = os.path.join(self.root, "manifest.json")
    if not os.path.exists(manifest_path):
        try:
            with open(manifest_path, "w", encoding="utf-8") as f:
                json.dump({}, f)
        except (OSError, IOError) as exc:
            raise RuntimeError(
                f"Failed to create manifest at {manifest_path!r}"
            ) from exc

    # Mark the storage as initialized
    self.initialized = True
    return self.root

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError('`version` must be a string')

    if not version.isdigit():
        raise ValueError('`version` must consist of digits only')

    original_len = len(version)
    try:
        number = int(version)
    except ValueError:
        raise ValueError('`version` cannot be converted to an integer')

    number += 1

    new_version = str(number)
    if len(new_version) < original_len:
        # Preserve leading zeros
        new_version = new_version.zfill(original_len)
    return new_version

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")

    # Find trailing numeric part
    i = len(version) - 1
    while i >= 0 and version[i].isdigit():
        i -= 1

    num_part = version[i + 1:]
    prefix = version[:i + 1]

    if not num_part:
        raise ValueError("No numeric suffix found in version")

    leading_zero = num_part[0] == '0' and len(num_part) > 1
    try:
        num = int(num_part)
    except ValueError:
        raise ValueError(f"Numeric part '{num_part}' is not a valid integer")

    num += 1

    if leading_zero:
        new_num = f"{num:0{len(num_part)}d}"
    else:
        new_num = str(num)

    return prefix + new_num

def validate_version_inventories(self, version_dirs):
        """Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        import os

        # Prepare container for digests that differ from the root inventory
        self.different_digests = {}
        # Keep track of the entries that were present in the previous version
        previous_entries = set()

        # Helper to load an inventory file as a dictionary {filename: digest}
        def _load_inventory(path):
            inventory = {}
            if not os.path.isfile(path):
                raise FileNotFoundError(f"Inventory file missing: {path}")
            with open(path, 'r', encoding='utf-8') as f:
                for line in f:
                    line = line.strip()
                    if not line or line.startswith('#'):
                        continue
                    parts = line.split(None, 1)
                    if len(parts) != 2:
                        continue
                    # Detect common formats: 'digest filename' or 'filename digest'
                    if len(parts[0]) == 40:  # rough SHA‑1 length
                        digest, filename = parts
                    else:
                        filename, digest = parts
                    inventory[filename] = digest
            return inventory

        # Ensure we have a root inventory reference. If not yet loaded, attempt to load it.
        if not hasattr(self, 'root_inventory') or not isinstance(self.root_inventory, dict):
            root_inventory_path = os.path.join(self.root_dir, 'inventory')
            if os.path.isfile(root_inventory_path):
                self.root_inventory = _load_inventory(root_inventory_path)
            else:
                self.root_inventory = {}

        # Iterate through all provided version directories in order
        for idx, dirname in enumerate(version_dirs):
            inv_path = os.path.join(dirname, 'inventory')
            current_inventory = _load_inventory(inv_path)

            # Validate that this inventory contains all files from previous versions
            missing_files = previous_entries - set(current_inventory.keys())
            if missing_files and idx > 0:
                msg = f"Version {idx + 1} inventory missing files: {', '.join(sorted(missing_files))}"
                raise ValueError(msg)

            # Record any digest differences compared with the root inventory
            for fname, digest in current_inventory.items():
                root_digest = self.root_inventory.get(fname)
                if root_digest and digest != root_digest:
                    self.different_digests.setdefault(fname, (root_digest, digest))

            # Update the set of files we know about for the next iteration
            previous_entries = set(current_inventory.keys())

        # No explicit return value needed – differences are stored in self.different_digests.

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Assume self.root_inventory is a dict mapping file paths to their digests.
    if not hasattr(self, 'root_inventory') or not isinstance(self.root_inventory, dict):
        raise AttributeError("The object must have a 'root_inventory' dictionary defined.")

    # Store discrepant digests as a list of tuples: (version, path, root_digest, version_digest)
    self.differing_digests = []

    # ImportPath, ElementTree, and os are assumed to be available globally.
    for vdir in version_dirs:
        inv_path = os.path.join(vdir, 'inventory.xml')
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Missing inventory file in version directory '{vdir}'.")

        # Parse the inventory XML
        try:
            tree = ET.parse(inv_path)
        except ET.ParseError as e:
            raise ValueError(f"Failed to parse inventory XML at '{inv_path}': {e}")

        root = tree.getroot()

        # Iterate through each item entry; adjust tag names if necessary.
        for item in root.findall('.//item'):
            path = item.get('path')
            if path is None:
                continue  # skip malformed entries
            digest = item.get('digest')
            if digest is None:
                continue

            if path in self.root_inventory:
                root_digest = self.root_inventory[path]
                if digest != root_digest:
                    self.differing_digests.append((vdir, path, root_digest, digest))
            else:
                # New path in this version; nothing to compare against root inventory.
                continue

    # If no exceptions were raised, validation succeeded.
    return True

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    from pathlib import Path
    try:
        p = Path(path)
    except Exception as e:
        return f'invalid path: {e}'

    if not p.exists():
        return 'path does not exist'

    if p.is_file():
        return 'file'

    if not p.is_dir():
        return 'not a directory'

    # Check for an OCFL Object: directory contains a subdirectory called "0"
    # which in turn contains a file starting with "0=" (a Namaste file)
    for sub in p.iterdir():
        if sub.is_dir() and sub.name == '0':
            for child in sub.iterdir():
                if child.is_file() and child.name.startswith('0='):
                    return 'object'
    # If not an object but has child directories, it is probably a storage root
    if any(child.is_dir() for child in p.iterdir()):
        return 'root'
    # If we get here, it's an empty directory or an unrecognised structure
    return 'unknown directory type'

import os
import re

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    # Basic path checks
    if not os.path.exists(path):
        return f"Path does not exist: {path}"
    if os.path.isfile(path):
        return 'file'
    if not os.path.isdir(path):
        return f"Unknown path type: {path}"

    # Helper: find files that matches the pattern 0=*
    def has_namaste_files(directory):
        try:
            return any(f.startswith('0=') and os.path.isfile(os.path.join(directory, f))
                       for f in os.listdir(directory))
        except OSError:
            return False

    # 1. Check for storage root indicators
    #    Many OCFL storage roots contain a marker file named `.ocfl_forest`
    #    and a subdirectory called `objects` that holds the individual objects.
    #    This is the most reliable and straightforward heuristic.
    if os.path.isfile(os.path.join(path, '.ocfl_forest')):
        if os.path.isdir(os.path.join(path, 'objects')):
            return 'root'

    # 2. Check if the directory itself looks like an object.
    #    An object root contains “Namaste” files named `0=*` that
    #    describe the versioned content.  We simply look for the
    #    presence of at least one such file.
    if has_namaste_files(path):
        return 'object'

    # 3. If we can't determine, return a helpful error string.
    try:
        entries = os.listdir(path)
    except OSError as exc:
        return f"Error accessing directory {path!r}: {exc}"
    if not entries:
        return f"Empty directory: {path}"
    return f"Could not identify OCFL component at {path}"

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    try:
        if not os.path.exists(path):
            return 'not found'
        if not os.path.isdir(path):
            return 'file'

        # look for Namaste files ("0=*") in the directory
        for fname in os.listdir(path):
            if fname.startswith('0='):
                full = os.path.join(path, fname)
                try:
                    with open(full, 'r', encoding='utf-8') as f:
                        content = f.read()
                except Exception as e:
                    return f'error reading {fname}: {e}'

                # simple heuristic: if the file contains known OCFL markers
                content_low = content.lower()
                if 'ocfl root' in content_low or 'ocfl_storage' in content_low:
                    return 'root'
                if 'ocfl object' in content_low or 'object' in content_low:
                    return 'object'

        # If we didn't find any Namaste file or markers we can't decide
        return 'unknown'

    except Exception as e:
        return f'error: {e}'

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    # Basic type checks
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")
    if bug_ids is None:
        raise ValueError("bug_ids must not be None")
    # Convert bug_ids to a comma‑separated string
    if isinstance(bug_ids, (int, str)):
        ids_str = str(bug_ids)
    else:
        try:
            ids_str = ','.join(str(bid) for bid in bug_ids)
        except Exception as exc:
            raise ValueError("bug_ids must be an int, str or an iterable of them") from exc
    # Bugzilla expects 'ids' for multiple IDs and 'id' for a single ID
    if ',' in ids_str:
        params['ids'] = ids_str
    else:
        params['id'] = ids_str
    return params

def amend_bzparams(self, params, bug_ids):
        """Amend the Bugzilla params"""
        if params is None:
            params = {}
        if not isinstance(params, dict):
            raise ValueError("params must be a dictionary")
        if bug_ids is None:
            return params

        # Normalize bug_ids to a list of integers
        try:
            if isinstance(bug_ids, str):
                bug_ids = [int(x) for x in bug_ids.split(",") if x.strip()]
            else:
                bug_ids = [int(x) for x in bug_ids]
        except Exception as exc:
            raise ValueError("bug_ids must be an iterable of integers or a comma‑separated string") from exc

        # Merge with any existing ids in params
        existing = params.get("ids")
        if existing:
            if isinstance(existing, list):
                existing_ids = [int(x) for x in existing]
            else:
                try:
                    existing_ids = [int(x.strip()) for x in str(existing).split(",") if x.strip()]
                except Exception as exc:
                    raise ValueError("existing params['ids'] must be a list or comma‑separated string of integers") from exc
            merged_ids = list(set(existing_ids + bug_ids))
        else:
            merged_ids = list(set(bug_ids))

        # Bugzilla expects ids as a comma‑separated string
        params["ids"] = ",".join(str(i) for i in sorted(merged_ids))
        return params

def deep_merge_nodes(nodes):  # pragma: no cover
    """
    Deep-merge a list of YAML node tuples.

    Parameters
    ----------
    nodes : list[tuple[ruamel.yaml.nodes.ScalarNode, ruamel.yaml.nodes.Node]]
        A list of (key, value) tuples where ``key`` is a ScalarNode and
        ``value`` is either a MappingNode or another node type.

    Returns
    -------
    list[tuple[ruamel.yaml.nodes.ScalarNode, ruamel.yaml.nodes.Node]]
        A new list where duplicate keys are merged. For MappingNode values,
        subkeys are recursively merged. For non-MappingNode colliding values,
        the last seen value wins.

    Notes
    -----
    The function assumes that ``MappingNode`` objects expose a ``value`` attribute
    that is a list of (key_node, value_node) tuples and a ``tag`` attribute.
    Other node types are left untouched.
    """
    # Helper that merges two MappingNodes, mutating ``first`` and returning it.
    def _merge_mapping_nodes(first, second):
        # Build dict for fast key lookup in first
        first_map = {k.value: v for k, v in first.value}
        # Iterate over second mapping keys
        for skey, svalue in second.value:
            key = skey.value
            if key in first_map:
                fvalue = first_map[key]
                # If both are mappings, merge recursively
                if hasattr(fvalue, "value") and hasattr(svalue, "value"):
                    if first_map[key].tag.startswith("tag:yaml.org,2002:map"):
                        # Recursively merge
                        _merge_mapping_nodes(first_map[key], svalue)
                        # Ensure order: drop old entry, re-add merged
                        # Remove second entry from first.value list
                        for i, (knode, vnode) in enumerate(first.value):
                            if knode.value == key:
                                first.value[i] = (skey, first_map[key])
                                break
                    else:
                        # Replace non-mapping value with second
                        first_map[key] = svalue
                        for i, (knode, vnode) in enumerate(first.value):
                            if knode.value == key:
                                first.value[i] = (skey, svalue)
                                break
                else:
                    # Non-mapping: replace with second value
                    first_map[key] = svalue
                    for i, (knode, vnode) in enumerate(first.value):
                        if knode.value == key:
                            first.value[i] = (skey, svalue)
                            break
            else:
                # New key: append
                first.value.append((skey, svalue))
                first_map[key] = svalue
        return first

    merged = {}
    key_nodes = {}
    for key_node, value_node in nodes:
        key = key_node.value
        if key in merged:
            existing_value = merged[key]
            # If both values are mapping nodes, merge deep
            if hasattr(existing_value, "value") and hasattr(value_node, "value"):
                if existing_value.tag.startswith("tag:yaml.org,2002:map"):
                    merged[key] = _merge_mapping_nodes(existing_value, value_node)
                else:
                    # last wins
                    merged[key] = value_node
            else:
                merged[key] = value_node
        else:
            merged[key] = value_node
            key_nodes[key] = key_node

    # Preserve order as first appearance
    result = []
    seen = set()
    for key_node, value_node in nodes:
        key = key_node.value
        if key not in seen:
            result.append((key_nodes[key], merged[key]))
            seen.add(key)
    return result

def deep_merge_nodes(nodes):
    """
    Deep merge a list of (key, value) node tuples whose keys are ScalarNodes
    and values can be MappingNodes or other node types. Duplicate keys whose
    values are MappingNodes are recursively merged; otherwise the last value
    wins.
    """
    if not isinstance(nodes, list):
        raise TypeError('nodes must be a list of tuples')
    result = []
    index_of_key = {}  # maps key value to index in result

    def is_mapping(node):
        return getattr(node, 'tag', None) == 'tag:yaml.org,2002:map' and hasattr(node, 'value')

    def merge_mapping_nodes(node1, node2):
        """
        Merge the mapping node `node2` into `node1`. The merged content
        replaces `node1.value`.
        """
        seen_keys = {}
        # first pass: node1 items
        for k, v in node1.value:
            key_val = getattr(k, 'value', None)
            seen_keys[key_val] = (k, v)
        # second pass: node2 items
        for k, v in node2.value:
            key_val = getattr(k, 'value', None)
            if key_val in seen_keys:
                old_k, old_v = seen_keys[key_val]
                if is_mapping(old_v) and is_mapping(v):
                    merge_mapping_nodes(old_v, v)
                    seen_keys[key_val] = (old_k, old_v)
                else:
                    seen_keys[key_val] = (k, v)  # last wins, keep key from node2
            else:
                seen_keys[key_val] = (k, v)
        # restore in order: node1 order first, then new nodes from node2
        merged = []
        for k, v in node1.value:
            key_val = getattr(k, 'value', None)
            if key_val in seen_keys:
                merged_k, merged_v = seen_keys.pop(key_val)
                merged.append((merged_k, merged_v))
        for k, v in node2.value:
            key_val = getattr(k, 'value', None)
            if key_val in seen_keys:
                merged_k, merged_v = seen_keys.pop(key_val)
                merged.append((merged_k, merged_v))
        node1.value = merged

    for key_node, val_node in nodes:
        if not hasattr(key_node, 'value'):
            raise ValueError('Key node has no value attribute')
        key_val = key_node.value
        if key_val in index_of_key:
            idx = index_of_key[key_val]
            current_key, current_val = result[idx]
            if is_mapping(current_val) and is_mapping(val_node):
                merge_mapping_nodes(current_val, val_node)
                result[idx] = (current_key, current_val)
            else:
                # last wins
                result[idx] = (key_node, val_node)
        else:
            result.append((key_node, val_node))
            index_of_key[key_val] = len(result) - 1
    return result

def deep_merge_nodes(nodes):
    """
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    """
    from ruamel.yaml.nodes import ScalarNode, MappingNode

    if not isinstance(nodes, (list, tuple)):
        raise TypeError("nodes must be a list or tuple of (ScalarNode, Node) tuples")

    # Helper that merges two MappingNode instances, returning a new MappingNode
    def _merge_mapping(node1, node2):
        # Build a mapping from key string to (key_node, value_node) for node1
        merged_items = {}
        for k, v in node1.value:
            merged_items[k.value] = (k, v)

        # Iterate over node2 items, merging or adding
        for k2, v2 in node2.value:
            k = k2.value
            if k in merged_items:
                _, existing_v = merged_items[k]
                if isinstance(existing_v, MappingNode) and isinstance(v2, MappingNode):
                    merged_v = _merge_mapping(existing_v, v2)
                else:
                    merged_v = v2  # last wins
                merged_items[k] = (merged_items[k][0], merged_v)
            else:
                merged_items[k] = (k2, v2)

        # Preserve order: start with original node1 items, then add new ones from node2
        result_list = []
        seen_keys = set()
        for k, _ in node1.value:
            result_list.append((k, merged_items[k][1]))
            seen_keys.add(k.value)
        for k, _ in node2.value:
            if k.value not in seen_keys:
                result_list.append((k, merged_items[k][1]))
                seen_keys.add(k.value)

        return MappingNode(node1.tag, result_list)

    merged_dict = {}  # key string -> (key_node, value_node)
    for key_node, val_node in nodes:
        if not isinstance(key_node, ScalarNode):
            raise TypeError("Key must be a ScalarNode")
        key = key_node.value

        if key in merged_dict:
            existing_key_node, existing_val_node = merged_dict[key]
            if isinstance(existing_val_node, MappingNode) and isinstance(val_node, MappingNode):
                merged_val = _merge_mapping(existing_val_node, val_node)
                merged_dict[key] = (existing_key_node, merged_val)
            else:
                # last wins; keep original key node
                merged_dict[key] = (existing_key_node, val_node)
        else:
            merged_dict[key] = (key_node, val_node)

    # Return list of tuples preserving the order in which unique keys first appeared
    return list(merged_dict.values())

def parser_flags(parser):
    '''Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.'''
    # Basic sanity check
    if not hasattr(parser, "_actions"):
        raise TypeError("Expected an argparse.ArgumentParser instance, got %r" % parser)
    flags = []
    for action in parser._actions:
        option_strings = getattr(action, "option_strings", None)
        if option_strings:
            flags.extend(option_strings)
    return " ".join(flags)

def parser_flags(parser):
    """Return the option flags of an argparse.ArgumentParser as a space‑separated string."""
    flags = []
    for action in getattr(parser, "_actions", []):
        # ``option_strings`` is a list of the flag names (e.g. ['--file', '-f'])
        flags.extend(action.option_strings)
    return " ".join(flags)

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space‑separated string.

    Parameters
    ----------
    parser : argparse.ArgumentParser
        The parser from which to extract the flags.

    Returns
    -------
    str
        A space‑separated string of all option flags registered with the parser.
    """
    if not hasattr(parser, "_actions"):
        raise ValueError("The provided object does not have the '_actions' attribute and is probably not an argparse.ArgumentParser instance.")
    try:
        flags = []
        for action in parser._actions:
            # Only actions that define option_strings are relevant
            if hasattr(action, "option_strings"):
                flags.extend(action.option_strings)
        # Remove duplicates while preserving order
        seen = set()
        unique_flags = []
        for f in flags:
            if f not in seen:
                seen.add(f)
                unique_flags.append(f)
        return " ".join(unique_flags)
    except Exception as exc:
        raise RuntimeError(f"Unable to extract flags from the parser: {exc}") from exc

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags
    in a space-separated string.
    """
    if not hasattr(parser, "_actions"):
        raise TypeError("Expected an argparse.ArgumentParser instance")
    flags = []
    for action in parser._actions:
        # skip actions that do not represent options (e.g. positional arguments)
        option_strings = getattr(action, "option_strings", [])
        if option_strings:
            flags.extend(option_strings)
    # Preserve order and remove duplicates
    seen = set()
    unique_flags = []
    for flag in flags:
        if flag not in seen:
            seen.add(flag)
            unique_flags.append(flag)
    return " ".join(unique_flags)

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space‑separated
    string.
    '''
    # Ensure we are dealing with an ArgumentParser instance
    try:
        from argparse import ArgumentParser
    except ImportError as exc:
        raise RuntimeError("argparse module is required") from exc

    if not isinstance(parser, ArgumentParser):
        raise TypeError(f"Expected an argparse.ArgumentParser, got {type(parser).__name__}")

    flags = []
    # argparse stores all actions in the private _actions list
    for action in getattr(parser, "_actions", []):
        # action.option_strings holds the flag names (e.g. ['-f', '--file'])
        if action.option_strings:
            flags.extend(action.option_strings)

    return " ".join(flags)

def parse_arguments(*unparsed_arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    import argparse

    # Create a top‑level parser.  Any subparsers that are defined elsewhere
    # (via parser.add_subparsers()) will be automatically handled when the
    # script is executed.  For the purpose of this utility we only need
    # to capture the global arguments; any unknown arguments are returned
    # under the same "global" namespace and can be processed
    # later if required.
    parser = argparse.ArgumentParser()
    try:
        namespace, _ = parser.parse_known_args(unparsed_arguments)
    except Exception:
        # If parsing fails for any unexpected reason, fall back to
        # an empty Namespace to avoid crashing the calling script.
        namespace = argparse.Namespace()

    return {'global': namespace}

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    from collections import Counter

    parsed = {}
    recognized_counts = Counter()
    args_tokenized = list(unparsed_arguments)

    for name, parser in subparsers.items():
        try:
            namespace, remainder = parser.parse_known_args(args_tokenized)
        except SystemExit:
            # If parsing fails (e.g., due to required arguments missing or help requested),
            # skip this subparser.
            continue
        parsed[name] = namespace
        # Count arguments recognized by this parser as those removed from the original list
        recognized_counts += Counter(args_tokenized) - Counter(remainder)

    # Build the list of remaining arguments preserving original order
    remaining = []
    for token in args_tokenized:
        if recognized_counts[token] > 0:
            recognized_counts[token] -= 1
        else:
            remaining.append(token)

    return parsed, remaining

def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This
    allows common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed
    namespace of arguments, a list of remaining arguments not claimed by any subparser).
    """
    if not isinstance(subparsers, dict):
        raise TypeError("subparsers must be a dict of name -> ArgumentParser")
    unparsed = list(unparsed_arguments)
    parsed_map = {}
    remaining_lists = []

    for name, parser in subparsers.items():
        if not hasattr(parser, "parse_known_args"):
            raise TypeError(f"Parser for subparser '{name}' does not support parse_known_args")
        try:
            namespace, remaining = parser.parse_known_args(unparsed)
        except Exception:
            # If parsing fails for a particular subparser, we still record None and
            # treat all arguments as remaining for that subparser.
            namespace = None
            remaining = list(unparsed)
        parsed_map[name] = namespace
        remaining_lists.append(list(remaining))

    # Arguments that are not claimed by any subparser are those present in every
    # remaining list. Preserve original order.
    if remaining_lists:
        remaining_set = set.intersection(*(set(r) for r in remaining_lists))
        remaining_unclaimed = [arg for arg in unparsed if arg in remaining_set]
    else:
        remaining_unclaimed = list(unparsed)

    return parsed_map, remaining_unclaimed

def make_parsers():
    '''
    Build a top-level parser and its subparsers and return them as a tuple.
    '''
    try:
        parser = ArgumentParser(description='Main parser')
        subparsers = parser.add_subparsers(dest='command', required=True)
        return parser, subparsers
    except Exception as e:
        raise RuntimeError(f"Failed to create parsers: {e}") from e

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    from ruamel.yaml.nodes import MappingNode, ScalarNode

    def merge_mapping_nodes(old_node, new_node):
        def to_dict(pair_list):
            d = {}
            for k_node, v_node in pair_list:
                d[k_node.value] = (k_node, v_node)
            return d

        old_dict = to_dict(old_node.value)
        new_dict = to_dict(new_node.value)

        merged_dict = dict(old_dict)  # start with old entries

        for key_val, (k_new, v_new) in new_dict.items():
            if key_val in old_dict:
                _, v_old = old_dict[key_val]
                if isinstance(v_old, MappingNode) and isinstance(v_new, MappingNode):
                    merged_v = merge_mapping_nodes(v_old, v_new)
                    merged_dict[key_val] = (old_dict[key_val][0], merged_v)
                else:
                    merged_dict[key_val] = (old_dict[key_val][0], v_new)
            else:
                merged_dict[key_val] = (k_new, v_new)

        # Preserve order: old order first, then new unique
        merged_pairs = []
        added = set()
        for key_val, pair in old_dict.items():
            merged_pairs.append(pair)
            added.add(key_val)
        for key_val, pair in new_dict.items():
            if key_val not in added:
                merged_pairs.append(pair)

        return MappingNode(old_node.tag, merged_pairs)

    if not isinstance(nodes, list):
        raise TypeError('nodes must be a list of (ScalarNode, Node) tuples')
    merged = {}  # key value -> (key_node, value_node)
    for key_node, val_node in nodes:
        if not isinstance(key_node, ScalarNode):
            raise TypeError('Key must be a ScalarNode')
        key_val = key_node.value
        if key_val not in merged:
            merged[key_val] = (key_node, val_node)
        else:
            _, existing_val = merged[key_val]
            if isinstance(existing_val, MappingNode) and isinstance(val_node, MappingNode):
                merged_node = merge_mapping_nodes(existing_val, val_node)
                merged[key_val] = (merged[key_val][0], merged_node)
            else:
                merged[key_val] = (merged[key_val][0], val_node)

    # Construct result preserving first occurrence order
    result = []
    seen = set()
    for key_node, _ in nodes:
        k = key_node.value
        if k in seen:
            continue
        seen.add(k)
        result.append(merged[k])
    return result

def deep_merge_nodes(nodes):
    """
    Deep merge a list of (ScalarNode, Node) tuples, merging values with duplicate keys.

    Parameters
    ----------
    nodes : list
        List of tuples where the first element is a ruamel.yaml.nodes.ScalarNode (key)
        and the second element is a mapping node or any other ruamel.yaml node.

    Returns
    -------
    list
        A list of merged (ScalarNode, Node) tuples.
    """
    # Helper to merge two values which may be MappingNodes.
    def merge_values(v1, v2):
        # If both are MappingNode, merge their mappings recursively.
        if hasattr(v1, "tag") and hasattr(v1, "value") and hasattr(v2, "tag") and hasattr(v2, "value"):
            # Recursively merge the .value lists (which are lists of (ScalarNode, Node) tuples).
            merged_pairs = merge_mapping_pairs(v1.value, v2.value)
            return type(v1)(v1.tag, merged_pairs)
        else:
            # For non-mapping or differing types, the second value wins.
            return v2

    # Helper to merge lists of mapping pairs.
    def merge_mapping_pairs(pairs1, pairs2):
        merged = {}
        # Preserve order: use dict insertion order.
        for k, v in pairs1:
            merged_str = k.value if hasattr(k, "value") else str(k)
            merged[merged_str] = (k, v)
        for k, v in pairs2:
            merged_str = k.value if hasattr(k, "value") else str(k)
            if merged_str in merged:
                key_node, existing_val = merged[merged_str]
                merged[merged_str] = (key_node, merge_values(existing_val, v))
            else:
                merged[merged_str] = (k, v)
        return list(merged.values())

    # Main merge logic for top-level nodes.
    result_dict = {}
    for key_node, val_node in nodes:
        key_str = key_node.value if hasattr(key_node, "value") else str(key_node)
        if key_str in result_dict:
            _, existing_val = result_dict[key_str]
            merged_val = merge_values(existing_val, val_node)
            # Keep the original key node from the first occurrence.
            result_dict[key_str] = (result_dict[key_str][0], merged_val)
        else:
            result_dict[key_str] = (key_node, val_node)

    return list(result_dict.values())

def deep_merge_nodes(nodes):
    """
    Merge a list of (key_node, value_node) pairs by deep merging values
    with duplicate keys. ``value_node`` is expected to be a MappingNode
    (tag == 'tag:yaml.org,2002:map') or any other node type.  For duplicate
    keys with MappingNode values, the mappings are recursively merged;
    otherwise the last value wins.

    Parameters
    ----------
    nodes : list
        List of tuples (ScalarNode, Node).

    Returns
    -------
    list
        Merged list of tuples.
    """
    merged_keys = {}
    key_order = []

    def is_mapping(node):
        return getattr(node, 'tag', None) == 'tag:yaml.org,2002:map'

    def merge_mapping_nodes(node1, node2):
        """
        Merge node2 into node1 in place.
        """
        # Build a dict of node1's current mappings
        mapping_dict = {}
        for k, v in node1.value:
            mapping_dict[k.value] = (k, v)
        # Iterate over node2's mappings
        for k2, v2 in node2.value:
            key = k2.value
            if key in mapping_dict:
                _, existing_v = mapping_dict[key]
                if is_mapping(existing_v) and is_mapping(v2):
                    # Recursively merge
                    merge_mapping_nodes(existing_v, v2)
                else:
                    # overwrite with last value
                    mapping_dict[key] = (k2, v2)
            else:
                mapping_dict[key] = (k2, v2)
        # Re-create the value list preserving order of keys in mapping_dict
        node1.value = [(k, v) for k, v in mapping_dict.values()]

    for key_node, val_node in nodes:
        try:
            key_str = key_node.value
        except AttributeError:
            raise ValueError("Key node missing 'value' attribute")

        if key_str in merged_keys:
            existing_key_node, existing_val_node = merged_keys[key_str]
            if is_mapping(existing_val_node) and is_mapping(val_node):
                merge_mapping_nodes(existing_val_node, val_node)
            else:
                merged_keys[key_str] = (existing_key_node, val_node)
        else:
            merged_keys[key_str] = (key_node, val_node)
            key_order.append(key_str)

    result = [(merged_keys[k][0], merged_keys[k][1]) for k in key_order]
    return result

