def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    # Basic validation: ensure we have a parser-like object with an _actions attribute
    if not hasattr(parser, "_actions"):
        raise ValueError("ArgumentParser is required")

    flags = []

    try:
        for action in parser._actions:
            # Only include actions that have option strings (e.g., -h/--help, etc.)
            if action.option_strings:
                # Join multiple option strings for the same action with spaces
                flags.append(' '.join(action.option_strings))
    except Exception as exc:
        # If anything goes wrong while iterating, re-raise a clear error
        raise RuntimeError(f"Failed to extract flags from parser: {exc}") from exc

    return ' '.join(flags)

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated string.
    '''
    try:
        # argparse objects store actions in the _actions attribute
        actions = getattr(parser, '_actions', [])
    except Exception as exc:
        raise TypeError("parser must be an argparse.ArgumentParser instance") from exc

    flags = []
    for action in actions:
        # Each action may have one or more option strings; skip positional arguments with no option_strings
        option_strings = getattr(action, 'option_strings', [])
        for opt in option_strings:
            # Only collect flags that start with a dash
            if opt.startswith('-'):
                flags.append(opt)

    return ' '.join(flags)

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    # Basic validation of the input
    if not hasattr(parser, '_actions'):
        raise TypeError('Expected an argparse.ArgumentParser instance, got %r' % parser)

    flags_set = set()
    for action in parser._actions:
        # action.option_strings contains the flag names (e.g., ['-h', '--help'])
        # Positional arguments do not have option_strings, so we skip those
        if getattr(action, 'option_strings', None):
            for flag in action.option_strings:
                # Skip automatically added flags that you might not want to expose
                if flag.startswith('-'):
                    flags_set.add(flag)

    # Return the flags as a space-separated string, sorted for reproducibility
    sorted_flags = sorted(flags_set)
    return ' '.join(sorted_flags)

def bash_completion():
    """Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    """
    import argparse
    import inspect
    import sys

    # Try to import borgmatic's main module and locate the main ArgumentParser.
    try:
        from borgmatic.main import main as borg_main
    except Exception as exc:
        raise RuntimeError("Could not import borgmatic.main: %s" % exc)

    parser = None
    main_module = sys.modules.get(borg_main.__module__)
    if main_module:
        for obj in inspect.getmembers(main_module):
            if isinstance(obj[1], argparse.ArgumentParser):
                parser = obj[1]
                break

    if parser is None:
        raise RuntimeError("No ArgumentParser found in borgmatic.main module")

    # Recursively collect subcommand names.
    commands = []

    def _collect(p):
        for action in p._actions:
            # Subparsers are instances of argparse._SubParsersAction
            if isinstance(action, argparse._SubParsersAction):
                for name, subp in action.choices.items():
                    commands.append(name)
                    _collect(subp)

    _collect(parser)
    cmds_str = " ".join(sorted(set(commands)))

    # Build a simple bash completion script that triggers on the first argument.
    script = f'''# Bash completion for borgmatic
_borgmatic_complete() {{
    local cur prev words cword
    _init_completion -s
    COMPREPLY=( $(compgen -W "{cmds_str}" -- "$cur") )
    return 0
}}

complete -F _borgmatic_complete borgmatic
'''
    return script

def bash_completion():
    '''
    Return a bash completion script for the borgmatic command.
    Produce this by introspecting borgmatic's command-line argument parsers.
    '''
    try:
        from borgmatic.cli.main import main_parser
    except Exception as exc:
        return f"# Error importing borgmatic's main parser: {exc}"

    # Extract subcommand names from the parser
    commands = []
    subparsers = getattr(main_parser, '_subparsers', None)
    if subparsers and hasattr(subparsers, 'choices'):
        commands = sorted(subparsers.choices.keys())

    # Build a simple Bash completion script that offers these subcommands
    script = f'''
_borgmatic_completion()
{{
    local cur="{{COMP_WORDS[COMP_CWORD]}}"
    case ${{COMP_CWORD}} in
        1)
            COMPREPLY=($(compgen -W "{' '.join(commands)}" -- $cur))
            ;;
    esac
}}
complete -F _borgmatic_completion borgmatic
'''
    return script.strip()

def bash_completion():
    '''
