def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    if not isinstance(unparsed_arguments, (list, tuple)):
        raise TypeError('unparsed_arguments must be a list or tuple of strings')
    if not isinstance(subparsers, dict):
        raise TypeError('subparsers must be a dict mapping names to ArgumentParser instances')

    parsed = {}
    unknowns = {}
    for name, parser in subparsers.items():
        if not hasattr(parser, 'parse_known_args'):
            raise TypeError(f'Parser for "{name}" does not seem to be an argparse.ArgumentParser')
        try:
            ns, unknown = parser.parse_known_args(list(unparsed_arguments))
        except Exception as exc:   # pragma: no cover
            raise ValueError(f'Error parsing arguments for subparser "{name}": {exc}') from exc
        parsed[name] = ns
        unknowns[name] = set(unknown)

    remaining = [
        arg for arg in unparsed_arguments
        if all(arg in unknowns[name] for name in subparsers)
    ]

    return parsed, remaining

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This
    allows common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed
    namespace of arguments, a list of remaining arguments not claimed by any subparser).
    '''
    if not isinstance(subparsers, dict):
        raise TypeError('subparsers must be a dict mapping name to ArgumentParser')
    # Ensure the arguments are in list form for ordering
    if isinstance(unparsed_arguments, (list, tuple)):
        args = list(unparsed_arguments)
    else:
        try:
            args = list(unparsed_arguments)
        except Exception as exc:
            raise TypeError('unparsed_arguments must be an iterable of strings') from exc

    parsed_results = {}
    unknown_lists = []

    for name, parser in subparsers.items():
        if not hasattr(parser, 'parse_known_args'):
            raise TypeError(f'Subparser {name!r} is not a valid argparse.ArgumentParser')
        try:
            parsed, unknown = parser.parse_known_args(args)
        except Exception as exc:
            # Propagate parse errors; only known args were consumed
            raise ValueError(f'Error parsing subparser {name!r}: {exc}') from exc
        parsed_results[name] = parsed
        unknown_lists.append(unknown)

    # Determine remaining arguments not claimed by any subparser
    if unknown_lists:
        # Intersection of unknown lists (args unknown to all)
        remaining_set = set(unknown_lists[0])
        for ulist in unknown_lists[1:]:
            remaining_set.intersection_update(ulist)
        # Preserve original order
        remaining = [arg for arg in args if arg in remaining_set]
    else:
        remaining = args  # no subparsers: all arguments remain

    return parsed_results, remaining

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    if not isinstance(response, list):
        raise TypeError(f"Expected response to be a list, got {type(response).__name__}")
    if not isinstance(max_results, int):
        raise TypeError(f"Expected max_results to be int, got {type(max_results).__name__}")
    if max_results <= 0:
        raise ValueError("max_results must be a positive integer")

    def _generator():
        for i in range(0, len(response), max_results):
            yield response[i:i + max_results]

    return _generator()

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    if not isinstance(response, list):
        raise TypeError("response must be a list")
    if not isinstance(max_results, int):
        raise TypeError("max_results must be an integer")
    if max_results <= 0:
        raise ValueError("max_results must be a positive integer")

    for start in range(0, len(response), max_results):
        yield response[start:start + max_results]

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    if not dicts:
        return result
    for d in dicts:
        if not isinstance(d, dict):
            raise TypeError(f"Expected dict, got {type(d).__name__}")
        for key, value in d.items():
            if key in result:
                try:
                    result[key] += value
                except TypeError as e:
