def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args

    Args:
        url (str): The URL string possibly containing placeholders.
        url_args (Mapping | Sequence): A mapping with named placeholder values
            or a sequence for positional placeholders.

    Returns:
        str: The URL with placeholders replaced.

    Raises:
        KeyError: If a named placeholder is missing in the mapping.
        ValueError: If a positional placeholder cannot be filled.
    """
    if not url:
        return url

    # Allow the function to be called with an empty or None url_args
    if not url_args:
        return url

    import re

    # Named placeholders: {name}
    named_placeholder_re = re.compile(r'\{([^}]+)\}')
    if isinstance(url_args, dict):
        def _replace_named(match):
            key = match.group(1)
            if key not in url_args:
                raise KeyError(f"Missing URL argument for placeholder '{{{key}}}'")
            value = url_args[key]
            # Ensure the value is a string (or convertible to)
            return str(value)
        url = named_placeholder_re.sub(_replace_named, url)
        return url

    # Positional placeholders: {0}, {1} etc.
    try:
        # Use Python's format method with positional arguments
        return url.format(*tuple(url_args))
    except IndexError as e:
        raise ValueError("Not enough positional URL arguments provided") from e
    except KeyError as e:
        # This should not normally happen for positional placeholders,
        # but provide a clear message
        raise ValueError("Invalid placeholder in URL") from e""

