        raise TypeError("register_number must be an int or str")
    if not isinstance(register_value, (int, str)):
        raise TypeError("register_value must be an int or str")

    def _recursively_replace(d):
        """Recursively replace any key that matches register_value."""
        # Make a list of keys to avoid runtime modification during iteration
        for key in list(d):
            if key == register_value:
                # Preserve the associated value
                value = d.pop(key)
                d[register_number] = value
            elif isinstance(d[key], dict):
                _recursively_replace(d[key])

    try:
        _recursively_replace(flow_params)
    except Exception as exc:
        raise RuntimeError(f"Failed to replace register value: {exc}") from exc

    return flow_params  # return modified dictionary for convenience.

