def get_repo_archive(url: str, destination_path: Path) -> Path:
    """
    Given an url and a destination path, retrieve and extract .tar.gz archive
    which contains 'desc' file for each package.
    Each .tar.gz archive corresponds to an Arch Linux repo ('core', 'extra', 'community').

    Args:
        url: url of the .tar.gz archive to download
        destination_path: the path on disk where to extract archive

    Returns:
        a directory Path where the archive has been extracted to.
    """
    # Ensure the destination directory exists
    try:
        destination_path.mkdir(parents=True, exist_ok=True)
    except Exception as e:
        raise RuntimeError(f"Could not create destination path {destination_path}") from e

    # Download the archive
    try:
        resp = requests.get(url, stream=True, timeout=60)
        resp.raise_for_status()
    except requests.RequestException as exc:
        raise RuntimeError(f"Download failed for {url}") from exc

    # Temporary file path for the downloaded archive
    archive_path = destination_path / "archive.tar.gz"

    # Write the downloaded content to the temporary file
    try:
        with open(archive_path, "wb") as f:
            for chunk in resp.iter_content(chunk_size=8192):
                if chunk:
                    f.write(chunk)
    except Exception as exc:
        # Clean up partial file if writing fails
        if archive_path.exists():
            try:
                archive_path.unlink()
            except Exception:
                pass
        raise RuntimeError(f"Failed to write archive to {archive_path}") from exc

    # Extract the archive
    try:
