def split(s, platform='this'):
    """
    Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import sys
    # Determine whether to use POSIX-style splitting
    if platform == 'this':
        posix = not sys.platform.startswith('win')
    elif platform == 1:
        posix = True
    elif platform == 0:
        posix = False
    else:
        raise ValueError("Unsupported platform value: %r" % platform)

    # Fast regex-based splitter for POSIX behaviour (used as fallback)
    def _posix_split(text):
        tokens = []
        i = 0
        length = len(text)
        while i < length:
            while i < length and text[i].isspace():
                i += 1
            if i >= length:
                break
            if text[i] in ('"', "'"):
                quote = text[i]
                i += 1
                buf = []
                while i < length:
                    if text[i] == quote:
                        i += 1
                        break
                    if text[i] == '\\' and i + 1 < length:
                        buf.append(text[i + 1])
                        i += 2
                    else:
                        buf.append(text[i])
                        i += 1
                tokens.append(''.join(buf))
            else:
                buf = []
                while i < length and not text[i].isspace():
                    if text[i] == '\\' and i + 1 < length:
                        buf.append(text[i + 1])
                        i += 2
                    else:
                        buf.append(text[i])
                        i += 1
                tokens.append(''.join(buf))
        return tokens

    # If POSIX, use the regex-based splitter; otherwise, delegate to shlex
    if posix:
        return _posix_split(s)
    else:
        import shlex
        return shlex.split(s, posix=False)

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import os
    import shlex
    if not isinstance(s, str):
        raise TypeError('s must be a string')
    if not s:
        return []
    if platform == 'this':
        platform = 0 if os.name == 'nt' else 1
    if platform == 1:
        # POSIX style: use the standard shlex module
        return shlex.split(s, posix=True)
    elif platform == 0:
        # Windows style: use a fast regex approach
        # Match either a double-quoted string (allowing escaped quotes) or a
        # single non-whitespace token.  Backslashes inside quotes are treated
        # literally except when escaping a quote.
        pattern = r'''(?:"((?:\\.|[^"\\])*)"|([^ \t\r\n]+))'''
        tokens = []
        for quoted, token in re.findall(pattern, s):
            if quoted:
                # Unescape escaped characters inside quotes
                # First handle escaped quotes
                t = quoted.replace(r'\"', '"')
                # Then handle escaped backslashes
                t = t.replace(r'\\', '\\')
                tokens.append(t)
            else:
                tokens.append(token)
        return tokens
    else:
        raise ValueError(f'Unsupported platform: {platform}')

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import os
    from pathlib import Path
    from subprocess import run, CalledProcessError

    archive = Path(archive_path)
    if not archive.is_file():
        raise FileNotFoundError(f"Archive file does not exist: {archive_path}")

    destination = Path(tmp_path) / archive.stem
    if destination.exists():
        # If the destination already exists, remove it before extraction
        try:
            if destination.is_dir():
                for child in destination.rglob('*'):
                    if child.is_file():
                        child.unlink()
                    else:
                        child.rmdir()
                destination.rmdir()
            else:
                destination.unlink()
        except Exception as exc:
            raise RuntimeError(f"Failed to clear existing extraction directory '{destination}': {exc}") from exc

    destination.mkdir(parents=True, exist_ok=True)

    try:
        if archive.suffix.lower() == ".zip":
            cmd = ["unzip", "-q", str(archive), "-d", str(destination)]
        else:
            cmd = ["tar", "xf", str(archive), "-C", str(destination)]
        run(cmd, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    except CalledProcessError as e:
        raise RuntimeError(f"Extraction failed for '{archive_path}': {e.stderr.decode().strip()}") from e

    return destination.as_uri()

def addignored(ignored):
    """Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma."""
    try:
        output = subprocess.check_output(
            ['git', 'ls-files', '--others', '--ignored', '--exclude-standard'],
            universal_newlines=True,
        )
    except (subprocess.CalledProcessError, OSError):
        return ''

    files = [line.strip() for line in output.splitlines() if line.strip()]

    # If a filter is supplied, apply it.  The filter may be a string or an iterable of strings.
    if ignored:
        try:
            # treat as iterable if not a string
            if isinstance(ignored, str):
                files = [f for f in files if ignored in f]
            else:
                files = [f for f in files if any(p in f for p in ignored)]
        except Exception:
            # if filtering fails, ignore the filter
            pass

    files.sort()
    return ','.join(files)

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    s = str(frequency).strip()
    if not s or s.lower() == 'always':
        return None
    parts = s.split()
    if len(parts) != 2:
        raise ValueError(f"Frequency must be in '<number> <unit>' format: {s}")
    number_str, unit = parts
    try:
        number = float(number_str)
    except ValueError:
        raise ValueError(f"Invalid number in frequency: {number_str}")
    unit = unit.lower()
    if unit in ('day', 'days'):
        return datetime.timedelta(days=number)
    if unit in ('hour', 'hours'):
        return datetime.timedelta(hours=number)
    if unit in ('minute', 'minutes'):
        return datetime.timedelta(minutes=number)
    if unit in ('second', 'seconds'):
        return datetime.timedelta(seconds=number)
    if unit in ('week', 'weeks'):
        return datetime.timedelta(weeks=number)
    if unit in ('month', 'months'):
        return datetime.timedelta(days=number*30)
    if unit in ('year', 'years'):
        return datetime.timedelta(days=number*365)
    raise ValueError(f"Unsupported unit in frequency: {unit}")

