def parse_frequency(frequency):
    """
    Given a frequency string with a number and a unit of time, return a
    corresponding datetime.timedelta instance or None if the frequency is
    None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3).

    Raise ValueError if the given frequency cannot be parsed.
    """
    if frequency is None:
        return None
    if isinstance(frequency, str) and frequency.strip().lower() == "always":
        return None

    if not isinstance(frequency, str):
        raise ValueError(f"Frequency must be a string or None, got {type(frequency).__name__}")

    parts = frequency.strip().lower().split()
    if len(parts) != 2:
        raise ValueError(f"Cannot parse frequency '{frequency}'. Expected format: '<int> <unit>'")

    try:
        amount = int(parts[0])
    except ValueError:
        raise ValueError(f"Could not parse number from frequency '{frequency}'")

    unit = parts[1]
    unit_map = {
        'second': 'seconds',
        'seconds': 'seconds',
        'minute': 'minutes',
        'minutes': 'minutes',
        'hour': 'hours',
        'hours': 'hours',
        'day': 'days',
        'days': 'days',
        'week': 'weeks',
        'weeks': 'weeks',
    }

    if unit not in unit_map:
        raise ValueError(f"Unsupported time unit '{unit}' in frequency '{frequency}'")

    kwargs = {unit_map[unit]: amount}
    return datetime.timedelta(**kwargs)

