def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Extract name and optional default from matcher
    name = None
    default = None

    # Regex match object (e.g., re.Match) with named groups
    if hasattr(matcher, "groupdict"):
        groups = matcher.groupdict()
        name = groups.get("name")
        default = groups.get("default")

    # Tuple or list form: (name,) or (name, default)
    elif isinstance(matcher, (tuple, list)):
        if len(matcher) > 0:
            name = matcher[0]
        if len(matcher) > 1:
            default = matcher[1]

    # Dictionary form
    elif isinstance(matcher, dict):
        name = matcher.get("name")
        default = matcher.get("default")

    else:
        raise TypeError("Unsupported matcher type: %r" % matcher)

    if name is None:
        raise ValueError("Matcher does not contain a variable name")

    value = os.getenv(name)
    if value is None:
        if default is not None:
            value = default
        else:
            raise KeyError("Environment variable '%s' not set and no default provided" % name)

    return value

