def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    # Validate inputs
    if not isinstance(commands, (str, list)):
        raise TypeError("commands must be a string or a list of strings")
    if not isinstance(args, list):
        raise TypeError("args must be a list of arguments")

    # Build the command list
    if isinstance(commands, list):
        if not commands:
            raise ValueError("commands list cannot be empty")
        command = commands + args
    else:
        command = [commands] + args

    # Debug output if requested
    if verbose:
        cmd_str = ' '.join(f"'{arg}'" if ' ' in arg else arg for arg in command)
        print(f"Running command: {cmd_str}")

    # Prepare subprocess arguments
    subprocess_kwargs = {"cwd": cwd, "text": True, "check": True}
    if env is not None:
        subprocess_kwargs["env"] = env
    if hide_stderr:
        subprocess_kwargs["stderr"] = subprocess.DEVNULL

    try:
        result = subprocess.run(command, **subprocess_kwargs)
        return result
    except subprocess.CalledProcessError as exc:
        # Re-raise with a clearer message
        errmsg = f"Command '{' '.join(command)}' exited with code {exc.returncode}"
        raise subprocess.CalledProcessError(exc.returncode, exc.cmd, exc.output, errmsg) from exc
    except Exception as exc:
        # Catch-all for unforeseen errors
        raise RuntimeError(f"Failed to run command '{' '.join(command)}': {exc}") from exc

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Validate inputs
    if commands is None:
        raise ValueError("No command specified.")
    # Build the command list
    if isinstance(commands, (list, tuple)):
        if not commands:
            raise ValueError("Command list is empty.")
        full_cmd = list(commands)
    else:
        full_cmd = [str(commands)]
    if args:
        if isinstance(args, (list, tuple)):
            full_cmd += list(args)
        else:
            full_cmd.append(str(args))
    # Emit verbose output if requested
    if verbose:
        print(f"Running command: {' '.join(full_cmd)}")
    # Set up stderr handling
    stderr_option = subprocess.PIPE if hide_stderr else None
    # Execute the command
    try:
        result = subprocess.run(
            full_cmd,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=stderr_option,
            text=True,
            check=True
        )
    except subprocess.CalledProcessError as e:
        # If hide_stderr, we may still want to get stderr
        if hide_stderr and e.stderr is not None:
            e.stderr = e.stderr.strip()
        raise e
    except Exception as exc:
        raise RuntimeError(f"Failed to run command '{' '.join(full_cmd)}': {exc}") from exc
    return result

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Normalize the command input as a list of arguments
    if isinstance(commands, str):
        cmd = [commands]
    else:
        cmd = list(commands)

    # Append any additional arguments
    if args:
        if isinstance(args, (list, tuple)):
            cmd.extend(args)
        else:
            cmd.append(args)

    # Debug output if requested
    if verbose:
        print("Running command:", " ".join(cmd))

    # Hide stderr if requested by redirecting to DEVNULL
    stderr_target = subprocess.DEVNULL if hide_stderr else None

    try:
        # Execute the command and raise on non-zero exit code
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=stderr_target,
            check=True,
            text=True
        )
        return result
    except subprocess.CalledProcessError as e:
        # Propagate the error with the command that failed
        raise RuntimeError(f"Command '{' '.join(e.cmd)}' failed with exit code {e.returncode}") from e
    except Exception as e:
        # Generic exception handling for unforeseen issues
        raise RuntimeError(f"An error occurred while running command '{' '.join(cmd)}': {e}") from e

