def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json
    import os
    import logging

    logger = logging.getLogger('load_configurations')
    configs = {}
    records = []

    def _resolve_env_in_value(value):
        if isinstance(value, str):
            # simple ${VAR} substitution
            start = value.find('${')
            while start != -1:
                end = value.find('}', start)
                if end == -1:
                    break
                var_name = value[start + 2:end]
                var_value = os.getenv(var_name, '')
                value = value[:start] + var_value + value[end + 1:]
                start = value.find('${', start + len(var_value))
        elif isinstance(value, dict):
            for k, v in value.items():
                value[k] = _resolve_env_in_value(v)
        elif isinstance(value, list):
            for i, v in enumerate(value):
                value[i] = _resolve_env_in_value(v)
        return value

    for fname in config_filenames:
        try:
            with open(fname, 'r', encoding='utf-8') as f:
                content = f.read()
        except FileNotFoundError:
            msg = f"Configuration file not found: {fname}"
            record = logger.makeRecord('load_configurations', logging.ERROR,
                                       fname, 0, msg, None, None, {})
            records.append(record)
            continue
        except OSError as e:
            msg = f"Error opening configuration file '{fname}': {e}"
            record = logger.makeRecord('load_configurations', logging.ERROR,
                                       fname, 0, msg, None, None, {})
            records.append(record)
            continue

        try:
            cfg = json.loads(content)
        except json.JSONDecodeError as e:
            msg = f"JSON parse error in file '{fname}': {e}"
            record = logger.makeRecord('load_configurations', logging.ERROR,
                                       fname, 0, msg, None, None, {})
            records.append(record)
            continue

        if not isinstance(cfg, dict):
            msg = f"Configuration in '{fname}' is not a JSON object (expected dict)."
            record = logger.makeRecord('load_configurations', logging.WARNING,
                                       fname, 0, msg, None, None, {})
            records.append(record)

        if resolve_env:
            cfg = _resolve_env_in_value(cfg)

        if overrides:
            if isinstance(overrides, dict):
                cfg.update(overrides)
            else:
                msg = f"Overrides provided for '{fname}' are not a dictionary."
                record = logger.makeRecord('load_configurations', logging.WARNING,
                                           fname, 0, msg, None, None, {})
                records.append(record)

        configs[fname] = cfg

    return configs, records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json
    import os
    import re

    configs = {}
    errors = []

    logger = logging.getLogger(__name__)

    if overrides is None:
        overrides = {}

    env_pattern = re.compile(r'\${([^}]+)}')

    def _resolve_env_value(value):
        if isinstance(value, str):
            def repl(match):
                var_name = match.group(1)
                return os.getenv(var_name, '')
            return env_pattern.sub(repl, value)
        return value

    def _recursive_resolve(item):
        if isinstance(item, dict):
            return {k: _recursive_resolve(_resolve_env_value(v)) for k, v in item.items()}
        elif isinstance(item, list):
            return [_recursive_resolve(_resolve_env_value(elem)) for elem in item]
        elif isinstance(item, tuple):
            return tuple(_recursive_resolve(_resolve_env_value(elem)) for elem in item)
        else:
            return _resolve_env_value(item)

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                try:
                    config = json.load(f)
                except Exception as exc:
                    msg = f"Failed to parse JSON in '{filename}': {exc}"
                    record = logger.makeRecord(logger.name, logging.ERROR,
                                               filename, 0, msg, (), None)
                    errors.append(record)
                    continue
        except Exception as exc:
            msg = f"Failed to open configuration file '{filename}': {exc}"
            record = logger.makeRecord(logger.name, logging.ERROR,
                                       filename, 0, msg, (), None)
            errors.append(record)
            continue

        if resolve_env:
            config = _recursive_resolve(config)

        # Apply overrides: merge overrides into config
        if overrides:
            if isinstance(config, dict):
                merged = dict(config)  # shallow copy
                merged.update(overrides)
                config = merged

        configs[filename] = config

    return configs, errors

import logging
import os
import re

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    configs = {}
    log_records = []

    # helpers to import modules lazily
    def _load_json(path):
        json_mod = __import__('json')
        with open(path, 'r', encoding='utf-8') as f:
            return json_mod.load(f)

    def _load_yaml(path):
        yaml_mod = __import__('yaml')
        with open(path, 'r', encoding='utf-8') as f:
            return yaml_mod.safe_load(f)

    def _load_ini(path):
        cfg_mod = __import__('configparser')
        parser = cfg_mod.ConfigParser()
        parser.read(path, encoding='utf-8')
        # convert to nested dict
        cfg = {}
        for section in parser.sections():
            cfg[section] = dict(parser.items(section))
        return cfg

    def resolve_env_vars(value):
        if isinstance(value, str):
            # replace ${VAR} with environment variable
            def repl(match):
                var = match.group(1)
                return os.getenv(var, '')
            return re.sub(r'\$\{([^}]+)\}', repl, value)
        elif isinstance(value, dict):
            return {k: resolve_env_vars(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [resolve_env_vars(x) for x in value]
        return value

    for fname in config_filenames:
        try:
            ext = os.path.splitext(fname)[1].lower()
            if ext == '.json':
                config = _load_json(fname)
            elif ext in ('.yaml', '.yml'):
                config = _load_yaml(fname)
            elif ext in ('.ini', '.cfg'):
                config = _load_ini(fname)
            else:
                # unsupported file type
                raise ValueError(f'Unsupported configuration file type: {ext}')
        except Exception as e:
            record = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=__file__,
                lineno=0,
                msg=f'Failed to parse configuration file "{fname}": {e}',
                args=None,
                exc_info=None)
            log_records.append(record)
            continue

        # apply overrides if any
        if overrides:
            override = overrides.get(fname)
            if override and isinstance(override, dict):
                if isinstance(config, dict):
                    config.update(override)
                else:
                    # cannot override non-dict config
                    pass

        # resolve environment variables
        if resolve_env:
            try:
                config = resolve_env_vars(config)
            except Exception as e:
                record = logging.LogRecord(
                    name='load_configurations',
                    level=logging.ERROR,
                    pathname=__file__,
                    lineno=0,
                    msg=f'Environment resolution error in file "{fname}": {e}',
                    args=None,
                    exc_info=None)
                log_records.append(record)

        configs[fname] = config

    return configs, log_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of:
        - dict mapping configuration filename to the corresponding parsed configuration
        - sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json
    import os
    import sys
    import re

    def _replace_env_vars(obj):
        """Recursively replace '${VAR}' patterns in strings with environment variables."""
        if isinstance(obj, str):
            def repl(match):
                var = match.group(1)
                return os.environ.get(var, '')
            return re.sub(r'\$\{([^}]+)\}', repl, obj)
        elif isinstance(obj, dict):
            return {k: _replace_env_vars(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [_replace_env_vars(item) for item in obj]
        else:
            return obj

    results = {}
    errors = []
    logger = logging.getLogger(__name__)

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as fh:
                try:
                    config = json.load(fh)
                except Exception as e:
                    # JSON parsing error
                    record = logger.makeRecord(
                        logger.name, logging.ERROR, filename, 0,
                        f'JSON parse error in {filename}: {e}', None, sys.exc_info()
                    )
                    errors.append(record)
                    continue

            # Validation: ensure config is a dict
            if not isinstance(config, dict):
                record = logger.makeRecord(
                    logger.name, logging.ERROR, filename, 0,
                    f'Configuration in {filename} is not a JSON object (expected dict)', None, None
                )
                errors.append(record)
                continue

            # Resolve environment variables if requested
            if resolve_env:
                config = _replace_env_vars(config)

            # Apply overrides if provided
            if overrides:
                for key, value in overrides.items():
                    config[key] = value

            results[filename] = config

        except FileNotFoundError as e:
            record = logger.makeRecord(
                logger.name, logging.ERROR, filename, 0,
                f'File not found: {filename}', None, sys.exc_info()
            )
            errors.append(record)
        except Exception as e:
            # Generic error
            record = logger.makeRecord(
                logger.name, logging.ERROR, filename, 0,
                f'Error loading configuration {filename}: {e}', None, sys.exc_info()
            )
            errors.append(record)

    return results, errors

