@classmethod
    def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        """
        # Validate that `values` is an iterable of strings (not a single string)
        try:
            iterator = iter(values)
        except TypeError:
            raise TypeError("values must be an iterable of strings")
        if isinstance(values, str):
            raise TypeError("values must be an iterable of strings, not a single string")
        # Build a list of raw string values, validating each element
        raw_values = []
        for v in iterator:
            if not isinstance(v, str):
                raise TypeError(f"Bookmark value {v!r} is not a string")
            raw_values.append(v)
        # Create a new instance of the Bookmarks class
        try:
            obj = cls()
        except TypeError:
            # If the default constructor expects arguments, try passing the raw values
            try:
                obj = cls(raw_values)
            except Exception as exc:
                raise TypeError(f"Cannot instantiate {cls.__name__} with provided values: {exc}") from exc
        # Add the bookmarks to the instance
        if hasattr(obj, "add"):
            try:
                for v in raw_values:
                    obj.add(v)
            except Exception as exc:
                raise ValueError(f"Failed to add bookmark {v!r} to {cls.__name__}: {exc}") from exc
        elif hasattr(obj, "extend"):
            try:
                obj.extend(raw_values)
            except Exception as exc:
                raise ValueError(f"Failed to extend bookmarks in {cls.__name__}: {exc}") from exc
        elif hasattr(obj, "bookmarks") and isinstance(getattr(obj, "bookmarks"), list):
            try:
                getattr(obj, "bookmarks").extend(raw_values)
            except Exception as exc:
                raise ValueError(f"Failed to set bookmarks list in {cls.__name__}: {exc}") from exc
        else:
            # Fallback: set a generic attribute
            try:
                setattr(obj, "bookmarks", list(raw_values))
            except Exception as exc:
                raise ValueError(f"Cannot set bookmarks attribute on {cls.__name__}: {exc}") from exc
        return obj

