def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    from collections.abc import Sequence
    import itertools

    if seq is None:
        raise ValueError("seq cannot be None")

    # If seq is already a sequence (including string, tuple, list, etc.)
    if isinstance(seq, Sequence):
        return seq, type(seq)

    # For iterables that aren't sequences, consume them into a list.
    try:
        if bufsize is not None:
            seq = list(itertools.islice(seq, bufsize))
        else:
            seq = list(seq)
    except TypeError:
        # If seq can't be iterated, propagate a clear error.
        raise TypeError("Provided object is not iterable and not a sequence") from None

    return seq, type(seq)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # First, determine whether *seq* is already a sequence.
    try:
        from collections.abc import Sequence as ABCSequence
    except Exception:
        # Fallback for older Python versions
        from collections import Sequence as ABCSequence

    # Treat strings and bytes as sequence types as well
    is_seq_type = isinstance(seq, ABCSequence)
    # Note: sequences like sets are not considered here

    if is_seq_type:
        # seq is already a sequence; just return it
        return seq, type(seq)

    # If we get here, seq is not a sequence type. Try to iterate over it.
    try:
        it = iter(seq)
    except TypeError:
        # Not iterable, just return as is
        return seq, type(seq)

    # Build the sequence. If a buffer size is specified, collect up to that many items.
    if bufsize is None:
        seq_list = list(it)
    else:
        # Be careful not to exhaust too many; use islice
        try:
            from itertools import islice
            seq_list = list(islice(it, bufsize))
        except Exception:
            # Fallback for older Python versions or unexpected errors
            seq_list = []
            count = 0
            for item in it:
                seq_list.append(item)
                count += 1
                if count >= bufsize:
                    break

    return seq_list, type(seq)  # type refers to original object type

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Keep the original type
    seq_type = type(seq)

    # If seq is already a sequence type we can use it directly
    if isinstance(seq, (list, tuple, set, frozenset, bytes, bytearray)):
        # Optionally truncate to the buffer size if requested
        if bufsize is not None:
            try:
                seq = seq[:bufsize]
            except Exception:
                # In case slicing is not supported (e.g. sets)
                pass
        return seq, seq_type

    # Try to materialise an iterable into a tuple
    try:
        # For generators or other iterables that are not actual sequences
        seq = tuple(seq)
        return seq, type(seq)
    except TypeError as exc:
        # seq is not iterable
        raise TypeError("Input 'seq' must be a sequence or iterable") from exc

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type).
    The optional *bufsize* argument is retained for compatibility but is not used
    in this implementation.
    """
    from collections.abc import Sequence, Mapping

    # Handle None explicitly
    if seq is None:
        return (None, type(None))

    # Treat mappings specially; otherwise, consider any sequence type
    if isinstance(seq, Mapping):
        return (seq, type(seq))

    # Strings, bytes, bytearray, lists, tuples, sets, frozensets are sequences
    if isinstance(seq, Sequence):
        return (seq, type(seq))

    # Try to convert non-sequence iterables to a list
    try:
        derived = list(seq)
    except TypeError:
        # seq is not iterable; return it unchanged
        return (seq, type(seq))

    return (derived, type(seq))

def scale(self, other=None, recompute=False):
    """Compute or set scale (integral of the histogram).

    If *other* is ``None``, return scale of this histogram.
    If its scale was not computed before,
    it is computed and stored for subsequent use
    (unless explicitly asked to *recompute*).
    Note that after changing (filling) the histogram
    one must explicitly recompute the scale
    if it was computed before.

    If a float *other* is provided, rescale self to *other*.

    Histograms with scale equal to zero can't be rescaled.
    :exc:`.LenaValueError` is raised if one tries to do that.
    """
    # Compute (or recompute) cached scale
    if recompute or not hasattr(self, "_cached_scale"):
        try:
            # Prefer a dedicated `bins` attribute if present
            if hasattr(self, "bins"):
                values = self.bins
            else:
                values = list(self)
        except Exception:
            values = []
        self._cached_scale = float(sum(values))

    # Return current scale if no new value supplied
    if other is None:
        return self._cached_scale

    # Validate new scale
    if not isinstance(other, (int, float)):
        raise TypeError("New scale must be a numeric value, got %r" % (other,))
    if self._cached_scale == 0:
        raise LenaValueError("Histogram scale is zero; cannot rescale.")

    # Compute factor and apply to underlying data
    factor = float(other) / self._cached_scale

    try:
        if hasattr(self, "bins"):
            # If `bins` is replaceable (e.g., list)
            self.bins = [x * factor for x in self.bins]
        elif hasattr(self, "_bins"):
            self._bins = [x * factor for x in self._bins]
        elif hasattr(self, "__setitem__"):
            # Fallback: iterate via indices if the object behaves like a list
            for i in range(len(self)):
                self[i] = self[i] * factor
        else:
            raise RuntimeError("Histogram storage type not rescalable.")
    except Exception as exc:
        raise RuntimeError("Failed to rescale histogram: %s" % exc)

    # Update cached scale to the new value
    self._cached_scale = float(other)
    return

def scale(self, other=None, recompute=False):
    """Compute or set scale (integral of the histogram).

    If *other* is ``None``, return scale of this histogram.
    If its scale was not computed before, it is computed and stored for
    subsequent use (unless explicitly asked to *recompute*).
    Note that after changing (filling) the histogram one must explicitly
    recompute the scale if it was computed before.

    If a float *other* is provided, rescale self to *other*.

    Histograms with scale equal to zero can't be rescaled.
    :exc:`.LenaValueError` is raised if one tries to do that.
    """
    # Helper to compute integral
    def _compute_integral():
        if hasattr(self, "bins") and isinstance(self.bins, (list, tuple)):
            return sum(self.bins)
        if hasattr(self, "counts"):
            return sum(self.counts)
        if hasattr(self, "data"):
            data = self.data
            if isinstance(data, dict):
                return sum(data.values())
            try:
                return sum(data)
            except Exception:
                pass
        raise AttributeError(
            "Cannot compute scale: no histogram data found in self"
        )

    # Return or compute current scale
    if other is None:
        if not hasattr(self, "_scale") or recompute:
            self._scale = _compute_integral()
        return getattr(self, "_scale")

    # Rescale to a new total
    if not isinstance(other, (int, float)):
        raise TypeError("other must be a numeric value representing the desired scale")

    current_scale = self.scale(recompute=recompute)
    if current_scale == 0:
        try:
            from .errors import LenaValueError
        except Exception:
            class LenaValueError(Exception):
                pass
        raise LenaValueError(
            "Cannot rescale histogram with zero scale"
        )
    factor = float(other) / float(current_scale)

    # Apply scaling factor to each bin/count/value
    if hasattr(self, "bins") and isinstance(self.bins, (list, tuple)):
        self.bins = [c * factor for c in self.bins]
    elif hasattr(self, "counts"):
        self.counts = [c * factor for c in self.counts]
    elif hasattr(self, "data"):
        data = self.data
        if isinstance(data, dict):
            self.data = {k: v * factor for k, v in data.items()}
        else:
            try:
                self.data = [x * factor for x in data]
            except Exception:
                pass
    else:
        raise AttributeError(
            "Cannot rescale histogram: no data to apply scaling factor"
        )

    # Update stored scale
    self._scale = float(other)
    return None

def scale(self, other=None, recompute=False):
    """Compute or set scale (integral of the histogram).

    If *other* is ``None``, return scale of this histogram.
    If its scale was not computed before,
    it is computed and stored for subsequent use
    (unless explicitly asked to *recompute*).
    Note that after changing (filling) the histogram
    one must explicitly recompute the scale
    if it was computed before.

    If a float *other* is provided, rescale self to *other*.

    Histograms with scale equal to zero can't be rescaled.
    :exc:`.LenaValueError` is raised if one tries to do that.
    """
    # Helper to compute the integral of the histogram
    def _compute_integral():
        # Try common attributes that may hold count data
        for attr in ('data', 'bins', 'values', 'counts'):
            if hasattr(self, attr):
                arr = getattr(self, attr)
                try:
                    return float(sum(arr))
                except Exception:
                    try:
                        return float(sum(arr.values()))
                    except Exception:
                        pass
        # Fallback: no data found
        return 0.0

    # If called without an argument, return the scale
    if other is None:
        # Return cached scale if already computed and no recompute requested
        if hasattr(self, "_scale") and self._scale is not None and not recompute:
            return self._scale
        # Compute new scale
        self._scale = _compute_integral()
        return self._scale

    # Called with a target scale: rescale histogram to the given value
    try:
        target_scale = float(other)
    except Exception as exc:
        raise ValueError(f"other must be a numeric value, got {other!r}") from exc

    # Ensure a previous scale exists to determine the scaling factor
    current_scale = self.scale(recompute=recompute) if recompute else self.scale()
    if current_scale == 0:
        raise LenaValueError("Histograms with scale equal to zero cannot be rescaled.")

    factor = target_scale / current_scale

    # Apply the scaling factor to the underlying data
    data_attr = None
    for attr in ('data', 'bins', 'values', 'counts'):
        if hasattr(self, attr):
            data_attr = getattr(self, attr)
            break
    if data_attr is None:
        raise AttributeError("Histogram data attribute not found for rescaling.")

    # Scale the data in place
    if isinstance(data_attr, dict):
        for key in data_attr:
            data_attr[key] *= factor
    else:
        # Assume iterable with numeric items
        try:
            for i in range(len(data_attr)):
                data_attr[i] *= factor
        except Exception as exc:
            raise TypeError("Histogram data is not a scalable sequence") from exc

    # Update cached scale
    self._scale = target_scale
    return target_scale

def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Get current scale
    if other is None:
        return getattr(self, "_scale", None)

    # Validate new scale value
    if not isinstance(other, (int, float)):
        raise TypeError("Scale value must be numeric.")
    current_scale = getattr(self, "_scale", None)
    if current_scale is None or current_scale == 0:
        # Assuming LenaValueError is defined elsewhere in the module
        raise LenaValueError("Cannot rescale a graph with unknown or zero scale")

    # Compute scaling factor
    factor = other / current_scale

    # Rescale each field's last coordinate and associated errors
    fields = getattr(self, "fields", None)
    if fields is None:
        # Attempt to guess common attribute names for fields
        if hasattr(self, "grid"):
            fields = getattr(self, "grid")
        else:
            fields = []

    for field in fields or []:
        # Rescale data points
        # Common containers might be numpy arrays or lists of tuples
        # Attempt to find numeric arrays
        data = None
        if hasattr(field, "data"):
            data = field.data
        elif hasattr(field, "points"):
            data = field.points
        if data is None:
            continue

        try:
            import numpy as np
            if isinstance(data, np.ndarray):
                # Ensure array has at least one dimension
                if data.ndim >= 1:
                    data[:, -1] *= factor
                if hasattr(field, "errors") and field.errors is not None:
                    if isinstance(field.errors, np.ndarray):
                        field.errors[:, -1] *= factor
                    elif isinstance(field.errors, list):
                        for err in field.errors:
                            if hasattr(err, "__iter__"):
                                err[-1] *= factor
            else:
                # Assume data is list-like of tuples or lists
                new_points = []
                for pt in data:
                    pt = list(pt)
                    pt[-1] *= factor
                    new_points.append(tuple(pt))
                if hasattr(field, "points"):
                    field.points = new_points
                # Rescale errors if present
                if hasattr(field, "errors") and field.errors is not None:
                    new_errors = []
                    for err in field.errors:
                        err = list(err)
                        err[-1] *= factor
                        new_errors.append(tuple(err))
                    field.errors = new_errors
        except Exception:
            # If any custom field implementation fails, skip silently
            continue

    # Update the graph's scale
    self._scale = other
    return None

def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Return current scale if no new value requested
    if other is None:
        return getattr(self, "_scale", None)

    # Ensure other is numeric
    try:
        new_scale = float(other)
    except Exception as exc:
        raise ValueError("Scale must be a numeric value.") from exc

    current_scale = getattr(self, "_scale", None)
    if current_scale is None or current_scale == 0:
        raise LenaValueError("Cannot rescale a graph with unknown or zero scale.")

    # Compute scaling factor
    factor = new_scale / current_scale

    # Identify the fields of the graph
    fields = getattr(self, "fields", None)
    if fields is None:
        fields = getattr(self, "_fields", None)
    if not fields or not isinstance(fields, (list, tuple)):
        raise ValueError("Graph does not contain any fields to rescale.")

    # Rescale the last coordinate field
    last_field = fields[-1]
    # Rescale the coordinate values
    if hasattr(last_field, "values"):
        try:
            last_field.values = [v * factor for v in last_field.values]
        except Exception:
            # If values are numpy arrays or other iterable
            try:
                last_field.values *= factor
            except Exception:
                pass
    elif hasattr(last_field, "data"):
        try:
            last_field.data = [v * factor for v in last_field.data]
        except Exception:
            try:
                last_field.data *= factor
            except Exception:
                pass

    # Rescale the errors (if any)
    if hasattr(last_field, "errors") and last_field.errors is not None:
        try:
            last_field.errors = [e * factor for e in last_field.errors]
        except Exception:
            try:
                last_field.errors *= factor
            except Exception:
                pass

    # Update the stored scale
    setattr(self, "_scale", new_scale)
    return self.

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be ``"left"`` (default), ``"right"`` and ``"middle"``.

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Default make_value if not provided
    if make_value is None:
        make_value = lambda bin_: bin_

    # Resolve scale
    if scale is True:
        scale_val = getattr(hist, "scale", None)
    else:
        scale_val = scale

    # Determine the collection of bin contents
    try:
        if hasattr(hist, "bins"):
            bins = hist.bins
        else:
            bins = hist
        # Ensure we can iterate
        iter(bins)
    except TypeError:
        raise TypeError("hist must be an iterable of bin contents or have a 'bins' attribute")

    # Get bin edges if available, otherwise we approximate with indices
    try:
        edges = getattr(hist, "edges", None)
        if edges is not None:
            # Convert to list to support indexing
            edges = list(edges)
    except Exception:
        edges = None

    # Function to compute coordinate for a given bin index
    def coordinate(idx):
        if edges is not None:
            if get_coordinate == "left":
                return edges[idx]
            elif get_coordinate == "right":
                return edges[idx + 1]
            elif get_coordinate == "middle":
                return (edges[idx] + edges[idx + 1]) / 2.0
            else:
                raise ValueError(
                    f"Unknown get_coordinate value '{get_coordinate}'. "
                    "Use 'left', 'right', or 'middle'."
                )
        # Fallback: use the index as the coordinate
        if get_coordinate == "left":
            return float(idx)
        elif get_coordinate == "right":
            return float(idx + 1)
        elif get_coordinate == "middle":
            return float(idx) + 0.5
        else:
            raise ValueError(
                f"Unknown get_coordinate value '{get_coordinate}'. "
                "Use 'left', 'right', or 'middle'."
            )

    # Prepare graph instance
    try:
        # It is expected that there is a Graph class available in the import context
        graph = Graph()
    except NameError:
        raise NameError("Graph class must be defined in the surrounding context.")

    # Assign graph attributes if they exist
    if hasattr(graph, "scale"):
        graph.scale = scale_val
    if hasattr(graph, "field_names"):
        graph.field_names = list(field_names)
    elif hasattr(graph, "fields"):
        graph.fields = list(field_names)
    else:
        # If graph does not have fields attribute, we set attribute anyway
        setattr(graph, "field_names", list(field_names))

    # Prepare container for points
    try:
        graph.points
    except AttributeError:
        # Graph might manage points via add_point method instead
        pass

    points = []
    for i, bin_content in enumerate(bins):
        try:
            x_coord = coordinate(i)
        except Exception as e:
            raise ValueError(f"Error computing coordinate for bin index {i}: {e}")

        try:
            y_vals = make_value(bin_content)
        except Exception as e:
            raise ValueError(f"Error applying make_value to bin index {i}: {e}")

        # Normalize y_vals to a tuple
        if not isinstance(y_vals, (tuple, list)):
            y_vals = (y_vals,)

        # Build the point tuple: coordinate + y values
        point = (x_coord,) + tuple(y_vals)

        # Validate the number of fields
        if len(point) != len(field_names):
            raise ValueError(
                f"Number of fields {len(point)} does not match field_names "
                f"{len(field_names)} at bin index {i}."
            )
        points.append(point)

    # Add points to graph
    if hasattr(graph, "add_point"):
        for p in points:
            graph.add_point(p)
    elif hasattr(graph, "points"):
        graph.points.extend(points)
    else:
        # Fallback: assign points attribute
        setattr(graph, "points", points)

    return graph

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use
    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Extract edges and bin values from the histogram.
    try:
        edges = getattr(hist, "edges")
    except AttributeError:
        try:
            edges = getattr(hist, "bin_edges")
        except AttributeError:
            raise AttributeError(
                "Histogram object must provide an 'edges' or 'bin_edges' attribute."
            )
    try:
        values = getattr(hist, "values")
    except AttributeError:
        try:
            values = getattr(hist, "data")
        except AttributeError:
            raise AttributeError(
                "Histogram object must provide a 'values' or 'data' attribute."
            )

    num_bins = len(values)
    if len(edges) != num_bins + 1:
        raise ValueError(
            "Histogram 'edges' length must be one more than number of bins."
        )

    # Determine which edge to use for the X coordinate.
    if get_coordinate == "left":
        coord_index = lambda i: edges[i]
    elif get_coordinate == "right":
        coord_index = lambda i: edges[i + 1]
    elif get_coordinate == "middle":
        coord_index = lambda i: (edges[i] + edges[i + 1]) / 2
    else:
        raise ValueError(
            "Parameter 'get_coordinate' must be either 'left', 'right' or 'middle'."
        )

    # Resolve scale.
    if scale is True:
        scale = getattr(hist, "scale", None)

    # Build points for the graph.
    points = []
    for i in range(num_bins):
        coord = coord_index(i)
        val = values[i]
        if make_value is not None:
            try:
                val = make_value(val)
            except Exception as exc:
                raise RuntimeError(
                    f"make_value failed for bin {i} with value {val}"
                ) from exc

        # Normalise val to a tuple of values.
        if isinstance(val, (list, tuple)):
            val_tuple = tuple(val)
        else:
            val_tuple = (val,)

        # Ensure the number of fields matches the data dimensions.
        if len(val_tuple) + 1 != len(field_names):
            raise ValueError(
                f"Inconsistent field count for bin {i}: "
                f"expected {len(field_names)} but got {len(val_tuple) + 1}."
            )

        point = {field_names[0]: coord}
        for fn, vv in zip(field_names[1:], val_tuple):
            point[fn] = vv
        points.append(point)

    # Return a simple representation of a graph.
    return {"points": points, "scale": scale}

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Determine scale for graph
    try:
        if scale is True:
            scale_value = getattr(hist, "scale", None)
        else:
            scale_value = scale
    except Exception:
        scale_value = None

    n_fields = len(field_names)

    # Simple graph implementation
    class Graph:
        def __init__(self, scale):
            self.scale = scale
            self.field_names = field_names
            self.points = []

        def add_point(self, *args):
            if len(args) != len(self.field_names):
                raise ValueError(f"Expected {len(self.field_names)} values, got {len(args)}")
            self.points.append(args)

    graph = Graph(scale=scale_value)

    # Iterate over histogram bins
    try:
        bins_iter = iter(hist)
    except TypeError:
        raise ValueError("Histogram object must be iterable over bins")

    for bin_item in bins_iter:
        # Determine bin boundaries
        if hasattr(bin_item, "left") and hasattr(bin_item, "right"):
            left, right = bin_item.left, bin_item.right
        elif isinstance(bin_item, tuple) and len(bin_item) >= 2:
            left, right = bin_item[0], bin_item[1]
        else:
            raise ValueError("Histogram bin must have left/right attributes or be a tuple with at least two elements")

        if get_coordinate == "left":
            x_coord = left
        elif get_coordinate == "right":
            x_coord = right
        elif get_coordinate == "middle":
            x_coord = (left + right) / 2.0
        else:
            raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")

        # Get bin content
        if hasattr(bin_item, "content"):
            bin_content = bin_item.content
        elif isinstance(bin_item, tuple) and len(bin_item) >= 3:
            bin_content = bin_item[2]
        else:
            raise ValueError("Histogram bin must contain content as attribute 'content' or third element in the tuple")

        # Compute point value(s)
        if make_value is None:
            value = bin_content
        else:
            value = make_value(bin_content)

        if isinstance(value, (list, tuple)):
            point_vals = (x_coord,) + tuple(value)
        else:
            point_vals = (x_coord, value)

        if len(point_vals) != n_fields:
            raise ValueError(f"Number of fields {len(point_vals)} does not match expected {n_fields}")

        graph.add_point(*point_vals)

    return graph

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    try:
        from zope.interface import Invalid
    except Exception:
        # In case zope.interface is not available, raise a standard
        # exception with an informative message.
        raise RuntimeError("zope.interface is required for _verify")
    import inspect

    errors = []

    # 1. Check that candidate declares it provides the iface
    if not tentative:
        if not iface.providedBy(candidate):
            errors.append(f"Candidate does not provide {iface}")

    # 2. Check methods
    try:
        methods = iface.methods()
    except Exception:
        methods = {}
    for name, iface_method in methods.items():
        if not hasattr(candidate, name):
            errors.append(f"Missing required method '{name}'")
            continue
        cand_method = getattr(candidate, name)
        if not callable(cand_method):
            errors.append(f"Attribute '{name}' is not callable")
            continue
        # Compare signatures if possible
        try:
            sig_iface = inspect.signature(iface_method)
            sig_cand = inspect.signature(cand_method)
            if sig_iface.parameters != sig_cand.parameters:
                errors.append(
                    f"Signature mismatch for method '{name}': expected {sig_iface}, got {sig_cand}"
                )
        except Exception as exc:
            errors.append(f"Could not inspect signature of '{name}': {exc}")

    # 3. Check attributes
    try:
        attributes = iface.attributes()
    except Exception:
        attributes = {}
    for name in attributes.keys():
        if not hasattr(candidate, name):
            errors.append(f"Missing required attribute '{name}'")

    # 4. Raise or return
    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        raise Invalid("; ".join(errors))
    return True

def _verify(iface, candidate, tentative=False, vtype=None):
    """Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    import inspect
    errors = []

    # If tentative, skip the providedBy check
    if not tentative:
        try:
            provided = iface.providedBy(candidate)
        except Exception:
            provided = False
        if not provided:
            errors.append(f"{candidate!r} does not provide {iface!r}")

    # Helper to compare signatures lightly
    def _signature_match(sig_src, sig_cand):
        params_src = sig_src.parameters
        params_cand = sig_cand.parameters

        # Ensure all non-var parameters from source exist in candidate
        for name, param in params_src.items():
            if param.kind in (inspect.Parameter.VAR_POSITIONAL,
                              inspect.Parameter.VAR_KEYWORD):
                continue
            if name not in params_cand:
                return False

        # We will allow candidate to have extra parameters; this keeps checking lenient
        return True

    # Inspect methods defined in the interface
    try:
        interface_methods = getattr(iface, 'methods', None) or getattr(iface, '_methods', None)
    except Exception:
        interface_methods = None

    if interface_methods is None:
        # As a fallback, discover all callables in the interface namespace
        interface_methods = []
        for name in dir(iface):
            attr = getattr(iface, name, None)
            if callable(attr) and not name.startswith('_'):
                interface_methods.append(name)

    for name in interface_methods:
        cand_method = getattr(candidate, name, None)
        if cand_method is None:
            errors.append(f"Missing method {name!r} required by {iface!r}")
            continue

        # Verify signature if possible
        try:
            src_sig = inspect.signature(getattr(iface, name))
            cand_sig = inspect.signature(cand_method)
            if not _signature_match(src_sig, cand_sig):
                errors.append(
                    f"Signature mismatch for {name!r}: expected {src_sig}, got {cand_sig}"
                )
        except (ValueError, TypeError):
            # Skeleton signatures are not inspectable; ignore
            pass

    # Inspect required attributes
    try:
        required_attrs = getattr(iface, 'requiredAttributes', None)
        if required_attrs is None:
            required_attrs = getattr(iface, 'attributes', None)
    except Exception:
        required_attrs = None

    if required_attrs:
        for name in required_attrs:
            if not hasattr(candidate, name):
                errors.append(f"Missing required attribute {name!r} for {iface!r}")
            else:
                # Optional: we could check that the attribute is not callable if
                # interface expects a non-callable
                attr = getattr(candidate, name)
                if callable(attr):
                    # determine if interface expects callable
                    try:
                        iface_attr = getattr(iface, name)
                        if not callable(iface_attr):
                            errors.append(
                                f"Attribute {name!r} is callable but interface expects non-callable"
                            )
                    except Exception:
                        pass

    # If no errors, verification passed
    if not errors:
        return True

    # If only one error, raise it directly
    if len(errors) == 1:
        # Raise a zope.interface.Invalid with the single error
        raise zope.interface.Invalid(iface, candidate, errors=[errors[0]])

    # Multiple errors: aggregate them into a single exception
    msg = "; ".join(errors)
    raise zope.interface.Invalid(iface, candidate, errors=errors)

def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
    interface using ``iface.providedBy`` (unless *tentative* is `True`,
    in which case this step is skipped). This means that the candidate's class
    declares that it `implements <zope.interface.implementer>` the interface,
    or the candidate itself declares that it `provides <zope.interface.provider>`
    the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
    extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    import inspect

    errors = []

    # 1. Check interface provision unless tentative
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append(f"Candidate {candidate!r} does not provide interface {iface.__name__}")
        except Exception as e:
            errors.append(f"Error checking providedBy for {candidate!r}: {e}")

    # 2. Discover required interface members
    iface_members = {
        name: member
        for name, member in iface.__dict__.items()
        if not (name.startswith("_") or name in ("__dict__", "__weakref__"))
    }

    method_names = [name for name, member in iface_members.items() if callable(member)]
    attr_names = [name for name, member in iface_members.items() if not callable(member)]

    # 3. Verify attributes
    for attr in attr_names:
        if not hasattr(candidate, attr):
            errors.append(f"Candidate {candidate!r} missing required attribute '{attr}'")

    # 4. Verify methods
    for method in method_names:
        if not hasattr(candidate, method):
            errors.append(f"Candidate {candidate!r} missing required method '{method}'")
            continue

        cand_func = getattr(candidate, method)
        iface_func = iface_members[method]

        try:
            cand_sig = inspect.signature(cand_func)

            # Attempt to obtain interface signature
            try:
                iface_sig = inspect.signature(iface_func)
            except (ValueError, TypeError):
                iface_sig = None

            if iface_sig:
                if cand_sig.parameters != iface_sig.parameters:
                    errors.append(
                        f"Signature mismatch for method '{method}': "
                        f"expected {iface_sig}, got {cand_sig}"
                    )
        except Exception as e:
            errors.append(f"Error inspecting method '{method}' on {candidate!r}: {e}")

    # 5. Report errors (collecting all)
    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Helper to recursively verify a sequence of interfaces
    def _verify_sequence(seq, cand):
        for sub in seq:
            if not verifyClass(sub, cand, tentative=True):
                raise ValueError(f"Candidate {cand!r} does not satisfy interface {sub!r}")
        return True

    try:
        # Support a list/tuple of interfaces
        if isinstance(iface, (list, tuple)):
            return _verify_sequence(iface, candidate)

        # Candidate may be a class or an instance
        if isinstance(candidate, type):
            # Candidate is a class: must be a subclass of iface
            if not issubclass(candidate, iface):
                raise TypeError(f"{candidate} is not a subclass of {iface}")
            # If iface has abstract methods, ensure they are implemented
            abstract = getattr(iface, "__abstractmethods__", set())
            for m in abstract:
                if not hasattr(candidate, m):
                    raise TypeError(f"{candidate} does not implement abstract method '{m}' from {iface}")
            return True
        else:
            # Candidate is an instance: must be an instance of iface
            if not isinstance(candidate, iface):
                raise TypeError(f"{candidate!r} is not an instance of {iface}")
            return True

    except Exception as exc:
        if tentative:
            return False
        raise

def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*."""
    # Validate that iface is indeed a class or type
    if not isinstance(iface, type):
        raise TypeError(f"iface must be a class or type, got {type(iface)!r}")

    # When candidate is a class, check subclass relationship
    # When an instance, check isinstance relationship
    try:
        if isinstance(candidate, type):
            ok = issubclass(candidate, iface)
        else:
            ok = isinstance(candidate, iface)
    except Exception:
        ok = False

    if not ok:
        if tentative:
            return False
        raise TypeError(
            f"Candidate {candidate!r} does not implement or inherit from interface {iface.__name__}"
        )
    return True

def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*."""
    # Validate that iface is a class-like object
    if not isinstance(iface, type):
        raise TypeError(f"iface must be a class or interface, got {type(iface).__name__}")

    # Handle None candidate
    if candidate is None:
        raise ValueError("candidate cannot be None")

    # Determine the candidate's class (works for instances and classes)
    candidate_cls = candidate if isinstance(candidate, type) else candidate.__class__

    # 1. Check direct subclass relationship
    if issubclass(candidate_cls, iface):
        return True

    # 2. If iface defines abstract methods, ensure they exist on the candidate
    abstract_methods = getattr(iface, "__abstractmethods__", None)
    if abstract_methods:
        for name in abstract_methods:
            if not hasattr(candidate, name):
                if tentative:
                    return False
                raise TypeError(
                    f"{candidate!r} does not provide required method {name!r} for interface {iface.__name__}"
                )
        return True

    # 3. Fallback duck-typing: check that candidate has all public members of iface
    public_attrs = [attr for attr in dir(iface) if not attr.startswith("_")]
    for attr in public_attrs:
        if not hasattr(candidate, attr):
            if tentative:
                return False
            raise TypeError(
                f"{candidate!r} is missing attribute {attr!r} required by interface {iface.__name__}"
            )
    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__."""
    # Helper to pick the most derived metaclass between two candidates
    def _most_specific_meta(meta1, meta2):
        if issubclass(meta1, meta2):
            return meta1
        if issubclass(meta2, meta1):
            return meta2
        raise TypeError(
            f"Cannot create class with metaclass {meta1.__name__} "
            f"and {meta2.__name__} because they are not compatible."
        )

    if not bases:
        raise TypeError("determineMetaclass requires at least one base class")

    # Start with the metaclass of the first base or the explicit one if provided
    candidate = explicit_mc or type(bases[0])

    # Determine the most derived metaclass among all bases
    for base in bases[1:]:
        candidate = _most_specific_meta(candidate, type(base))

    # If an explicit metaclass was provided, ensure compatibility and pick the more derived
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError("explicit metaclass must be a class")
        if not issubclass(candidate, explicit_mc) and not issubclass(explicit_mc, candidate):
            raise TypeError(
