            if isinstance(dt, datetime.date) and not isinstance(dt, datetime):
                # Pure date, no time.
                return dt.strftime('%Y-%m-%d')
            # For full datetime objects.
            # isoformat() already produces the correct D* format.
            return dt.isoformat()
    except Exception:
        pass
    # Fallback: try a manual formatting.
    try:
        return str(dt)
    except Exception:
        return ''  # if formatting fails, return empty string.

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    import datetime
    # Helper to format a datetime object
    def _format_datetime(obj):
        # If timezone info is present, use full ISO format including offset
        if obj.tzinfo is not None:
            return obj.isoformat()
        # Assume UTC if no tzinfo and convert to ISO format ending with Z
        return obj.replace(tzinfo=datetime.timezone.utc).isoformat().replace('+00:00', 'Z')

    if isinstance(dt, datetime.datetime):
        return _format_datetime(dt)
    elif isinstance(dt, datetime.date):
        # Date only, ISO format
        return dt.isoformat()
    elif isinstance(dt, str):
        # Try to parse the string and then format
        try:
            # Python 3.7+ can parse ISO format directly
            parsed = datetime.datetime.fromisoformat(dt)
            return _format_datetime(parsed)
        except Exception:
            raise ValueError(f"Cannot parse datetime string: {dt!r}")
    else:
        raise TypeError(f"format_dt expects a datetime, date, or ISO string, got {type(dt).__name__}")

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    The expected format is ISO‑8601 with an optional
    timezone offset.  For naive datetime objects the
    offset is omitted.
    """
    if dt is None:
        raise ValueError("dt must not be None")

    # Ensure we have a datetime instance
    try:
        from datetime import datetime as _datetime
    except Exception:
        # If datetime module is not available, just convert to string
        return str(dt)

    if not isinstance(dt, _datetime):
        raise TypeError("dt must be a datetime instance")

    # Use isoformat with seconds precision; this handles timezones correctly
    try:
        return dt.isoformat(timespec='seconds')
    except TypeError:
        # For older Python versions that don't support timespec
        formatted = dt.strftime("%Y-%m-%dT%H:%M:%S")
        if dt.tzinfo:
            # Append timezone offset in the form +HH:MM
            offset_secs = dt.utcoffset().total_seconds()
            sign = '+' if offset_secs >= 0 else '-'
            offset_secs = abs(int(offset_secs))
            hours = offset_secs // 3600
            minutes = (offset_secs % 3600) // 60
            formatted += f"{sign}{hours:02d}:{minutes:02d}"
        return formatted

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")

    # Regex pattern to match http://, https://, and www. URLs
    import re
    url_pattern = r'\b(?:https?://|www\.)[^\s<>"\'`]+'

    def _replace(match):
        url = match.group(0)
        href = url
        # Add http:// when URL starts with www.
        if url.startswith('www.'):
            href = f'http://{url}'
        # Return linkified HTML tag with common attributes
        return f'<a href="{href}" target="_blank" rel="nofollow">{url}</a>'

    return re.sub(url_pattern, _replace, text)

