def check_sender_and_entity_handle_match(sender_handle, entity_handle):
    """Ensure that sender and entity handles match.

    Basically we've already verified the sender is who they say when receiving the payload. However, the sender might
    be trying to set another author in the payload itself, since Diaspora has the sender in both the payload headers
    AND the object. We must ensure they're the same.
    """
    # If either handle is None or not a string/bytes, raise an error for clarity
    if sender_handle is None or entity_handle is None:
        raise ValueError("Sender and entity handles must both be provided and non‑empty")

    # Compare the handles, normalizing them to strings if necessary
    try:
        if str(sender_handle).strip() != str(entity_handle).strip():
            raise ValueError(
                f"Sender handle '{sender_handle}' does not match entity handle '{entity_handle}'"
            )
    except Exception as exc:
        # Capture unexpected conversion errors
        raise ValueError(
            f"Error comparing sender and entity handles: {exc}"
        ) from exc

    # Handles match; nothing else to do
    return True

def get_nodeinfo_well_known_document(url, document_path=None):
    """
    Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Basic validation: url must contain scheme
    if not isinstance(url, str) or not url:
        raise ValueError("url must be a non-empty string")
    if not url.startswith(("http://", "https://")):
        raise ValueError("url must start with http:// or https://")

    # Normalise base url: strip trailing slash to avoid double slashes
    base = url.rstrip("/")
    if document_path is None:
        # Default NodeInfo 2.0 document path
        document_path = "/.well-known/nodeinfo/2.0"
    else:
        if not isinstance(document_path, str):
            raise ValueError("document_path must be a string")
        if not document_path.startswith("/"):
            document_path = "/" + document_path

    full_href = base + document_path

    # Construct minimal NodeInfo .well-known document
    return {
        "@context": "https://www.w3.org/ns/nodeinfo",
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/1.0",
                "href": full_href
            },
            {
                "rel": "self",
                "href": full_href
            }
        ]
    }

