def verify_relayable_signature(public_key, doc, signature):
    """Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message."""
    try:
        # Resolve the signature element: it may already be an Element
        if isinstance(signature, (bytes, str)):
            try:
                from lxml import etree
                sig_root = etree.fromstring(signature)
            except Exception as exc:
                raise ValueError("Signature string could not be parsed as XML") from exc
        else:
            sig_root = signature
        # Ensure we have a key
        if not public_key:
            raise ValueError("Public key is required for verification")
        # Load the key via xmlsec
        key = xmlsec.Key.from_memory(public_key, xmlsec.KeyFormat.PEM, None)
        ctx = xmlsec.SignatureContext()
        ctx.key = key
        # Register the ID attribute of the signed data (commonly 'Id')
        try:
            ctx.register_id(doc, "Id")
        except Exception:
            # ignore if registration fails (ID may not be present)
            pass
        # Perform verification: this will raise xmlsec.VerificationError on failure
        ctx.verify(sig_root)
        return True
    except Exception:
        return False

def parse_diaspora_webfinger(document: str) -> Dict:
    """Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    # First, try JSON parsing (new format)
    try:
        data = json.loads(document)
        if isinstance(data, dict):
            # Ensure a consistent format
            subject = data.get('subject')
            links = data.get('links', [])
            # Normalize links to a list of dicts if they are a list
            if isinstance(links, list):
                links = [link if isinstance(link, dict) else {} for link in links]
            return {'subject': subject, 'links': links}
    except json.JSONDecodeError:
        pass

    # Fallback to XRD XML parsing (old format)
    try:
        import xml.etree.ElementTree as ET
        root = ET.fromstring(document)

        # Handle optional namespace
        ns = ''
        if root.tag.startswith('{'):
            ns = root.tag[root.tag.find('{'):root.tag.find('}') + 1]

        subject_el = root.find(f'{ns}Subject')
        subject = subject_el.text if subject_el is not None else None

        links = []
        for link_el in root.findall(f'{ns}Link'):
            rel = link_el.get('rel')
            href = link_el.get('href')
            if rel and href:
                links.append({'rel': rel, 'href': href})

        return {'subject': subject, 'links': links}
    except Exception as exc:
        raise ValueError(f'Invalid Diaspora webfinger format: {exc}') from exc

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not isinstance(document, str) or not document.strip():
        raise ValueError("Input document must be a non-empty string")

    # Try JSON parsing first (new format)
    try:
        import json
        data = json.loads(document)
        if isinstance(data, dict):
            return data
    except json.JSONDecodeError:
        pass  # fall back to XRD parsing

    # Fallback: XRD (XML) parsing
    try:
        import xml.etree.ElementTree as ET

        def local_name(tag):
            return tag.split("}")[-1] if "}" in tag else tag

        root = ET.fromstring(document)
        if local_name(root.tag).lower() != "xrd":
            raise ValueError("Expected <XRD> root element")

        result: Dict[str, object] = {}
        # Extract Subject if present
        subject_el = root.find("./{*}Subject")
        if subject_el is not None and subject_el.text:
            result["subject"] = subject_el.text.strip()

        # Extract Link elements
        links = []
        for link_el in root.findall("./{*}Link"):
            link_dict = {}
            # All attributes
            for attr, val in link_el.attrib.items():
                if attr and val:
                    link_dict[attr] = val
            # Any direct child elements as key-value pairs
            for child in list(link_el):
                cname = local_name(child.tag)
                if child.text:
                    link_dict[cname] = child.text.strip()
            links.append(link_dict)
        if links:
            result["links"] = links

        return result

    except ET.ParseError as e:
        raise ValueError(f"Unable to parse Diaspora Webfinger: {e}") from e
    except Exception as e:
        raise ValueError(f"Unexpected error while parsing Diaspora Webfinger: {e}") from e

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    # First try JSON
    try:
        import json
        return json.loads(document)
    except Exception:
        pass

    # Try XML/XRD
    try:
        import xml.etree.ElementTree as ET
        root = ET.fromstring(document)
    except Exception as exc:
        raise ValueError(f"Unable to parse webfinger document as JSON or XML/XRD: {exc}") from exc

    def _elem_to_dict(elem):
        """
        Recursively convert an XML element into a nested dictionary.
        Attributes are prefixed with '@', text content stored under '#text'.
        """
        d: Dict = {}
        # Attributes
        for k, v in elem.attrib.items():
            d[f"@{k}"] = v

        # Text content (if any and element has no children)
        text = elem.text.strip() if elem.text and elem.text.strip() else None
        if text:
            d["#text"] = text

        # Children
        children = list(elem)
        if children:
            child_counts: Dict[str, int] = {}
            for ch in children:
                child_dict = _elem_to_dict(ch)
                tag = ch.tag
                child_counts[tag] = child_counts.get(tag, 0) + 1
                if child_counts[tag] == 1:
                    # first occurrence
                    d[tag] = child_dict[tag]
                else:
                    # multiple occurrences, convert to list
                    if not isinstance(d[tag], list):
                        d[tag] = [d[tag]]
                    d[tag].append(child_dict[tag])

        return {elem.tag: d}

    return _elem_to_dict(root)[:] if isinstance(_elem_to_dict(root), list) else _elem_to_dict(root)

