                result["aliases"].append(elem.text)
        elif name == "Link":
            rel = elem.attrib.get("rel") or elem.attrib.get("relationship")
            href = elem.attrib.get("href") or elem.attrib.get("uri") or elem.attrib.get("uri-href")
            type_ = elem.attrib.get("type")
            if href:
                result["links"].append({"rel": rel, "href": href, "type": type_})
    return result

