def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    # Basic input validation
    if not isinstance(url, str):
        return None, TypeError("url must be a string")
    if data is not None and not isinstance(data, (dict, bytes, bytearray, str, type)):
        # type is placeholder to allow file-like objects
        if not hasattr(data, 'read'):
            return None, TypeError("data must be dict, bytes, or file-like object")
    try:
        timeout = float(timeout)
    except Exception:
        return None, TypeError("timeout must be a number")
    if not isinstance(method, str):
        return None, TypeError("method must be a string")
    method_lower = method.lower()
    if method_lower not in ("post", "put"):
        return None, ValueError(f"Unsupported method: {method!r}")

    try:
        if method_lower == "post":
            response = requests.post(url, data=data, timeout=timeout, *args, **kwargs)
        else:  # method_lower == "put"
            response = requests.put(url, data=data, timeout=timeout, *args, **kwargs)
        # Ensure we always return an integer status code
        status = response.status_code
        if not isinstance(status, int):
            status = None
        return status, None
    except Exception as exc:
        return None, exc

