def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1', 'key2')

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    if not isinstance(dic, dict):
        raise TypeError("dic must be a dictionary")

    # If ``key`` is an iterable of strings other than a plain string,
    # treat the entire sequence as the key chain.
    if isinstance(key, str):
        chain = [key] + list(keys)
    else:
        chain = list(key) + list(keys)

    if not chain:
        raise ValueError("No key specified for insertion")

    cur = dic
    # Traverse all keys except the last one, creating nested dicts as necessary.
    for k in chain[:-1]:
        if not isinstance(k, str):
            raise TypeError(f"Key element {k!r} is not a string")
        if k not in cur:
            cur[k] = {}
        elif not isinstance(cur[k], dict):
            # Existing non-dict value will be overridden by a dict
            cur[k] = {}
        cur = cur[k]

    # Finally set the value for the last key.
    last_key = chain[-1]
    if not isinstance(last_key, str):
        raise TypeError(f"Key element {last_key!r} is not a string")
    cur[last_key] = val

    return dic

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    Returns a sorted list of file paths from the given directories that end with the
    supplied spec_option (default: '.ini'). Directories that cannot be accessed
    are ignored, and any non‑string entries in `settings_dirs` are skipped.
    Arguments:
        settings_dirs (Iterable[str]): Sequence of directory paths to search.
        spec_option (str): File extension pattern to filter on, e.g. '.ini' or 'txt'.
    Returns:
        List[str]: Sorted list of matching file paths.
    Raises:
        ValueError: If spec_option is not a string or if settings_dirs is not iterable.
    """
    import os

    # Validate inputs
    if not isinstance(spec_option, str):
        raise ValueError("spec_option must be a string")
    try:
        iter(settings_dirs)
    except TypeError:
        raise ValueError("settings_dirs must be an iterable of path strings")

    # Normalise spec_option to include a leading dot only if missing
    if spec_option and not spec_option.startswith('.'):
        spec_option = f".{spec_option}"

    file_list = []
    for dir_path in settings_dirs:
        if not isinstance(dir_path, str):
            # Skip non-string entries silently
            continue
        try:
            if not os.path.isdir(dir_path):
                # Skip if not a directory
                continue
            for fname in os.listdir(dir_path):
                full_path = os.path.join(dir_path, fname)
                if os.path.isfile(full_path):
                    if not spec_option or fname.lower().endswith(spec_option.lower()):
                        file_list.append(full_path)
        except OSError:
            # Unable to access directory – skip it and continue
            continue

    return sorted(file_list)

