        An iterable of directory paths to search for files.
    spec_option : str or Iterable[str]
        Glob pattern(s) to match filenames within the directories. If none
        provided or an empty string, all files are returned.

    Returns
    -------
    List[str]
        A sorted list of absolute file paths that match the specified pattern(s).

    Raises
    ------
    ValueError
        If *settings_dirs* is not iterable or contains nonexistent directories,
        or if *spec_option* is not a string or an iterable of strings.
    """
    # Lazy imports to avoid side effects on module import
    import os
    from glob import glob

    # Validate settings_dirs
    try:
        dirs_iter = iter(settings_dirs)
    except TypeError:
        raise ValueError("settings_dirs must be an iterable of directory paths")

    # Resolve spec_option into a list of patterns
    if spec_option is None or (isinstance(spec_option, str) and spec_option == ""):
        patterns = ["*"]
    elif isinstance(spec_option, str):
        patterns = [spec_option]
    else:
        try:
            patterns = list(spec_option)
            if not patterns:
                patterns = ["*"]
        except TypeError:
            raise ValueError("spec_option must be a string or an iterable of strings")

    file_set = set()
    for dir_path in dirs_iter:
        if not isinstance(dir_path, str):
            raise ValueError(f"Directory path {dir_path!r} is not a string")
        abs_dir = os.path.abspath(dir_path)
        if not os.path.isdir(abs_dir):
            raise ValueError(f"Directory does not exist: {abs_dir!r}")

        for pattern in patterns:
            join_pattern = os.path.join(abs_dir, pattern)
            for matched in glob(join_pattern):
                if os.path.isfile(matched):
                    file_set.add(os.path.abspath(matched))

    # Return sorted list for deterministic ordering
    return sorted(file_set)

