def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    # Use a recursive resolver with a visited set to prevent circular references.
    visited = set()

    def _resolve_group(group_name):
        """Recursively resolve a single group, merging includes."""
        if group_name in visited:
            # Circular reference detected; stop recursion.
            raise ValueError(f"Circular include detected for group '{group_name}'")
        visited.add(group_name)

        if group_name not in parser_dict:
            raise KeyError(f"Included group '{group_name}' not present in parser_dict")

        group_def = parser_dict[group_name]
        if not isinstance(group_def, dict):
            raise TypeError(f"Group definition for '{group_name}' must be a dict")

        # Create a copy so that we don't mutate the original parser_dict.
        merged = {}

        # Handle include directive; it may be a single name or a list of names.
        include = group_def.pop('include', None)
        if include:
            if isinstance(include, str):
                include = [include]
            if not isinstance(include, (list, tuple)):
                raise TypeError(f"'include' directive for group '{group_name}' must be a string or a list of strings")

            for inc in include:
                merged.update(_resolve_group(inc))

        # Merge the remaining keys of the current group, overwriting any duplicates.
        merged.update(group_def)
        return merged

    # Resolve all groups in the dictionary.
    resolved_dict = {}
    for gname in parser_dict:
        resolved_dict[gname] = _resolve_group(gname)

    return resolved_dict

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    # The `include` directive can be a single string or a list/tuple of keys
    # that reference other dictionaries inside `parser_dict`. Those dictionaries
    # are merged into the current one in a depth‑first manner.
    #
    # Example:
    #     parser_dict = {
    #         'foo': {'a': 1},
    #         'bar': {'b': 2},
    #         'include': ['foo', 'bar']
    #     }
    # After calling `_include_groups`, parser_dict becomes:
    #     {'a': 1, 'b': 2}
    #
    # This method consumes the keys that are included; after the call they
    # are no longer present in `parser_dict`.
    try:
        include_keys = parser_dict.pop('include', [])
        # Normalise a single key or non‑iterable to a list of keys
        if isinstance(include_keys, str):
            include_keys = [include_keys]
        elif not isinstance(include_keys, (list, tuple, set)):
            raise TypeError(f"Expected a list, tuple, set or string for 'include', got {type(include_keys).__name__}")
    except Exception as exc:
        raise ValueError(f"Error retrieving 'include' directive: {exc}") from exc

    # Resolve includes recursively – if an included dict itself contains an
    # `include` key we want to process that in turn.
    def _merge(source, merged):
        for key, value in list(source.items()):
            if key == 'include':
                # Recursively handle nested include lists
                nested = source.pop(key)
                if isinstance(nested, str):
                    nested = [nested]
                elif not isinstance(nested, (list, tuple, set)):
                    raise TypeError(f"Expected a list, tuple, set or string for nested 'include', got {type(nested).__name__}")
                for subkey in nested:
                    if subkey in source:
                        _merge(source.pop(subkey), merged)
            else:
                # Merge non‑include elements; later keys overwrite earlier ones
                merged[key] = value

    merged_dict = {}
    for key in include_keys:
        if key not in parser_dict:
            continue  # silently ignore missing keys
        include_item = parser_dict.pop(key)
        if isinstance(include_item, dict):
            _merge(include_item, merged_dict)
        else:
            # If the included value is not a dict, we simply store it as a key
            merged_dict[key] = include_item

    # Update the original parser_dict with merged entries
    parser_dict.update(merged_dict)
    return parser_dict

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if not isinstance(parser_dict, dict):
        raise TypeError("parser_dict must be a dict")

    visited_groups = set()

    def _resolve_group(group_name, group_dict):
        # Avoid infinite recursion
        if id(group_dict) in visited_groups:
            raise ValueError(f"Circular include detected for group '{group_name}'")
        visited_groups.add(id(group_dict))

        include_key = None
        for key, value in list(group_dict.items()):
            if key == 'include':
                include_key = value
                break

        if include_key:
            if include_key not in parser_dict:
                raise KeyError(f"Include reference '{include_key}' not found in parser_dict")
            included_group = parser_dict[include_key]
            if not isinstance(included_group, dict):
                raise TypeError(f"Included group '{include_key}' must be a dict")
            # Resolve nested includes first
            _resolve_group(include_key, included_group)
            # Merge included group into current group, preserving local overrides
            merged = included_group.copy()
            merged.update(group_dict)
            # Remove the 'include' directive after merging
            merged.pop('include', None)
            # Update the original group_dict reference
            group_dict.clear()
            group_dict.update(merged)

        # Recursively resolve any nested sub‐groups
        for sub_key, sub_value in list(group_dict.items()):
            if isinstance(sub_value, dict):
                _resolve_group(sub_key, sub_value)

    # Process all top-level groups
    for top_key, top_value in list(parser_dict.items()):
        if isinstance(top_value, dict):
            _resolve_group(top_key, top_value)

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    def _load_and_merge(include_path):
        """Recursively load a spec file and merge its contents."""
        import os
        import json

        # Resolve relative paths based on the current working directory
        include_path = os.path.abspath(include_path)

        if not os.path.isfile(include_path):
            raise FileNotFoundError(f"Included spec file '{include_path}' not found")

        with open(include_path, "r", encoding="utf-8") as fh:
            try:
                data = json.load(fh)
            except Exception as exc:
                raise ValueError(f"Failed to parse JSON in included file '{include_path}': {exc}") from exc

        # Recursively process includes inside the included file
        return self._include_groups(data)

    def _merge_dicts(result, new, path=""):
        """Merge `new` into `result` recursively, overwriting existing keys."""
        for key, value in new.items():
            if key in result and isinstance(result[key], dict) and isinstance(value, dict):
                _merge_dicts(result[key], value, path + f".{key}" if path else key)
            else:
                result[key] = value

    # Normalize the parser_dict input
    if not isinstance(parser_dict, dict):
        raise TypeError("parser_dict must be a dictionary")

    result = {}
    # Detect include keyword(s)
    include_keys = {"include", "includes", "include_dict"}
    include_entries = []

    for key in list(parser_dict.keys()):
        if key in include_keys:
            include_entries.append(parser_dict.pop(key))

    # Convert include entries to a flat list of paths
    paths = []
    for entry in include_entries:
        if isinstance(entry, str):
            paths.append(entry)
        elif isinstance(entry, (list, tuple)):
            paths.extend(entry)
        else:
            raise TypeError(f"Include entry must be a string or a list/tuple of strings, got {type(entry).__name__}")

    # Load and merge each included spec
    for p in paths:
        inc_dict = _load_and_merge(p)
        _merge_dicts(result, inc_dict)

    # Merge the remaining keys from the original dict
    _merge_dicts(result, parser_dict)

    return result

