    except Exception:
        spec = None

    defaults = {}
    if isinstance(spec, dict):
        for name, definition in spec.items():
            # ``definition`` could be a dict, an object with attributes, or simply a
            # default value.  Try the most common patterns step by step.
            try:
                # If it's a dict with a 'default' key, use that.
                if isinstance(definition, dict) and "default" in definition:
                    defaults[name] = definition["default"]
                    continue
                # If it's an object with a ``default`` attribute, use that.
                if hasattr(definition, "default"):
                    defaults[name] = getattr(definition, "default")
                    continue
                # Otherwise treat the value itself as the default.
                defaults[name] = definition
            except Exception:
                # If anything goes wrong we skip this entry.
                continue

