    # the argument names (uppercased).  This is a lightweight fallback that
    # can surface defaults from external configuration.
    try:
        import os
        for key in list(defaults.keys()):
            if defaults[key] is None:
                env_val = os.getenv(key.upper())
                if env_val is not None:
                    defaults[key] = env_val
    except Exception:
        # Ignore any import or lookup errors – they are not critical.
