    deprecation_map = getattr(self, 'DEPRECATED_ARGS', {})

    # Helper to process a single args dictionary
    def _process(arg_dict):
        for key in list(arg_dict):
            if key in deprecation_map:
                new_name = deprecation_map[key]
                message = f"Argument '{key}' is deprecated."
                if new_name:
                    message += f" Use '{new_name}' instead."
                # Prefer a logger if available, otherwise fallback to print
                if hasattr(self, 'logger') and hasattr(self.logger, 'warning'):
                    self.logger.warning(message)
                else:
                    print(message)

                # If a replacement name exists, forward the value
                if new_name:
                    if new_name in arg_dict:
                        # Avoid accidental overwrite; keep existing value
                        pass
                    else:
                        arg_dict[new_name] = arg_dict.pop(key)
                else:
                    # Just remove the deprecated argument
                    arg_dict.pop(key)

    # Validate CLI and answer file arguments
    _process(cli_args)
    _process(answer_file_args)

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    Note: The class implementing this method should provide a list of
    deprecated argument names via an attribute named ``DEPRECATED_ARGS``
    or ``deprecated_args`` (list or set).  Any deprecated argument found
    in either ``cli_args`` or ``answer_file_args`` will result in a
    warning message and will be removed from the combined defaults
    before the arguments are returned.

    :param cli_args: dict of arguments parsed from the command line
    :param answer_file_args: dict of arguments loaded from an answer file
    :return: dict containing the final merged arguments after deprecation
        handling
    """
    # Get the list of deprecated arguments, if any
    deprecated = getattr(self, "DEPRECATED_ARGS", None)
    if deprecated is None:
        deprecated = getattr(self, "deprecated_args", None)
    if not deprecated:
        # Nothing to deprecate – just merge the dictionaries
        return {**answer_file_args, **cli_args}

    # Merge the answer file arguments with the CLI arguments;
    # CLI values override the file ones
    combined = {**answer_file_args, **cli_args}

    # Identify and remove deprecated arguments
    removed = []
    for key in list(combined.keys()):
        if key in deprecated:
            removed.append(key)

    if removed:
        msg = (
            "Deprecated arguments encountered: "
            + ", ".join(f"'{arg}'" for arg in removed)
            + ". They will be ignored."
        )
        # Inform the user – use a warning level if available, otherwise print
        try:
            import warnings
            warnings.warn(msg)
        except Exception:
            print(msg)

        for arg in removed:
            combined.pop(arg, None)

    return combined

