        parsers = getattr(self, "_commands", {})
        parser = parsers.get(command_name)
        if parser is None:
            raise KeyError
    except AttributeError:
        # Fallback: maybe a namespace with parsers as attributes
        parser = getattr(self, command_name, None)

    if not parser:
