def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Basic type checking
    if not isinstance(command_name, str):
        raise TypeError(f"command_name must be a string, got {type(command_name).__name__}")
    if not isinstance(argument_name, str):
        raise TypeError(f"argument_name must be a string, got {type(argument_name).__name__}")

    # Determine where the option definitions are stored.
    # Try common attribute names; fall back to an empty dict.
    options_container = getattr(self, "_options", None) or getattr(self, "options", None)
    if not isinstance(options_container, dict):
        raise AttributeError(
            "The object does not have a mapping of command options "
            "stored in '_options' or 'options' attribute."
        )

    # Retrieve the options for the specified command
    if command_name not in options_container:
        raise KeyError(f"Unknown command '{command_name}'. Available commands: {sorted(options_container)}")

    command_options = options_container[command_name]

    # If the command options are stored as a dict keyed by argument name, get it directly
    if isinstance(command_options, dict):
        spec = command_options.get(argument_name)
        if spec is not None:
            return spec

    # If they are stored as a list/tuple of option spec dictionaries,
    # find the one matching the argument name
    if isinstance(command_options, (list, tuple)):
        for opt in command_options:
            # Common keys that might hold the option identifier
            for key in ("argument", "name", "arg", "id"):
                if opt.get(key) == argument_name:
                    return opt

    # If we reach this point, the option spec was not found
    raise KeyError(
        f"Option '{argument_name}' not found for command '{command_name}'."
    )

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    if not isinstance(command_name, str) or not isinstance(argument_name, str):
        raise TypeError("command_name and argument_name must be strings")
    cmd = self.commands.get(command_name)
    if cmd is None:
        raise KeyError(f"Command '{command_name}' not found")
    spec = None
    if hasattr(cmd, "options") and isinstance(cmd.options, dict):
        spec = cmd.options.get(argument_name)
    if spec is None:
        # Try a get_option_spec method on the command itself
        try:
            spec = cmd.get_option_spec(argument_name)
        except Exception:
            spec = None
    if spec is None:
        raise KeyError(f"Option '{argument_name}' not found in command '{command_name}'")
    return spec

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    silent = []
    if args is None:
        return silent
    try:
        # If args behaves like a dict
        if hasattr(args, "items"):
            iterator = args.items()
        else:
            # Otherwise treat it as an iterable of (name, value) pairs
            iterator = args
        for item in iterator:
            if isinstance(item, (tuple, list)) and len(item) >= 2:
                name, value = item[0], item[1]
            else:
                # If only a name is provided, assume silent
                name, value = item, None
            # Consider None or False as silent
            if value is None or value is False:
                silent.append(name)
    except Exception:
        # In case of unexpected input, just ignore
        pass
    return silent

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    # Normalise to a list of names where the supplied value is considered
    # "silent" – i.e. None, an empty string (or whitespace only), or an empty
    # container. These are the arguments that will not trigger any action.
    if args is None:
        return []

    if not isinstance(args, dict):
        raise TypeError("args must be a dict")

    silent = []
    for name, value in args.items():
        if value is None:
            silent.append(name)
        elif isinstance(value, (str, bytes)):
            if value.strip() == "":
                silent.append(name)
        elif isinstance(value, (list, tuple, set, dict)):
            if len(value) == 0:
                silent.append(name)

    return silent

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    silent_names = []
    try:
        if args is None:
            return silent_names

        if isinstance(args, dict):
            for name, val in args.items():
                if val is None:
                    silent_names.append(name)

        elif isinstance(args, (list, tuple)):
            for item in args:
                if isinstance(item, (list, tuple)) and len(item) == 2:
                    name, val = item
                    if val is None:
                        silent_names.append(name)
                else:
                    # If it's just a name without a value, assume it is not silent.
                    pass
        else:
            raise TypeError(f"Unsupported args type: {type(args)}")
    except Exception as exc:
        # Log or handle exceptional situations here, if needed.
        raise ValueError(f"Error processing silent arguments: {exc}") from exc

    # Return unique names preserving the original order
    seen = set()
    unique_silent = []
    for name in silent_names:
        if name not in seen:
            seen.add(name)
            unique_silent.append(name)

    return unique_silent

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    try:
        # Handle dictionary inputs
        if isinstance(args, dict):
            return [k for k in args.keys() if isinstance(k, str) and k.startswith('_')]
        # Handle iterable of (name, value) tuples or simple names
        elif isinstance(args, (list, tuple)):
            if all(isinstance(item, (tuple, list)) and len(item) == 2 for item in args):
                return [k for k, _ in args if isinstance(k, str) and k.startswith('_')]
            else:
                return [name for name in args if isinstance(name, str) and name.startswith('_')]
        # Handle objects that expose .keys() (like mappings)
        elif hasattr(args, 'keys'):
            return [k for k in args.keys() if isinstance(k, str) and k.startswith('_')]
        else:
            raise TypeError("Unsupported type for args: %r" % type(args))
    except Exception:
        # In case of any unexpected error, return empty list to avoid breaking caller
        return []

