    """Check if all the required arguments have been provided. """
    # The required arguments list should be defined on the instance – fall back to an attribute named
    # 'REQUIRED_ARGS' or 'required_args' if present.
    required = getattr(self, "REQUIRED_ARGS", None)
    if required is None:
        required = getattr(self, "required_args", None)
    if required is None:
