            if isinstance(opt, dict):
                opt_name = opt.get('name')
                required_when = opt.get('required_when')
            else:
                opt_name = getattr(opt, 'name', None)
                required_when = getattr(opt, 'required_when', None)

            if not opt_name:
                continue

            if required_when is None:
                continue

            # Evaluate the required_when condition
            condition_met = False
            try:
                # If the required_when is a callable, call it with args
                if callable(required_when):
                    condition_met = bool(required_when(args))
                # If it's already a boolean value
                elif isinstance(required_when, bool):
                    condition_met = required_when
                # Assume it's a string expression that can be evaluated against args
                else:
                    # Ensure args is at least a dict for eval locals
                    local_args = args if isinstance(args, dict) else {}
                    condition_met = bool(eval(required_when, {}, local_args))
            except Exception:
                # Any exception evaluating the condition is treated as False
                condition_met = False

            if condition_met:
                required.append(opt_name)
    except Exception:
        # In the event of any unexpected error, return the currently collected required list (which may be empty)
        pass

