                                required.append(opt.get('name'))
                                break
                            if isinstance(condition, dict) and all(args.get(k) == v for k, v in condition.items()):
                                required.append(opt.get('name'))
                                break
                        except Exception:
                            # Ignore individual condition errors.
                            continue
                # Other types of `required_when` are ignored.
            except Exception:
                # Any error evaluating a condition is ignored so that the
                # method can still return those that are reliably matched.
                continue
        return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Determine the length limit. It can be defined on the instance (MAX_LENGTH)
    # or on the class (MAX_LENGTH). If none is found, skip validation.
    limit = getattr(self, 'MAX_LENGTH', None)
    if limit is None:
        limit = getattr(self.__class__, 'MAX_LENGTH', None)

    # If no limit defined, nothing to validate.
    if limit is None:
        return

    def _check(value, idx):
        if isinstance(value, (str, list, tuple)):
            if len(value) > limit:
                raise ValueError(
                    f"Argument {idx} length {len(value)} exceeds maximum allowed {limit}"
                )
        if isinstance(value, dict):
            for key, sub in value.items():
                _check(sub, f"{idx}.{key}")

    # Support args being a sequence, mapping or a single value
    if isinstance(args, (list, tuple)):
        for i, value in enumerate(args):
            _check(value, i)
    elif isinstance(args, dict):
        for key, value in args.items():
            _check(value, key)
    else:
        _check(args, 'value')

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: A mapping of argument names to their values. Each value can be one
        of the following:
            * a raw value whose length is to be checked against the argument's
              predefined maximum length stored elsewhere.
            * a tuple/list of the form (value, max_length)
            * a dict containing the keys ``value`` and ``max_length``.
        If no maximum length is specified for an argument, it is skipped.

    This method raises :class:`ValueError` if any argument exceeds its
    allowed length.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dict mapping argument names to values or specs")

    for arg_name, spec in args.items():
        # Determine value and maximum length to check.
        if isinstance(spec, dict):
            value = spec.get('value')
            max_length = spec.get('max_length')
        elif isinstance(spec, (tuple, list)) and len(spec) == 2:
            value, max_length = spec
        else:
            # Treat the spec itself as the value; no max_length provided.
            value = spec
            max_length = None

        # Only perform length check if we have a max_length defined.
        if max_length is None:
            continue

        try:
            max_len = int(max_length)
        except (TypeError, ValueError):
            raise ValueError(f"Maximum length for argument '{arg_name}' must be an integer")

        try:
            val_len = len(value)
        except TypeError:
            # If the value does not have a length (e.g., an integer), skip checking.
            continue

        if val_len > max_len:
            raise ValueError(
                f"Argument '{arg_name}' exceeds maximum length of {max_len} "
                f"(current length: {val_len})"
            )

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.  It may be a mapping from
                 argument name to a ``(value, max_length)`` tuple, or
                 a sequence of such tuples.  Only string values are
                 length‑checked.
    """
    if not isinstance(args, (dict, list, tuple)):
        raise TypeError(f'args must be a dict or a sequence, got {type(args).__name__!r}')

    # Determine how to iterate over the arguments
    if isinstance(args, dict):
        items = args.items()
    else:  # sequence
        items = enumerate(args)

    for key, pair in items:
        # We expect each element to be a tuple of length 2: (value, max_length)
        if not (isinstance(pair, tuple) and len(pair) == 2):
            raise ValueError(f'argument {key!r} does not contain a (value, max_length) tuple')
        value, max_length = pair

        if max_length is None:
            # No length restriction specified
            continue
        if not isinstance(max_length, int):
            raise TypeError(f'max_length for argument {key!r} must be an int, got {type(max_length).__name__!r}')

        # Convert the value to string for length comparison if it is not None
        if value is not None:
            # Ensure we have a string representation; other types with a __len__ attribute
            try:
                string_value = str(value)
            except Exception as exc:
                raise TypeError(f'cannot convert argument {key!r} to string: {exc!r}')

            if len(string_value) > max_length:
                raise ValueError(
                    f'argument {key!r} exceeds maximum length of {max_length} '
                    f'(actual length {len(string_value)})'
                )
    # If we reach this point, all arguments satisfy their length limits
    return True

def validate_length_args(self, args):
        """Check if value of arguments is not longer than length specified.

        :param args: The received arguments. Expected to be a mapping of argument names to values.
        """
        # Determine the maximum allowed lengths for each argument. Subclasses or instances may define
        # an ``argument_lengths`` dictionary mapping argument names to the maximum string length.
        max_lengths = getattr(self, "argument_lengths", None)
        if not max_lengths:
            # Nothing to validate: silently return
            return

        if not isinstance(args, dict):
            raise TypeError("args must be a dictionary mapping argument names to values")

        for name, value in args.items():
            # Skip arguments that are not present in the length specification
            if name not in max_lengths:
                continue

            # Treat None as empty string; skip if value is not stringifiable
            try:
                value_str = "" if value is None else str(value)
            except Exception as exc:
                raise ValueError(f"Could not convert value of argument '{name}' to string for length check: {exc}") from exc

            if len(value_str) > max_lengths[name]:
                raise ValueError(
                    f"Argument '{name}' length {len(value_str)} exceeds maximum "
                    f"{max_lengths[name]}"
                )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    Parameters
    ----------
    args : mapping
        The received arguments. Keys are the argument names and the values are
        the supplied argument values.  The values can be a single value or a
        list/tuple of values for arguments that accept multiple choices.
    """
    # Attempt to find the set of valid choices for each argument.
    # Many frameworks expose a ``choices`` attribute or a dedicated mapping
    # (e.g. ``self._choices``); we try a few common patterns.
    for arg_name, value in args.items():
        # Retrieve the argument descriptor.  It may be an attribute of this
        # object, an entry in a ``_args`` dict, or an entry in a ``_choices``
        # mapping.  Any of these will provide a ``choices`` or
        # ``allowed_values`` attribute.
        arg_desc = None
        if hasattr(self, arg_name):
            arg_desc = getattr(self, arg_name)
        elif hasattr(self, "_args") and isinstance(self._args, dict):
            arg_desc = self._args.get(arg_name)
        elif hasattr(self, "_choices") and isinstance(self._choices, dict):
            # If ``_choices`` already stores the allowed values we can use that
            # and skip the descriptor lookup.
            arg_desc = None

        # Determine the set of allowed values.
        allowed = None
        if isinstance(self, type(List[object])):  # placeholder for interface
            pass
        # First check for the mapping of allowed values (most straightforward)
        if hasattr(self, "_choices") and isinstance(self._choices, dict):
            allowed = self._choices.get(arg_name)
        # If not found, fall back to the descriptor attributes.
        if allowed is None and arg_desc is not None:
            allowed = getattr(arg_desc, "choices", None) or getattr(arg_desc, "allowed_values", None)

        # If we have a set of allowed choices, validate the supplied value(s).
        if allowed:
            # Handle multiple values (lists/tuples) and single values.
            if isinstance(value, (list, tuple)):
                for val in value:
                    if val not in allowed:
                        raise ValueError(
                            f"Argument '{arg_name}' value '{val}' is not one of the allowed choices: {allowed}"
                        )
            else:
                if value not in allowed:
                    raise ValueError(
                        f"Argument '{arg_name}' value '{value}' is not one of the allowed choices: {allowed}"
                    )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Retrieve the mapping of argument names to their allowed values.
    # Subclasses / instances may define this as `choices`, `choice_map`, or `param_choices`.
    # We look for the most common name first, then fallback to any of the others.
    choices_map = getattr(self, 'choices', None)
    if choices_map is None:
        choices_map = getattr(self, 'choice_map', None)
    if choices_map is None:
        choices_map = getattr(self, 'param_choices', {})
    if not isinstance(choices_map, (dict,)):
        # If no mapping is defined, nothing to validate.
        return

    for arg_name, allowed_values in choices_map.items():
        if arg_name not in args:
            continue

        # The argument may be passed as a single value or an iterable (list/tuple/set).
        raw_val = args[arg_name]
        values_to_check = raw_val if isinstance(raw_val, (list, tuple, set)) else [raw_val]

        for val in values_to_check:
            if val not in allowed_values:
                raise ValueError(
                    f"Invalid value '{val}' for argument '{arg_name}'. "
                    f"Allowed choices: {allowed_values}"
                )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError(f"args must be a dict, got {type(args).__name__}")

    for key, val in args.items():
        # Skip if the attribute does not exist
        descriptor = getattr(self, key, None)
        if descriptor is None:
            continue

        # Support attributes that expose a 'choices' iterable
        choices = getattr(descriptor, 'choices', None)
        if choices is None:
            continue

        # Ensure choices is iterable
        try:
            iter(choices)
        except TypeError:
            raise TypeError(f"choices for argument '{key}' must be an iterable")

        # Validate scalar or iterable values
        if isinstance(val, (list, tuple)):
            for v in val:
                if v not in choices:
                    raise ValueError(
                        f"Invalid choice for argument '{key}': {v}. "
                        f"Allowed: {list(choices)}"
                    )
        else:
            if val not in choices:
                raise ValueError(
                    f"Invalid choice for argument '{key}': {val}. "
                    f"Allowed: {list(choices)}"
                )
    return None

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        return

    for name, value in args.items():
        # Try to obtain the argument specification from the instance
        try:
            arg_obj = getattr(self, name, None)
        except Exception:  # pragma: no cover
            arg_obj = None

        # If no such attribute exists, skip this argument
        if arg_obj is None:
            continue

        # Look for a ``choices`` attribute or property
        choices = getattr(arg_obj, "choices", None)
        if choices is None:
            # Some frameworks store choices in a dictionary
            try:
                spec = getattr(self, "arg_spec", None) or getattr(self, "_arg_spec", None)
                if spec and name in spec:
                    choices = spec[name].get("choices")
            except Exception:  # pragma: no cover
                choices = None

        # Skip validation if no choice list is defined
        if choices is None:
            continue

        # Validate the provided value
        if value not in choices:
            raise ValueError(
                f"Invalid value for argument '{name}': {value!r}. "
                f"Allowed choices are: {choices}"
            )

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Determine the bounds.  If the instance does not expose ``min`` and ``max``,
    # we simply skip validation.
    try:
        min_val = getattr(self, "min", None)
        max_val = getattr(self, "max", None)
    except Exception as exc:
        raise ValueError("Unable to obtain min/max bounds") from exc

    if min_val is None or max_val is None:
        return

    # Flexible handling of the incoming arguments.
    if isinstance(args, dict):
        values = args.values()
    else:
        values = args

    for val in values:
        # Some library objects wrap the numeric value in a ``value`` attribute.
        try:
            check_val = val.value if hasattr(val, "value") else val
        except Exception:
            # If we cannot access the value, skip it.
            continue

        try:
            if check_val < min_val or check_val > max_val:
                raise ValueError(
                    f"Value {check_val!r} outside allowed range [{min_val!r}, {max_val!r}]"
                )
        except TypeError as exc:
            # The value cannot be compared to the bounds.
            raise ValueError(
                f"Value {check_val!r} is not comparable to bounds {min_val!r} - {max_val!r}"
            ) from exc"""

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Determine iterable vs single value
    if args is None:
        values = []
    else:
        try:
            values = list(args)
        except TypeError:
            values = [args]

    min_val = getattr(self, "minimum", getattr(self, "min", None))
    max_val = getattr(self, "maximum", getattr(self, "max", None))

    if min_val is None and max_val is None:
        return True

    for idx, val in enumerate(values):
        if val is None:
            continue
        # Ensure the value is comparable
        try:
            if min_val is not None and val < min_val:
                raise ValueError(
                    f"Argument #{idx + 1} value {val} is below the minimum of {min_val}"
                )
            if max_val is not None and val > max_val:
                raise ValueError(
                    f"Argument #{idx + 1} value {val} is above the maximum of {max_val}"
                )
        except TypeError:
            raise TypeError(
                f"Argument #{idx + 1} value {val} is not comparable to the minimum/maximum limits"
            )

    return True

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Determine how to iterate over the arguments.
    # Accept a dict or an iterable of (key, value) tuples.
    if isinstance(args, dict):
        items = args.items()
    else:
        try:
            # Try to interpret args as iterable of tuples
            items = [(k, v) for k, v in args]
        except Exception:
            # single value, use a generic key
            items = [("value", args)]

    # Iterate and check each value against optional min and max attributes.
    for key, value in items:
        try:
            if getattr(self, "min", None) is not None and value < self.min:
                raise ValueError(
                    f"Argument '{key}' with value {value} is below "
                    f"the minimum allowed {self.min}."
                )
            if getattr(self, "max", None) is not None and value > self.max:
                raise ValueError(
                    f"Argument '{key}' with value {value} exceeds "
                    f"the maximum allowed {self.max}."
                )
        except TypeError:
            # Value not comparable to min/max (e.g., non numeric); ignore
            continue

    return True

def validate_min_max_args(self, args):
        """Check if value of arguments is between minimum and maximum values.

        :param args: The received arguments.
        """
        # Determine the numeric value to validate.
        try:
            if hasattr(args, "__len__") and not isinstance(args, (int, float)):
                # Treat as a collection; use its length.
                value = len(args)
            else:
                value = args
        except Exception as exc:
            raise ValueError(f"Unable to determine length/value of args: {exc}") from exc

        # Retrieve min and max bounds if they exist on the instance.
        min_val = getattr(self, "min_args", None)
        max_val = getattr(self, "max_args", None)

        # Perform validation against the bounds.
        if min_val is not None and value < min_val:
            raise ValueError(f"Argument count {value} is less than the minimum allowed {min_val}.")

        if max_val is not None and value > max_val:
            raise ValueError(f"Argument count {value} exceeds the maximum allowed {max_val}.")

        return True

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Validate input types
    if not isinstance(subcommand, str):
        raise TypeError("subcommand must be a string")
    if not isinstance(type_name, str):
        raise TypeError("type_name must be a string")
    if not isinstance(option_name, str):
        raise TypeError("option_name must be a string")
    if not isinstance(spec_option, (dict, list, tuple)):
        raise TypeError("spec_option must be a dict, list, or tuple")

    # Attempt to construct the complex argument type using a pre‑defined class
    try:
        return ComplexArgumentType(subcommand, type_name, option_name,
                                   spec_option)
    except NameError:
        # Fallback: return a plain dictionary representation
        return {'subcommand': subcommand,
                'type_name': type_name,
                'option_name': option_name,
                'spec_option': spec_option}

def get_nested_custom_and_control_args(self, args):
        """Split input arguments to control nested and custom.

        Controls arguments: control the IR behavior. These arguments
            will not be put into the spec yml file
        Nested arguments: are used by the Ansible playbooks and will be put
            into the spec yml file.
        Custom arguments: Custom ansible variables to be used instead of the
            normal nested usage.

        :param args: the collected list of args.
        :return: (dict, dict): flat dicts (control_args, nested_args)
        """
        control_args = {}
        nested_args = {}
        try:
            flat_args = {}
            if args is None:
                flat_args = {}
            elif isinstance(args, dict):
                flat_args = args
            elif isinstance(args, (list, tuple)):
                for item in args:
                    if isinstance(item, dict):
                        flat_args.update(item)
                    elif isinstance(item, (list, tuple)) and len(item) == 2:
                        flat_args[item[0]] = item[1]
                    elif isinstance(item, str):
                        if '=' in item:
                            key, value = item.split('=', 1)
                            flat_args[key] = value
                        else:
                            # Treat lone string as key with True value
                            flat_args[item] = True
                    else:
                        raise ValueError(f"Unsupported argument item type: {type(item)}")
            else:
                raise ValueError(f"Argument must be dict or list/tuple, got {type(args)}")

            for key, value in flat_args.items():
                if isinstance(key, str) and key.startswith('control_'):
                    control_args[key[len('control_') :]] = value
                else:
                    nested_args[key] = value
        except Exception as exc:
            raise ValueError(f"Failed to parse arguments: {exc}") from exc

        return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Prepare result dictionaries
    control_args = {}
    nested_args = {}

    # Normalize input to iterable of key/value pairs
    if args is None:
        return control_args, nested_args

    # Determine the type of args: dict, list/tuple of tuples, or list of args
    if isinstance(args, dict):
        items = list(args.items())
    elif isinstance(args, (list, tuple)):
        # assume list of (key, value) or simple values
        items = []
        for item in args:
            if isinstance(item, (list, tuple)) and len(item) == 2:
                items.append((item[0], item[1]))
            else:
                # treat as value with no key; skip
                continue
    else:
        raise TypeError(f"Unsupported type for args: {type(args)}")

    # Class level sets for control and nested keys, if defined
    control_set = getattr(self, "CONTROL_KEYS", set())
    custom_set = getattr(self, "CUSTOM_KEYS", set())
    nested_set = getattr(self, "NESTED_KEYS", set())

    for key, value in items:
        if not isinstance(key, str):
            # ignore non-string keys or raise
            continue

        # Determine where the key belongs
        if key in control_set or key.lower().startswith("control_"):
            control_args[key] = value
        elif key in custom_set or key.lower().startswith("custom_"):
            # Custom args are treated as nested args; strip the custom_ prefix if needed
            plain_key = key
            if key.lower().startswith("custom_"):
                plain_key = key[7:]
            nested_args[plain_key] = value
        elif key in nested_set or key.lower().startswith("nested_"):
            nested_args[key] = value
        else:
            # Default to nested
            nested_args[key] = value

    return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Helper to determine the group of a key
    CONTROL_PREFIXES = ('control_', 'control.', 'ir_', 'ir.')
    CUSTOM_PREFIXES = ('custom_', 'custom.')

    control_args = {}
    nested_args = {}

    # Handle None
    if args is None:
        return (control_args, nested_args)

    # Ensure args is an iterable of items
    if isinstance(args, dict):
        items = args.items()
    else:
        try:
            iter(args)
            items = args
        except TypeError:
            raise TypeError("args must be a dict or an iterable of key-value pairs")

    for item in items:
        # Determine key, value
        if isinstance(item, dict):
            # If item is a dict, iterate inside
            for k, v in item.items():
                key, val = k, v
                # group determination will happen in the following block
            # Restart the loop for this dict? Handled above
            continue

        if isinstance(item, (list, tuple)):
            if len(item) == 2:
                key, val = item
            else:
                # unexpected tuple/list, skip
                continue
        elif isinstance(item, str):
            if '=' in item:
                key, val = item.split('=', 1)
                val = val.strip()
            else:
                key = item
                val = True
        else:
            # Unsupported item type: skip
            continue

        if not isinstance(key, str):
            # Only string keys processed
            continue

        key_lower = key.lower()

        # Determine if key is control
        if any(key_lower.startswith(prefix) for prefix in CONTROL_PREFIXES):
            # Strip prefix for storing
            for prefix in CONTROL_PREFIXES:
                if key_lower.startswith(prefix):
                    norm_key = key[len(prefix):]
                    break
            control_args[norm_key] = val

        # Determine if key is custom
        elif any(key_lower.startswith(prefix) for prefix in CUSTOM_PREFIXES):
            # Strip prefix for storing
            for prefix in CUSTOM_PREFIXES:
                if key_lower.startswith(prefix):
                    norm_key = key[len(prefix):]
                    break
            nested_args[norm_key] = val

        else:
            # Regular nested argument
            nested_args[key] = val

    return (control_args, nested_args)

def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Prepare the list of keys that should be treated as control arguments.
    # First, try to get an explicit list from the instance if present.
    control_keys = set()
    if hasattr(self, 'CONTROL_ARGS'):
        try:
            control_keys = set(self.CONTROL_ARGS)
        except Exception:
            # ignore, fallback below
            pass

    if not control_keys:
        # Infer control keys by a simple prefix rule (e.g. keys starting with 'control_').
        # When given a dictionary, we can scan its keys. For other types, no inference.
        if isinstance(args, dict):
            control_keys = {k for k in args if isinstance(k, str) and k.startswith('control_')}

    control_args = {}
    nested_args = {}

    def _add_dict(d, dest):
        for k, v in d.items():
            if k in control_keys:
                control_args[k] = v
            else:
                nested_args[k] = v

    if args is None:
        # Empty input is fine; return empty dicts
        return control_args, nested_args

    # If args is already a dictionary, unpack it directly
    if isinstance(args, dict):
        _add_dict(args, nested_args if control_keys else control_args)
    else:
        # Assume iterable of items
        for item in args:
            if isinstance(item, dict):
                _add_dict(item, nested_args if control_keys else control_args)
            elif isinstance(item, (list, tuple)) and len(item) == 2:
                key, value = item
