        if expected_type:
            try:
                values_dict[key] = expected_type(raw_value)
                continue
            except Exception:
                # Fall back to inference if explicit conversion fails
                pass

        # Basic inference based on the string content
        val_str = str(raw_value).strip()

        # Empty string becomes None
        if val_str == "":
            values_dict[key] = None
            continue

        # Boolean conversion
        lowered = val_str.lower()
        if lowered in ("true", "false"):
            values_dict[key] = lowered == "true"
            continue

        # Numeric conversion
        for cast_fn in (int, float):
            try:
                values_dict[key] = cast_fn(val_str)
                break
            except Exception:
                continue
        else:
            # Try JSON or literal evaluation for complex types
            try:
                if val_str[0] in ("[", "{", "("):
                    values_dict[key] = ast.literal_eval(val_str)
                else:
                    values_dict[key] = json.loads(val_str)
            except Exception:
                # Leave as string if all conversions fail
                values_dict[key] = val_str
    # values_dict is modified in place; no return value needed.

