    # Helper to attempt conversion according to Python builtins
    def _try_convert(value):
        """Attempt to convert a string to int, float, bool, or leave as is."""
        if value is None:
            return None

        # Empty string -> keep as empty string
        if isinstance(value, str) and value.strip() == '':
            return value

        # Handle explicit integer
        try:
            return int(value)
        except (ValueError, TypeError):
            pass

        # Handle floating point
        try:
            return float(value)
        except (ValueError, TypeError):
            pass

        # Handle booleans
        if isinstance(value, str):
            low = value.lower()
            if low in ('true', 'false'):
                return low == 'true'
            if low in ('1', '0'):
                return low == '1'

        # Return the original value unchanged
        return value

    # If the calling context provides a mapping of expected types, use it
    expected_types = getattr(self, 'argtypes', None)
    if expected_types and isinstance(expected_types, dict):
        try:
            type_map = expected_types.get(parser_name, {})
