        # Use explicit type if known
        if expected_types and isinstance(expected_types, dict):
            try:
                tgt_type = type_map.get(key)
                if tgt_type:
                    try:
                        values_dict[key] = tgt_type(val)
                        continue
                    except Exception:
                        # Failed to cast with expected type; fall back
                        pass
            except Exception:
                pass

        # Generic conversion
        values_dict[key] = _try_convert(val)

