    # Find spec file (JSON or YAML)
    spec_files = ["plugin.json", "spec.json", "plugin.yaml", "plugin.yml"]
    spec_path = None
    for filename in spec_files:
        candidate = os.path.join(plugin_dir, filename)
        if os.path.isfile(candidate):
            spec_path = candidate
            break
    if spec_path is None:
        raise FileNotFoundError(
            f"No plugin specification file found in '{plugin_dir}'. "
            f"Expected one of: {', '.join(spec_files)}")

    # Load spec content
    try:
        with open(spec_path, "r", encoding="utf-8") as fp:
            if spec_path.endswith(".json") or spec_path.endswith("spec.json"):
                spec = json.load(fp)
            else:
                if yaml is None:
                    raise RuntimeError("PyYAML not installed, cannot load YAML")
                spec = yaml.safe_load(fp)
    except Exception as exc:
        raise RuntimeError(f"Failed to load plugin spec from '{spec_path}': {exc}") from exc

    if not isinstance(spec, dict):
        raise ValueError("Plugin spec must be a dictionary at the top level")

    # Helper to flatten nested dictionaries
    def _flatten(d, parent_key="", sep="."):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            elif isinstance(v, list):
                # Flatten lists by index
                for idx, item in enumerate(v):
                    list_key = f"{new_key}{sep}{idx}"
                    if isinstance(item, dict):
                        items.update(_flatten(item, list_key, sep=sep))
                    else:
                        items[list_key] = item
            else:
                items[new_key] = v
        return items

    flat_spec = _flatten(spec)
