def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    import os
    import pathlib
    env_var = "CONFIG_PATH"

    # Only inject if it's not already defined
    if env_var in os.environ:
        return  # nothing to do

    # Attempt to find a suitable default path
    default_path = None

    # First, try attributes that may be set on the instance
    for attr in ("config_path", "default_config_path", "config_file"):
        default_path = getattr(self, attr, None)
        if default_path:
            break

    # If no attribute was found, fall back to a config.json in the same folder as this file
    if not default_path:
        try:
            default_path = pathlib.Path(__file__).with_name("config.json")
        except NameError:
            # __file__ may not exist in interactive sessions
            default_path = None

    if default_path is None:
        raise RuntimeError("Unable to locate a default configuration path for injection.")

    # Ensure the path is a string, otherwise convert
    try:
        default_path_str = str(default_path)
    except Exception as exc:
        raise TypeError(f"Configuration path must be convertible to a string, got {type(default_path)}") from exc

    # Finally set the environment variable
    try:
        os.environ[env_var] = default_path_str
    except Exception as exc:
        raise RuntimeError(f"Failed to set environment variable {env_var}: {exc}") from exc

