def extend_cli(self, root_subparsers):
    """Adds the spec cli options to the main entry point.

    :param subparser: the subparser object to extend.
    """
    # Validate the provided subparser object
    try:
        add_parser = root_subparsers.add_parser
    except AttributeError:
        raise TypeError("root_subparsers must support an `add_parser` method") from None

    # Create the spec subparser
    try:
        spec_parser = add_parser("spec", help="Specification related options")
    except Exception as exc:
        raise RuntimeError("Failed to create the 'spec' subparser") from exc

    # Add predefined spec options if present
    options = getattr(self, "spec_cli_options", {})
    if not isinstance(options, dict):
        # If options is not a dict, we silently skip adding options
        return spec_parser

    for flag, cfg in options.items():
        # cfg expected to be a dict with possible keys: help, action, default, type, choices
        if not isinstance(cfg, dict):
            continue
        help_text = cfg.get("help", "")
        action = cfg.get("action")
        default = cfg.get("default")
        opt_type = cfg.get("type")
        choices = cfg.get("choices")

        kwargs = {"help": help_text}
        if action:
            kwargs["action"] = action
        if default is not None:
            kwargs["default"] = default
        if opt_type is not None:
            kwargs["type"] = opt_type
        if choices is not None:
            kwargs["choices"] = choices

        try:
            spec_parser.add_argument(flag, **kwargs)
        except Exception:
            # Skip invalid options but keep building the parser
            continue

    return spec_parser

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both 'path' and 'root' must be strings.")
    if not path.startswith(root):
        raise ValueError(f"Root '{root}' not found in path '{path}'.")
    stripped = path[len(root):]
    # Remove any leading path separators
    while stripped and stripped[0] in ('/', '\\'):
        stripped = stripped[1:]
    return stripped

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    # Normalize separators to forward slash for simplicity
    path_norm = path.replace("\\", "/")
    root_norm = root.replace("\\", "/")

    # Handle the special case where the root is just "/"
    if root_norm == "/":
        if not path_norm.startswith("/"):
            raise ValueError(f"Root '/ ' is not a prefix of path '{path}'")
        stripped = path_norm[1:]  # remove leading slash
        return stripped

    # Strip trailing slashes (except keep a leading slash if present)
    if root_norm.endswith("/"):
        root_norm = root_norm.rstrip("/")
    if path_norm.endswith("/"):
        path_norm = path_norm.rstrip("/")

    # Ensure root has a trailing slash for prefix comparison
    root_prefix = root_norm + "/"

    if path_norm.startswith(root_prefix):
        stripped = path_norm[len(root_prefix):]
        return stripped
    else:
        raise ValueError(f"Root '{root}' is not a prefix of path '{path}'")

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    import os
    if not root:
        raise ValueError("Root path cannot be empty")
    norm_root = os.path.normpath(root)
    norm_path = os.path.normpath(path)
    if not norm_path.startswith(norm_root):
        raise ValueError(f'Path "{path}" does not start with root "{root}"')
    rel = norm_path[len(norm_root):]
    if rel.startswith(os.sep):
        rel = rel[len(os.sep):]
    return rel

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    import os
    if not root:
        raise ValueError("Root must not be empty")
    norm_path = os.path.normpath(path)
    norm_root = os.path.normpath(root)
    try:
        common = os.path.commonpath([norm_path, norm_root])
    except ValueError:
        # Different drives or invalid paths
        raise ValueError(f"Root '{root}' is not a prefix of path '{path}'")
    if common != norm_root:
        raise ValueError(f"Root '{root}' is not a prefix of path '{path}'")
    rel = os.path.relpath(norm_path, norm_root)
    return "" if rel == "." else rel
